import React, { useEffect, useRef, useState, Suspense } from 'react';
import { createPortal } from 'react-dom';

import { AnimatePresence, motion } from 'framer-motion';

import { useOnboarding } from '../../contexts/OnboardingContext';
// Utility to check if a string is non-empty
const isNonEmptyString = (value: unknown): value is string => {
  return typeof value === 'string' && value.trim() !== '';
};

import { OnboardingHighlight } from './OnboardingHighlight';
import { OnboardingProgress } from './OnboardingProgress';
import { OnboardingTooltip } from './OnboardingTooltip';

interface HighlightPosition {
  top: number;
  left: number;
  width: number;
  height: number;
}

// Loading fallback for lazy components
const OnboardingLoadingFallback = (): React.ReactElement => (
  <div className="fixed inset-0 z-[9999] bg-black/50 flex items-center justify-center">
    <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500" />
  </div>
);

export function OnboardingFlowOptimized(): React.ReactElement | null {
  const {
    isOnboardingActive,
    currentStep,
    progress,
    nextStep,
    previousStep,
    skipOnboarding,
    canGoBack,
    canGoForward,
    state,
  } = useOnboarding();

  const [highlightPosition, setHighlightPosition] = useState<HighlightPosition | null>(null);
  const [tooltipPosition, setTooltipPosition] = useState({ top: 0, left: 0 });
  const overlayRef = useRef<HTMLDivElement>(null);

  // Update highlight position when step changes
  useEffect(() => {
    if (!currentStep) {
      setHighlightPosition(null);
      return;
    }

    if (!isNonEmptyString(currentStep.targetElement)) {
      setHighlightPosition(null);
      return;
    }

    const updatePosition = (): void => {
      // currentStep is guaranteed to be non-null here due to the early return above
      if (!isNonEmptyString(currentStep.targetElement)) {
        setHighlightPosition(null);
        return;
      }

      const element = document.querySelector(currentStep.targetElement);
      if (!element) {
        setHighlightPosition(null);
        return;
      }

      const rect = element.getBoundingClientRect();
      const padding = currentStep.highlightPadding ?? 8;

      setHighlightPosition({
        top: rect.top - padding + window.scrollY,
        left: rect.left - padding + window.scrollX,
        width: rect.width + padding * 2,
        height: rect.height + padding * 2,
      });

      // Calculate tooltip position
      const tooltipWidth = 400;
      const tooltipHeight = 200;
      let top = rect.top + window.scrollY;
      let left = rect.left + window.scrollX;

      switch (currentStep.position) {
        case 'top':
          top -= tooltipHeight + 20;
          left += rect.width / 2 - tooltipWidth / 2;
          break;
        case 'bottom':
          top += rect.height + 20;
          left += rect.width / 2 - tooltipWidth / 2;
          break;
        case 'left':
          top += rect.height / 2 - tooltipHeight / 2;
          left -= tooltipWidth + 20;
          break;
        case 'right':
          top += rect.height / 2 - tooltipHeight / 2;
          left += rect.width + 20;
          break;
        default:
          // Center
          top = window.innerHeight / 2 - tooltipHeight / 2 + window.scrollY;
          left = window.innerWidth / 2 - tooltipWidth / 2 + window.scrollX;
      }

      // Keep tooltip within viewport
      const viewportPadding = 20;
      left = Math.max(
        viewportPadding,
        Math.min(left, window.innerWidth - tooltipWidth - viewportPadding),
      );
      top = Math.max(viewportPadding + window.scrollY, top);

      setTooltipPosition({ top, left });
    };

    updatePosition();

    // Update on scroll or resize
    window.addEventListener('scroll', updatePosition);
    window.addEventListener('resize', updatePosition);

    return () => {
      window.removeEventListener('scroll', updatePosition);
      window.removeEventListener('resize', updatePosition);
    };
  }, [currentStep]);

  // Handle element click if required
  useEffect(() => {
    if (!currentStep) {
      return;
    }

    if ((currentStep.targetElement === undefined || currentStep.targetElement === '') || currentStep.requiresAction !== true) {
      return;
    }

    const handleClick = (e: MouseEvent): void => {
      // currentStep is guaranteed to be non-null here due to the early return above
      if (currentStep.targetElement === undefined || currentStep.targetElement === '') {
        return;
      }
      const element = document.querySelector(currentStep.targetElement);
      if (element && element.contains(e.target as Node)) {
        nextStep();
      }
    };

    document.addEventListener('click', handleClick);
    return () => {
 document.removeEventListener('click', handleClick); 
};
  }, [currentStep, nextStep]);

  if (!isOnboardingActive || !currentStep) {
return null;
}

  const isCenter = currentStep.position === 'center' || currentStep.targetElement === undefined || currentStep.targetElement === '';

  return createPortal(
    <Suspense fallback={<OnboardingLoadingFallback />}>
      <AnimatePresence>
        <div className="fixed inset-0 z-[9999]" ref={overlayRef}>
          {/* Dark overlay with spotlight */}
          <motion.div
            animate={{ opacity: 1 }}
            className="absolute inset-0 bg-black/50"
            exit={{ opacity: 0 }}
            initial={{ opacity: 0 }}
            onClick={(e) => {
              // Allow clicking through to highlighted element
              if (highlightPosition && currentStep.requiresAction === true) {
                e.stopPropagation();
              }
            }}
          >
            {/* Spotlight cutout */}
            {highlightPosition ? (
              <OnboardingHighlight highlightPosition={highlightPosition} />
            ) : null}
          </motion.div>

          {/* Tooltip */}
          <OnboardingTooltip
            canGoBack={canGoBack}
            canGoForward={canGoForward}
            currentStep={currentStep}
            isCenter={isCenter}
            nextStep={nextStep}
            previousStep={previousStep}
            progress={progress}
            skipOnboarding={skipOnboarding}
            state={state}
            tooltipPosition={tooltipPosition}
          />

          {/* Completion message */}
          {state.currentFlow != null && 
            state.currentFlow.completionMessage != null && state.currentFlow.completionMessage !== '' &&
            state.currentStepIndex === state.currentFlow.steps.length - 1 ? (
              <OnboardingProgress completionMessage={state.currentFlow.completionMessage} />
            ) : null}
        </div>
      </AnimatePresence>
    </Suspense>,
    document.body,
  );
}

/**
 * Express Application Factory
 * Creates and configures the Express application
 */

import { PrismaClient } from '@teaching-engine/database';
import cors from 'cors';
import type { Express, Request, Response, NextFunction } from 'express';
import express, { json, urlencoded } from 'express';

import { errorHandler } from './middleware/errorHandler';
import { router as authEndpoints } from './routes/authEndpoints';
import { userRoutes } from './routes/user';

export function createApp(prisma: PrismaClient): Express {
  const app = express();

  // Middleware
  app.use(
    cors({
      origin: process.env.CLIENT_URL ?? 'http://localhost:5173',
      credentials: true,
    }),
  );
  app.use(json());
  app.use(urlencoded({ extended: true }));

  // Rate limiting is applied at route level, not here

  // Health check
  app.get('/health', (_req: Request, res: Response) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  // Routes
  app.use('/api/auth', authEndpoints);
  app.use('/api/user', userRoutes(prisma));

  // 404 handler
  app.use((_req: Request, res: Response) => {
    res.status(404).json({ error: 'Route not found' });
  });

  // Error handler
  app.use(errorHandler);

  return app;
}

export async function createTestApp(prisma?: PrismaClient): Promise<Express> {
  // Use provided prisma or create a mock
  const testPrisma = prisma ?? new PrismaClient();

  const app = createApp(testPrisma);

  // Add test-specific middleware
  if (process.env.NODE_ENV === 'test') {
    app.use((req: Request, _res: Response, next: NextFunction) => {
      // Mock authentication for testing
      if (req.headers.authorization === 'Bearer valid.jwt.token') {
        req.user = {
          id: 123,
          email: 'test@example.com',
          role: 'teacher',
        };
      } else if (req.headers.authorization === 'Bearer admin.token') {
        req.user = {
          id: 456,
          email: 'admin@example.com',
          role: 'admin',
        };
      }
      next();
    });
  }

  return app;
}

