import type { Request, Response, NextFunction } from 'express';

import { logger } from '../logger.js';

/**
 * Middleware for API key validation
 * Provides security through API key authentication
 */
export function validateApiKey(
  req: Request,
  res: Response,
  next: NextFunction,
): void {
  try {
    // Check if API key validation is enabled
    const isValidationEnabled = process.env.ENABLE_API_KEY_VALIDATION === 'true';

    if (!isValidationEnabled) {
      next(); return;
    }

    // Get the expected API key from environment
    const expectedApiKey = process.env.API_KEY;

    if (!expectedApiKey || expectedApiKey === '') {
      // Server misconfiguration - log error but don't expose details
      logger.error('API_KEY environment variable not set');

      res.status(500).json({
        error: 'Server configuration error',
      });
      return;
    }

    // Extract API key from request headers
    let providedApiKey: string | undefined;

    // Check x-api-key header (case-insensitive)
    // Express automatically lowercases header names
    const xApiKey = req.headers['x-api-key'] as string;
    if (xApiKey) {
      providedApiKey = xApiKey;
    }

    // Check Authorization header with Bearer format
    const authHeader = req.headers.authorization;
    if (authHeader && typeof authHeader === 'string') {
      const bearerMatch = authHeader.match(/^Bearer (.+)$/i);
      if (bearerMatch) {
        providedApiKey = bearerMatch[1];
      }
    }

    // Validate API key
    if (!providedApiKey || providedApiKey.trim() === '') {
      res.status(401).json({
        error: 'Unauthorized: API key is required',
      });
      return;
    }

    // Compare API keys (timing-safe comparison would be better in production)
    if (providedApiKey !== expectedApiKey) {
      res.status(401).json({
        error: 'Unauthorized: Invalid API key',
      });
      return;
    }

    // Cache functionality removed - keeping simple for single-teacher use

    // API key is valid, proceed to next middleware
    next();
  } catch (error: unknown) {
    // Handle unexpected errors
    logger.error(error as string | Record<string, unknown>, 'Authentication error');

    res.status(500).json({
      error: 'Internal server error during authentication',
    });
  }
}

import type { Request, Response, NextFunction } from 'express';

import { logger } from '../logger.js';

export interface AuditLogEntry {
  userId: string;
  action: string;
  resource: string;
  resourceId?: string;
  metadata?: Record<string, unknown>;
  ip?: string;
  userAgent?: string;
  timestamp: Date;
  success: boolean;
  errorMessage?: string;
}

class AuditLogger {
  // Retry configuration for future use
  // private readonly maxRetries = 3;
  // private readonly retryDelay = 1000; // 1 second

  /**
   * Log an audit event
   * Currently logs to application logs only, as AuditLog table is not yet implemented
   */
  log(entry: AuditLogEntry): void {
    // Log to application logs
    if (entry.success) {
      logger.info(
        {
          audit: true,
          ...entry,
        },
        `Audit: ${entry.action} on ${entry.resource}`,
      );
    } else {
      logger.warn(
        {
          audit: true,
          ...entry,
        },
        `Audit: Failed ${entry.action} on ${entry.resource}`,
      );
    }

    // NOTE: Database audit logging can be implemented when AuditLog model is added to schema
    // Future implementation: await prisma.auditLog.create({ data: entry });
  }

  /**
   * Create audit middleware for specific actions
   */
  middleware(action: string, resource: string): (req: Request, res: Response, next: NextFunction) => Promise<void> {
    return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
      const start = Date.now();
      const originalSend = res.send;
      const originalJson = res.json;

      // let _responseData: unknown;
      let success = true;
      let errorMessage: string | undefined;

      // Intercept response
      res.send = function (data: unknown): Response {
        // _responseData = data as Record<string, unknown>;
        if (res.statusCode >= 400) {
          success = false;
          const errorData = data as { error?: string; message?: string };
          errorMessage = typeof data === 'string' ? data : errorData.error ?? errorData.message;
        }
        return originalSend.call(res, data);
      };

      res.json = function (data: unknown): Response {
        // _responseData = data as Record<string, unknown>;
        if (res.statusCode >= 400) {
          success = false;
          const errorData = data as { error?: string; message?: string };
          errorMessage = errorData.error ?? errorData.message;
        }
        return originalJson.call(res, data);
      };

      // Continue with request
      res.on('finish', (): void => {
        const duration = Date.now() - start;

        const entry: AuditLogEntry = {
          userId: req.user?.id.toString() ?? 'anonymous',
          action,
          resource,
          resourceId: req.params.id ?? (req.body as Record<string, unknown>).id as string,
          metadata: {
            method: req.method,
            path: req.path,
            query: req.query,
            body: req.body,
            duration,
            statusCode: res.statusCode,
          },
          ip: req.ip ?? req.socket.remoteAddress,
          userAgent: req.headers['user-agent'],
          timestamp: new Date(),
          success,
          errorMessage,
        };

        // Log asynchronously, don't block response
        try {
          this.log(entry);
        } catch (error: unknown) {
          logger.error({ error: error as Error }, 'Failed to create audit log');
        }
      });

      next();
    };
  }

  /**
   * Log a custom audit event
   */
  logCustom(
    userId: string,
    action: string,
    resource: string,
    options?: {
      resourceId?: string;
      metadata?: Record<string, unknown>;
      success?: boolean;
      errorMessage?: string;
      req?: Request;
    },
  ): void {
    const entry: AuditLogEntry = {
      userId,
      action,
      resource,
      resourceId: options?.resourceId,
      metadata: options?.metadata,
      ip: options?.req?.ip ?? options?.req?.socket.remoteAddress,
      userAgent: options?.req?.headers['user-agent'],
      timestamp: new Date(),
      success: options?.success ?? true,
      errorMessage: options?.errorMessage,
    };

    this.log(entry);
  }
}

