/**
 * Register a new user
 */
export async function register(data: RegistrationData): Promise<{
  user: UserResponse;
  tokens: TokenResponse;
}> {
  // Validate password strength
  const passwordValidation = validatePasswordStrength(data.password);
  if (!passwordValidation.isValid) {
    throw new ValidationError(`Invalid password: ${  passwordValidation.errors.join(', ')}`);
  }

  // Check if user already exists
  const existingUser = await prisma.user.findUnique({
    where: { email: data.email.toLowerCase() },
  });

  if (existingUser) {
    throw new ConflictError('User with this email already exists');
  }

  // Hash password
  const hashedPassword = await hashPassword(data.password);

  // Create user
  const user = await prisma.user.create({
    data: {
      email: data.email.toLowerCase(),
      password: hashedPassword,
      name: data.name,
      role: data.role ?? UserRole.TEACHER,
    },
  });

  logger.info({ userId: user.id, email: user.email }, `New user registered: ${user.email}`);

  // Generate tokens
  const tokens = generateTokenPair({
    id: user.id,
    email: user.email,
    role: user.role,
    organizationId: undefined,
  });

  return {
    user: sanitizeUser(user),
    tokens: {
      ...tokens,
      expiresIn: '24h',
      tokenType: 'Bearer',
    },
  };
}

/**
 * Login with email and password
 */
export async function login(credentials: LoginCredentials): Promise<{
  user: UserResponse;
  tokens: TokenResponse;
}> {
  // Find user
  const user = await prisma.user.findUnique({
    where: { email: credentials.email.toLowerCase() },
  });

  if (!user) {
    throw new AuthenticationError('Invalid credentials');
  }

  // Verify password
  const isValidPassword = await verifyPassword(credentials.password, user.password);
  if (!isValidPassword) {
    throw new AuthenticationError('Invalid credentials');
  }

  // Log last login
  logger.info(
    { userId: user.id, email: user.email },
    `User ${user.email} logged in at ${new Date().toISOString()}`,
  );

  // Generate tokens
  const tokens = generateTokenPair({
    id: user.id,
    email: user.email,
    role: user.role,
    organizationId: undefined,
  });

  return {
    user: sanitizeUser(user),
    tokens: {
      ...tokens,
      expiresIn: '24h',
      tokenType: 'Bearer',
    },
  };
}

