export { caches };

import type { Request, Response, NextFunction } from 'express';
import type { RateLimitRequestHandler } from 'express-rate-limit';

import { logger } from '../logger';

import { authenticate } from './authenticate';
import { apiCache, curriculumCache, staticCache, userCache } from './cache';
import { compose, chain, conditional, timed } from './core/composer';
import { errorLoggingMiddleware, errorHandlerMiddleware, notFoundHandler } from './core/error';
import {
  requestLoggingMiddleware,
  auditMiddleware,
  AuditEventType,
  performanceLoggingMiddleware,
  developmentLoggingMiddleware,
} from './core/logging';
import {
  inputSanitizationMiddleware,
  xssProtectionMiddleware,
  sqlInjectionProtectionMiddleware,
  fileUploadSecurityMiddleware,
  securityMonitoringMiddleware,
} from './core/security';
import { rateLimiters } from './rateLimit';
// Environment checks
const isDevelopment = process.env.NODE_ENV === 'development';
const isProduction = process.env.NODE_ENV === 'production';

// Core middleware chain - applied to all requests
export const coreMiddleware = chain()
  .add(timed('requestLogging', requestLoggingMiddleware))
  .add(securityMonitoringMiddleware)
  .addIf(isDevelopment, developmentLoggingMiddleware)
  .add(inputSanitizationMiddleware)
  .add(xssProtectionMiddleware)
  .addIf(isProduction, sqlInjectionProtectionMiddleware)
  .build();

// API middleware chain - for all API routes
export const apiMiddleware = compose(
  coreMiddleware,
  rateLimiters.api as RateLimitRequestHandler,
  performanceLoggingMiddleware,
);

// Authenticated API chain
export const authenticatedApiMiddleware = compose(apiMiddleware, authenticate);

// Public API chain (no auth required)
export const publicApiMiddleware = compose(
  apiMiddleware,
  conditional(isProduction, rateLimiters.auth as RateLimitRequestHandler),
);

// Write operation chain (POST, PUT, DELETE)
export const writeOperationMiddleware = compose(
  authenticatedApiMiddleware,
  rateLimiters.write as RateLimitRequestHandler,
  auditMiddleware(AuditEventType.PLAN_MODIFICATION, { severity: 'medium' }),
);

// Read operation chain (GET)
export const readOperationMiddleware = compose(
  authenticatedApiMiddleware,
  rateLimiters.read as RateLimitRequestHandler,
  conditional((req): boolean => req.path.includes('/api/curriculum'), curriculumCache),
);

// File upload chain
export const fileUploadMiddleware = (allowedTypes?: string[]): (req: Request, res: Response, next: NextFunction) => void =>
  compose(
    authenticatedApiMiddleware,
    rateLimiters.upload as RateLimitRequestHandler,
    fileUploadSecurityMiddleware(allowedTypes),
    auditMiddleware(AuditEventType.DATA_IMPORT, {
      severity: 'high',
      targetResource: 'file_upload',
    }),
  );

// Auth endpoint chain
export const authEndpointMiddleware = compose(
  coreMiddleware,
  rateLimiters.auth as RateLimitRequestHandler,
  auditMiddleware(AuditEventType.LOGIN_SUCCESS, { severity: 'high' }),
);

// Admin operation chain
export const adminOperationMiddleware = compose(
  authenticatedApiMiddleware,
  (req: Request, res: Response, next: NextFunction): void => {
    if (req.user?.role !== 'admin') {
      res.status(403).json({ error: 'Admin access required' });
      return;
    }
    next();
  },
  auditMiddleware(AuditEventType.SYSTEM_CONFIG_CHANGE, { severity: 'critical' }),
);

// Cached read chain
export const cachedReadMiddleware = (
  cacheType: 'api' | 'curriculum' | 'static' | 'user' = 'api',
): (req: Request, res: Response, next: NextFunction) => void => {
  const cacheMiddleware = {
    api: apiCache,
    curriculum: curriculumCache,
    static: staticCache,
    user: userCache,
  }[cacheType];

  return compose(readOperationMiddleware, cacheMiddleware);
};

// Error handling chain - should be last
export const errorHandlingMiddleware = compose(errorLoggingMiddleware, errorHandlerMiddleware);

// Specific feature chains
export const planningOperationsMiddleware = compose(
  authenticatedApiMiddleware,
  rateLimiters.write as RateLimitRequestHandler,
  userCache,
  auditMiddleware(AuditEventType.PLAN_CREATION, {
    severity: 'low',
    targetResource: 'planning',
  }),
);

export const aiOperationsMiddleware = compose(
  authenticatedApiMiddleware,
  rateLimiters.ai as RateLimitRequestHandler,
  performanceLoggingMiddleware,
  auditMiddleware(AuditEventType.AI_GENERATION, {
    severity: 'medium',
    targetResource: 'ai_generation',
  }),
);

export const exportOperationsMiddleware = compose(
  authenticatedApiMiddleware,
  rateLimiters.read as RateLimitRequestHandler,
  auditMiddleware(AuditEventType.DATA_EXPORT, {
    severity: 'high',
    targetResource: 'data_export',
  }),
);

// Development-only chains
export const developmentMiddleware = conditional(
  isDevelopment,
  compose((_req: Request, _res: Response, next: NextFunction): void => {
    logger.info(`[DEV] ${_req.method} ${_req.path}`);
    next();
  }, performanceLoggingMiddleware),
);

// Health check chain (minimal processing)
export const healthCheckMiddleware = compose(
  rateLimiters.public as RateLimitRequestHandler,
  (_req: Request, res: Response, next: NextFunction): void => {
    res.locals.skipLogging = true;
    next();
  },
);

// Helper to create custom chains
export const createCustomChain = (options: {
  authenticate?: boolean;
  rateLimit?: keyof typeof rateLimiters;
  cache?: boolean;
  audit?: {
    event: AuditEventType;
    severity?: 'low' | 'medium' | 'high' | 'critical';
    resource?: string;
  };
  validators?: ((req: Request, res: Response, next: NextFunction) => void)[];
}): (req: Request, res: Response, next: NextFunction) => void => {
  const chainBuilder = chain().add(coreMiddleware);

  if (options.rateLimit) {
    chainBuilder.add(rateLimiters[options.rateLimit] as RateLimitRequestHandler);
  }

  if (options.authenticate) {
    chainBuilder.add(authenticate);
  }

  if (options.cache) {
    chainBuilder.add(apiCache);
  }

  if (options.audit) {
    chainBuilder.add(
      auditMiddleware(options.audit.event, {
        severity: options.audit.severity,
        targetResource: options.audit.resource,
      }),
    );
  }

  if (options.validators) {
    options.validators.forEach((validator): void => chainBuilder.add(validator));
  }

  return chainBuilder.build();
};

// Export commonly used combinations
export const middleware = {
  // Core chains
  core: coreMiddleware,
  api: apiMiddleware,
  authenticated: authenticatedApiMiddleware,
  public: publicApiMiddleware,

  // Operation chains
  read: readOperationMiddleware,
  write: writeOperationMiddleware,
  upload: fileUploadMiddleware,

  // Feature chains
  auth: authEndpointMiddleware,
  admin: adminOperationMiddleware,
  planning: planningOperationsMiddleware,
  ai: aiOperationsMiddleware,
  export: exportOperationsMiddleware,

  // Utility chains
  cached: cachedReadMiddleware,
  health: healthCheckMiddleware,
  development: developmentMiddleware,

  // Error handling (use last)
  errorHandling: errorHandlingMiddleware,
  notFound: notFoundHandler,

  // Chain builder
  custom: createCustomChain,
};

/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unused-vars */
import type { Request, Response, NextFunction, RequestHandler } from 'express';

import { logger } from '../../logger';

// Middleware type
export type Middleware = RequestHandler | ErrorRequestHandler;

// Error-handling middleware type
export type ErrorRequestHandler = (
  err: Error,
  req: Request,
  res: Response,
  next: NextFunction
) => void | Promise<void>;

// Compose multiple middleware into a single middleware
export const compose = (...middlewares: Middleware[]): RequestHandler => async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    let index = 0;

    const dispatch = async (err?: Error): Promise<void> => {
      if (err !== null && err !== undefined) {
        next(err); return;
      }

      if (index >= middlewares.length) {
        next(); return;
      }

      const middleware = middlewares[index++];

      try {
        // Check if it's an _error-handling middleware (4 parameters)
        if (middleware.length === 4) {
          // Skip _error handlers in normal flow
          return dispatch();
        }

        // Regular middleware
        await (middleware as RequestHandler)(req, res, (err?: unknown) => {
          if (err && typeof err === 'string') {
            void dispatch(new Error(err));
          } else {
            void dispatch(err as Error);
          }
        });
      } catch (_error) {
        next(_error);
      }
    };

    await dispatch();
  };

// Conditional middleware - only apply if condition is met
export const conditional = (
  condition: boolean | ((req: Request) => boolean),
  middleware: Middleware
): RequestHandler => (req: Request, res: Response, next: NextFunction) => {
    const shouldApply = typeof condition === 'function' ? condition(req) : condition;

    if (shouldApply) {
      (middleware as RequestHandler)(req, res, next); return;
    }

    next();
  };

// Create middleware that only runs once
export const once = (middleware: Middleware): RequestHandler => {
  let hasRun = false;

  return (req: Request, res: Response, next: NextFunction) => {
    if (!hasRun) {
      hasRun = true;
      (middleware as RequestHandler)(req, res, next); return;
    }
    next();
  };
};

// Middleware with timeout
export const withTimeout = (
  middleware: Middleware,
  timeout = 5000
): RequestHandler => async (req: Request, res: Response, next: NextFunction) => {
    let timeoutId: NodeJS.Timeout | null = null;
    let completed = false;

    const timeoutPromise = new Promise<void>((_resolve, reject) => {
      timeoutId = setTimeout(() => {
        if (!completed) {
          reject(new Error(`Middleware timeout after ${timeout}ms`));
        }
      }, timeout);
    });

    const middlewarePromise = new Promise<void>((resolve, reject) => {
      (middleware as RequestHandler)(req, res, (err?: unknown) => {
        completed = true;
        if (timeoutId !== null) {
clearTimeout(timeoutId);
}

        if (err !== null && err !== undefined) {
          reject(err);
        } else {
          resolve();
        }
      });
    });

    try {
      await Promise.race([middlewarePromise, timeoutPromise]);
      next();
    } catch (_error) {
      next(_error as unknown);
    }
  };

// Parallel middleware execution (for independent operations)
export const parallel = (...middlewares: Middleware[]): RequestHandler => async (req: Request, res: Response, next: NextFunction) => {
    const promises = middlewares.map(middleware => new Promise<void>((resolve, reject) => {
        (middleware as RequestHandler)(req, res, (err?: unknown) => {
          if (err !== null && err !== undefined) {
reject(err);
} else {
resolve();
}
        });
      }));

    try {
      await Promise.all(promises);
      next();
    } catch (_error) {
      next(_error as unknown);
    }
  };

// Middleware chain builder for fluent API
export class MiddlewareChain {
  private middlewares: Middleware[] = [];

  add(middleware: Middleware): this {
    this.middlewares.push(middleware);
    return this;
  }

  addIf(condition: boolean | ((req: Request) => boolean), middleware: Middleware): this {
    this.middlewares.push(conditional(condition, middleware));
    return this;
  }

  addParallel(...middlewares: Middleware[]): this {
    this.middlewares.push(parallel(...middlewares));
    return this;
  }

  addWithTimeout(middleware: Middleware, timeout: number): this {
    this.middlewares.push(withTimeout(middleware, timeout));
    return this;
  }

  build(): RequestHandler {
    return compose(...this.middlewares);
  }
}

// Create a new middleware chain
export const chain = (): MiddlewareChain => new MiddlewareChain();

// Middleware _error wrapper
export const asyncMiddleware = (
  fn: (req: Request, res: Response, next: NextFunction) => Promise<void>
): RequestHandler => (req: Request, res: Response, next: NextFunction) => {
    // eslint-disable-next-line promise/no-callback-in-promise
    Promise.resolve(fn(req, res, next)).catch(next);
  };

// Log middleware execution time
export const timed = (name: string, middleware: Middleware): RequestHandler => async (req: Request, res: Response, next: NextFunction) => {
    const start = Date.now();

    const handleNext = (err?: unknown) => {
      const duration = Date.now() - start;

      logger.debug({
        middleware: name,
        duration,
        method: req.method,
        path: req.path,
      }, `Middleware executed: ${name}`);

      if (duration > 100) {
        logger.warn({
          middleware: name,
          duration,
        }, `Slow middleware detected: ${name}`);
      }

      next(err);
    };

    try {
      (middleware as RequestHandler)(req, res, handleNext);
    } catch (_error) {
      handleNext(_error as unknown);
    }
  };

import type { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';

import { logger } from '../../logger';
import { errorCounter } from '../../monitoring/telemetry';
import { errorReportingService } from '../../services/monitoring/errorReportingService';
import { AppError, handleDatabaseError, formatErrorResponse } from '../../utils/errors';

// Extended Express Request with additional properties
interface ExtendedRequest extends Request {
  id?: string;
  user?: {
    id: number;
    email: string;
    role: string;
    organizationId?: number;
    permissions?: string[];
  };
  startTime?: number;
}

// Error logging middleware
export const errorLoggingMiddleware = (
  err: Error | AppError | ZodError,
  req: ExtendedRequest,
  _res: Response,
  next: NextFunction,
): void => {
  // Log error details
  const errorData = {
    error: err,
    method: req.method,
    path: req.path,
    query: req.query,
    body: req.body as unknown,
    userId: req.user?.id,
    requestId: req.id,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    duration: req.startTime !== null && req.startTime !== undefined && req.startTime > 0 ? Date.now() - req.startTime : undefined,
  };

  // Determine log level based on error type and status
  if (err instanceof AppError) {
    if (err.statusCode >= 500) {
      logger.error(errorData, 'Application error');
      // Report server errors to Sentry
      errorReportingService.captureError(err, {
        request: {
          method: req.method,
          path: req.path,
          query: req.query,
          headers: req.headers,
        },
        user: req.user,
        requestId: req.id,
        duration: errorData.duration,
      });
    } else if (err.statusCode >= 400) {
      logger.warn(errorData, 'Client error');
      // Only report client errors that might indicate bugs
      if (err.statusCode !== 404 && err.statusCode !== 401) {
        errorReportingService.captureError(err, {
          request: {
            method: req.method,
            path: req.path,
            query: req.query,
          },
          user: req.user,
          requestId: req.id,
        });
      }
    } else {
      logger.info(errorData, 'Handled error');
    }
  } else if (err instanceof ZodError) {
    logger.warn(errorData, 'Validation error');
    // Don't report validation errors to Sentry unless they're unexpected
  } else {
    logger.error(errorData, 'Unhandled error');
    // Always report unhandled errors
    errorReportingService.captureError(err, {
      request: {
        method: req.method,
        path: req.path,
        query: req.query,
        headers: req.headers,
        body: req.body as unknown,
      },
      user: req.user,
      requestId: req.id,
      duration: errorData.duration,
    });
  }

  // Track error metrics
  const errorType =
    err instanceof AppError
      ? 'app_error'
      : err instanceof ZodError
        ? 'validation_error'
        : 'unhandled_error';

  const statusCode = err instanceof AppError ? err.statusCode.toString() : '500';

  errorCounter.add(1, {
    type: errorType,
    status: statusCode,
    path: req.path,
    method: req.method,
  });

  next(err);
};

// Main error handler middleware
export const errorHandlerMiddleware = (
  err: Error | AppError | ZodError,
  req: ExtendedRequest,
  res: Response,
  next: NextFunction,
): void => {
  // Don't handle if response was already sent
  if (res.headersSent) {
    next(err); return;
  }

  // Handle database errors
  if ('code' in err && typeof err.code === 'string' && err.code.startsWith('P')) {
    err = handleDatabaseError(err);
  }

  // Handle specific error types
  let statusCode = 500;
  let errorResponse;

  if (err instanceof AppError) {
    statusCode = err.statusCode;
    errorResponse = formatErrorResponse(err, req.id);
  } else if (err instanceof ZodError) {
    statusCode = 400;
    errorResponse = formatErrorResponse(err, req.id);
  } else if (err.name === 'UnauthorizedError') {
    statusCode = 401;
    errorResponse = formatErrorResponse(new AppError(401, 'Unauthorized', 'UNAUTHORIZED'), req.id);
  } else if (err.name === 'ValidationError') {
    statusCode = 400;
    errorResponse = formatErrorResponse(
      new AppError(400, err.message || 'Validation failed', 'VALIDATION_ERROR'),
      req.id,
    );
  } else if ('type' in err && err.type === 'entity.too.large') {
    statusCode = 413;
    errorResponse = formatErrorResponse(
      new AppError(413, 'Request entity too large', 'PAYLOAD_TOO_LARGE'),
      req.id,
    );
  } else {
    // Generic error
    const message =
      process.env.NODE_ENV === 'production'
        ? 'An unexpected error occurred'
        : err.message || 'Unknown error';

    errorResponse = formatErrorResponse(
      new AppError(statusCode, message, 'INTERNAL_ERROR'),
      req.id,
    );
  }

  // Send error response
  res.status(statusCode).json(errorResponse);
};

// 404 Not Found handler
export const notFoundHandler = (req: Request, _res: Response, next: NextFunction): void => {
  const error = new AppError(404, `Cannot ${req.method} ${req.path}`, 'NOT_FOUND');
  next(error);
};

// Async error catcher for route handlers
export const catchAsync = (
  fn: (req: Request, res: Response, next: NextFunction) => Promise<void>,
) => (req: Request, res: Response, next: NextFunction): void => {
    // eslint-disable-next-line promise/no-callback-in-promise
    Promise.resolve(fn(req, res, next)).catch(next);
  };

// Error handler for unhandled promise rejections
export const unhandledRejectionHandler = (reason: unknown, promise: Promise<unknown>): void => {
  logger.error(
    {
      reason,
      promise,
      type: 'unhandledRejection',
    },
    'Unhandled Promise Rejection',
  );

  // Report to error service
  errorReportingService.captureError(reason instanceof Error ? reason : new Error(String(reason)), {
    type: 'unhandledRejection',
    promise: String(promise),
  });

  // In production, you might want to gracefully shutdown
  if (process.env.NODE_ENV === 'production') {
    // Give time for logging before exit
    setTimeout(() => {
      process.exit(1);
    }, 1000);
  }
};

// Error handler for uncaught exceptions
export const uncaughtExceptionHandler = (error: Error): void => {
  logger.fatal(
    {
      error,
      type: 'uncaughtException',
    },
    'Uncaught Exception',
  );

  // Report critical error
  errorReportingService.captureError(error, {
    type: 'uncaughtException',
    fatal: true,
  });

  // Exit immediately as the process is in an undefined state
  process.exit(1);
};

// Install global error handlers
export const installGlobalErrorHandlers = (): void => {
  process.on('unhandledRejection', unhandledRejectionHandler);
  process.on('uncaughtException', uncaughtExceptionHandler);

  // Graceful shutdown on SIGTERM
  process.on('SIGTERM', () => {
    logger.info('SIGTERM received, shutting down gracefully');
    process.exit(0);
  });

  // Graceful shutdown on SIGINT
  process.on('SIGINT', () => {
    logger.info('SIGINT received, shutting down gracefully');
    process.exit(0);
  });
};

// Create error boundary middleware for specific routes
export const errorBoundary = (handler: (err: unknown, req: Request, res: Response) => void) => (err: unknown, req: Request, res: Response, next: NextFunction): void => {
    try {
      handler(err, req, res);
    } catch (boundaryError) {
      logger.error({ error: boundaryError, originalError: err }, 'Error boundary failed');
      next(err); // Pass original error
    }
  };

