/* eslint-disable @typescript-eslint/no-explicit-any, @typescript-eslint/no-unused-vars */
import { performance } from 'perf_hooks';

import type { Request, Response, NextFunction } from 'express';

import { logger } from '../logger.js';

// Simple metrics collection without external dependencies
interface MetricData {
  name: string;
  value: number;
  labels: Record<string, string>;
  timestamp: number;
  type: 'counter' | 'gauge' | 'histogram';
}

interface HistogramBucket {
  le: number; // less than or equal to
  count: number;
}

interface HistogramData {
  buckets: HistogramBucket[];
  sum: number;
  count: number;
}

// In-memory metrics store
class MetricsStore {
  private counters = new Map<string, number>();
  private gauges = new Map<string, number>();
  private histograms = new Map<string, HistogramData>();
  private metrics: MetricData[] = [];

  // Default histogram buckets for response times (in milliseconds)
  private readonly defaultBuckets = [
    1,
    5,
    10,
    25,
    50,
    100,
    250,
    500,
    1000,
    2500,
    5000,
    10000,
    Infinity,
  ];

  constructor() {
    // Initialize core metrics
    this.initializeMetrics();
  }

  private initializeMetrics(): void {
    // HTTP metrics
    this.createHistogram('http_request_duration_ms', 'HTTP request duration in milliseconds');
    this.createCounter('http_requests_total', 'Total number of HTTP requests');
    this.createCounter('http_errors_total', 'Total number of HTTP errors');

    // Database metrics
    this.createHistogram('db_query_duration_ms', 'Database query duration in milliseconds');
    this.createCounter('db_queries_total', 'Total number of database queries');
    this.createCounter('db_errors_total', 'Total number of database errors');

    // Cache metrics
    this.createCounter('cache_hits_total', 'Total cache hits');
    this.createCounter('cache_misses_total', 'Total cache misses');
    this.createGauge('cache_size', 'Current cache size');

    // Application metrics
    this.createGauge('active_connections', 'Number of active connections');
    this.createGauge('memory_usage_bytes', 'Memory usage in bytes');
    this.createGauge('cpu_usage_percent', 'CPU usage percentage');
  }

  createCounter(name: string, _help: string): void {
    if (!this.counters.has(name)) {
      this.counters.set(name, 0);
    }
  }

  createGauge(name: string, _help: string): void {
    if (!this.gauges.has(name)) {
      this.gauges.set(name, 0);
    }
  }

  createHistogram(name: string, _help: string, buckets?: number[]): void {
    if (!this.histograms.has(name)) {
      const histogramBuckets = (buckets ?? this.defaultBuckets).map((le) => ({ le, count: 0 }));
      this.histograms.set(name, {
        buckets: histogramBuckets,
        sum: 0,
        count: 0,
      });
    }
  }

  incrementCounter(name: string, labels: Record<string, string> = {}, value = 1): void {
    const current = this.counters.get(name) ?? 0;
    this.counters.set(name, current + value);

    this.recordMetric({
      name,
      value: current + value,
      labels,
      timestamp: Date.now(),
      type: 'counter',
    });
  }

  setGauge(name: string, value: number, labels: Record<string, string> = {}): void {
    this.gauges.set(name, value);

    this.recordMetric({
      name,
      value,
      labels,
      timestamp: Date.now(),
      type: 'gauge',
    });
  }

  observeHistogram(name: string, value: number, labels: Record<string, string> = {}): void {
    const histogram = this.histograms.get(name);
    if (!histogram) {
return;
}

    // Update histogram data
    histogram.sum += value;
    histogram.count += 1;

    // Update buckets
    for (const bucket of histogram.buckets) {
      if (value <= bucket.le) {
        bucket.count += 1;
      }
    }

    this.recordMetric({
      name,
      value,
      labels,
      timestamp: Date.now(),
      type: 'histogram',
    });
  }

  private recordMetric(metric: MetricData): void {
    this.metrics.push(metric);

    // Keep only recent metrics (last 1000 entries to prevent memory issues)
    if (this.metrics.length > 1000) {
      this.metrics = this.metrics.slice(-500);
    }
  }

  getMetrics(): {
    counters: Record<string, number>;
    gauges: Record<string, number>;
    histograms: Record<string, HistogramData>;
    recent: MetricData[];
  } {
    return {
      counters: Object.fromEntries(this.counters),
      gauges: Object.fromEntries(this.gauges),
      histograms: Object.fromEntries(this.histograms),
      recent: this.metrics.slice(-100), // Last 100 metrics
    };
  }

  getPrometheusFormat(): string {
    let output = '';

    // Counters
    this.counters.forEach((value, name) => {
      output += `# TYPE ${name} counter\n`;
      output += `${name} ${value}\n`;
    });

    // Gauges
    this.gauges.forEach((value, name) => {
      output += `# TYPE ${name} gauge\n`;
      output += `${name} ${value}\n`;
    });

    // Histograms
    this.histograms.forEach((data, name) => {
      output += `# TYPE ${name} histogram\n`;

      // Buckets
      for (const bucket of data.buckets) {
        const le = bucket.le === Infinity ? '+Inf' : bucket.le.toString();
        output += `${name}_bucket{le="${le}"} ${bucket.count}\n`;
      }

      // Sum and count
      output += `${name}_sum ${data.sum}\n`;
      output += `${name}_count ${data.count}\n`;
    });

    return output;
  }

  reset(): void {
    this.counters.clear();
    this.gauges.clear();
    this.histograms.clear();
    this.metrics = [];
    this.initializeMetrics();
  }
}

// Global metrics store
export const metricsStore = new MetricsStore();

/**
 * HTTP request metrics middleware
 */
export function httpMetricsMiddleware(req: Request, res: Response, next: NextFunction): void {
  const startTime = performance.now();

  // Increment request counter
  metricsStore.incrementCounter('http_requests_total', {
    method: req.method,
    path: req.path,
    user_agent: req.get('User-Agent')?.substring(0, 50) ?? 'unknown',
  });

  // Override end method to capture response metrics
  const originalEnd = res.end;
  res.end = function (chunk?: unknown, encoding?: unknown): Response {
    const duration = performance.now() - startTime;

    // Record request duration
    metricsStore.observeHistogram('http_request_duration_ms', duration, {
      method: req.method,
      status_code: res.statusCode.toString(),
      path: (req.route as Record<string, unknown>).path as string ?? req.path,
    });

    // Record errors
    if (res.statusCode >= 400) {
      metricsStore.incrementCounter('http_errors_total', {
        method: req.method,
        status_code: res.statusCode.toString(),
        path: (req.route as Record<string, unknown>).path as string ?? req.path,
      });
    }

    // Call original end method
    return originalEnd.call(this, chunk, encoding as BufferEncoding);
  };

  next();
}

/**
 * Database query metrics wrapper
 */
export function recordDatabaseQuery<T>(operation: string, queryFn: () => Promise<T>): Promise<T> {
  const startTime = performance.now();

  metricsStore.incrementCounter('db_queries_total', { operation });

  return queryFn()
    .then((result) => {
      const duration = performance.now() - startTime;
      metricsStore.observeHistogram('db_query_duration_ms', duration, { operation });
      return result;
    })
    .catch((_error) => {
      const duration = performance.now() - startTime;
      metricsStore.observeHistogram('db_query_duration_ms', duration, { operation, error: 'true' });
      metricsStore.incrementCounter('db_errors_total', { operation });
      throw _error;
    });
}

/**
 * Cache metrics helpers
 */
export const cacheMetrics = {
  recordHit: (cacheType: string): void => {
    metricsStore.incrementCounter('cache_hits_total', { cache_type: cacheType });
  },

  recordMiss: (cacheType: string): void => {
    metricsStore.incrementCounter('cache_misses_total', { cache_type: cacheType });
  },

  setCacheSize: (cacheType: string, size: number): void => {
    metricsStore.setGauge('cache_size', size, { cache_type: cacheType });
  },
};

/**
 * System metrics collector
 */
export function collectSystemMetrics(): void {
  try {
    const memoryUsage = process.memoryUsage();
    const cpuUsage = process.cpuUsage();

    // Memory metrics
    metricsStore.setGauge('memory_usage_bytes', memoryUsage.heapUsed, { type: 'heap_used' });
    metricsStore.setGauge('memory_usage_bytes', memoryUsage.heapTotal, { type: 'heap_total' });
    metricsStore.setGauge('memory_usage_bytes', memoryUsage.external, { type: 'external' });
    metricsStore.setGauge('memory_usage_bytes', memoryUsage.rss, { type: 'rss' });

    // CPU metrics (convert microseconds to percentage)
    const cpuPercent = (cpuUsage.user + cpuUsage.system) / 1000000; // Convert to seconds
    metricsStore.setGauge('cpu_usage_percent', cpuPercent);
  } catch (_error: unknown) {
    logger.error('Error collecting system metrics:', _error as string | undefined);
  }
}

/**
 * Start system metrics collection
 */
export function startSystemMetricsCollection(intervalMs = 30000): NodeJS.Timeout {
  // Collect initial metrics
  collectSystemMetrics();

  // Set up periodic collection
  const interval = setInterval(collectSystemMetrics, intervalMs);

  // Cleanup on process exit
  process.on('SIGTERM', () => {
 clearInterval(interval); 
});
  process.on('SIGINT', () => {
 clearInterval(interval); 
});

  logger.info(`System metrics collection started with ${intervalMs}ms interval`);

  return interval;
}

/**
 * Performance monitoring decorator for async functions
 */
export function withMetrics<T extends any[], R>(
  metricName: string,
  labels: Record<string, string> = {},
) {
  return function (_target: unknown, propertyKey: string, descriptor: PropertyDescriptor): PropertyDescriptor {
    const originalMethod = descriptor.value as (...args: T) => Promise<R>;

    descriptor.value = async function (...args: T): Promise<R> {
      const startTime = performance.now();

      try {
        const result = await originalMethod.apply(this, args);
        const duration = performance.now() - startTime;

        metricsStore.observeHistogram(metricName, duration, {
          ...labels,
          method: propertyKey,
          status: 'success',
        });

        return result as R;
      } catch (_error) {
        const duration = performance.now() - startTime;

        metricsStore.observeHistogram(metricName, duration, {
          ...labels,
          method: propertyKey,
          status: 'error',
        });

        throw _error;
      }
    };

    return descriptor;
  };
}

/**
 * Calculate performance percentiles from histogram data
 */
export function calculatePercentiles(
  histogramData: HistogramData,
  percentiles: number[] = [50, 90, 95, 99],
): Record<string, number> {
  const result: Record<string, number> = {};

  for (const p of percentiles) {
    const targetCount = (histogramData.count * p) / 100;
    let cumulativeCount = 0;

    for (const bucket of histogramData.buckets) {
      cumulativeCount += bucket.count;
      if (cumulativeCount >= targetCount) {
        result[`p${p}`] =
          bucket.le === Infinity ? histogramData.sum / histogramData.count : bucket.le;
        break;
      }
    }
  }

  return result;
}

/**
 * Get performance summary
 */
export function getPerformanceSummary(): { http: { totalRequests: number; totalErrors: number; errorRate: number; responseTime: Record<string, number> }; database: { totalQueries: number; totalErrors: number; errorRate: number; queryTime: Record<string, number> }; cache: { totalHits: number; totalMisses: number; hitRate: number }; system: { memoryUsage: number; cpuUsage: number } } {
  const metrics = metricsStore.getMetrics();

  const summary = {
    http: {
      totalRequests: metrics.counters.http_requests_total ?? 0,
      totalErrors: metrics.counters.http_errors_total ?? 0,
      errorRate: 0,
      responseTime: calculatePercentiles(
        metrics.histograms.http_request_duration_ms ?? { buckets: [], sum: 0, count: 0 },
      ),
    },
    database: {
      totalQueries: metrics.counters.db_queries_total ?? 0,
      totalErrors: metrics.counters.db_errors_total ?? 0,
      errorRate: 0,
      queryTime: calculatePercentiles(
        metrics.histograms.db_query_duration_ms ?? { buckets: [], sum: 0, count: 0 },
      ),
    },
    cache: {
      totalHits: metrics.counters.cache_hits_total ?? 0,
      totalMisses: metrics.counters.cache_misses_total ?? 0,
      hitRate: 0,
    },
    system: {
      memoryUsage: metrics.gauges.memory_usage_bytes ?? 0,
      cpuUsage: metrics.gauges.cpu_usage_percent ?? 0,
    },
  };

  // Calculate rates
  if (summary.http.totalRequests > 0) {
    summary.http.errorRate = (summary.http.totalErrors / summary.http.totalRequests) * 100;
  }

  if (summary.database.totalQueries > 0) {
    summary.database.errorRate =
      (summary.database.totalErrors / summary.database.totalQueries) * 100;
  }

  const totalCacheRequests = summary.cache.totalHits + summary.cache.totalMisses;
  if (totalCacheRequests > 0) {
    summary.cache.hitRate = (summary.cache.totalHits / totalCacheRequests) * 100;
  }

  return summary;
}

// Named export for getMetrics function
export const getMetrics = (): ReturnType<typeof metricsStore.getMetrics> => metricsStore.getMetrics();

/**
 * Pagination middleware for list endpoints
 * Automatically adds pagination support to routes
 */

import type { Request, Response, NextFunction, RequestHandler, Router } from 'express';

import { logger } from '../logger';
import type {
  PaginationOptions,
  PaginatedResponse} from '../utils/pagination';
import {
  getPaginationParams,
  createPaginatedResponse,
  setPaginationHeaders,
} from '../utils/pagination';

// Extend Express Request type to include pagination
declare global {
  // eslint-disable-next-line @typescript-eslint/no-namespace
  namespace Express {
    interface Request {
      pagination?: PaginationOptions;
      paginatedResponse?: <T>(data: T[], total: number) => PaginatedResponse<T>;
    }
  }
}

/**
 * Middleware to parse and validate pagination parameters
 */
export function parsePagination(req: Request, res: Response, next: NextFunction): void {
  try {
    // Get and validate pagination params
    const pagination = getPaginationParams(req);

    // Attach to request for use in route handlers
    req.pagination = pagination;

    // Helper function to create paginated response
    req.paginatedResponse = <T>(data: T[], total: number): PaginatedResponse<T> => {
      const response = createPaginatedResponse(
        data,
        {
          page: pagination.page,
          limit: pagination.limit,
          total,
        },
        `${req.protocol}://${req.get('host')}${req.originalUrl.split('?')[0]}`,
      );

      // Set headers
      setPaginationHeaders(res, response.pagination);

      return response;
    };

    next();
  } catch (error: unknown) {
    logger.error('Pagination parsing error:', error as string | undefined);
    res.status(400).json({
      error: 'Invalid pagination parameters',
      details: error instanceof Error ? error.message : 'Unknown error',
    });
  }
}

/**
 * Repository pagination helper
 * Wraps repository methods to automatically handle pagination
 */
export function withPagination<T extends { id: number }>(
  repository: {
    findMany: (options: {
      where?: Record<string, unknown>;
      include?: Record<string, boolean>;
      pagination?: PaginationOptions;
      searchFields?: string[];
    }) => Promise<PaginatedResponse<T>>;
    findManyCursor: (options: {
      where?: Record<string, unknown>;
      include?: Record<string, boolean>;
      cursor?: number;
      limit: number;
    }) => Promise<{ data: T[]; nextCursor?: number }>;
  },
  defaultSearchFields: string[] = [],
): {
  findPaginated: (req: Request, options?: {
    where?: Record<string, unknown>;
    include?: Record<string, boolean>;
    searchFields?: string[];
  }) => Promise<PaginatedResponse<T>>;
  findCursorPaginated: (req: Request, options?: {
    where?: Record<string, unknown>;
    include?: Record<string, boolean>;
  }) => Promise<{ data: T[]; nextCursor?: number }>;
} {
  return {
    async findPaginated(
      req: Request,
      options?: {
        where?: Record<string, unknown>;
        include?: Record<string, boolean>;
        searchFields?: string[];
      },
    ): Promise<PaginatedResponse<T>> {
      const pagination = req.pagination || getPaginationParams(req);

      return repository.findMany({
        where: options?.where,
        include: options?.include,
        pagination,
        searchFields: options?.searchFields ?? defaultSearchFields,
      });
    },

    async findCursorPaginated(
      req: Request,
      options?: {
        where?: Record<string, unknown>;
        include?: Record<string, boolean>;
      },
    ): Promise<{ data: T[]; nextCursor?: number }> {
      const { cursor, limit = '20' } = req.query as { cursor?: string; limit?: string };

      return repository.findManyCursor({
        where: options?.where,
        include: options?.include,
        cursor: cursor !== null && cursor !== undefined && cursor !== '' ? parseInt(cursor) : undefined,
        limit: parseInt(limit),
      });
    },
  };
}

/**
 * Express router wrapper that automatically adds pagination to GET list endpoints
 */

export function paginatedRouter(): Router {
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const express = require('express') as { Router: () => Router };
  const router = express.Router();

  // Store original get method
  const originalGet = router.get.bind(router);

  // Override get method to add pagination middleware
  const extendedRouter = router as Router & {
    get: (path: string, ...handlers: RequestHandler[]) => Router;
  };

  extendedRouter.get = function (path: string, ...handlers: RequestHandler[]): Router {
    // Only add pagination to list endpoints (root or ending with 's')
    if (path === '/' || path.match(/s$/)) {
      return originalGet(path, parsePagination, ...handlers);
    }
    return originalGet(path, ...handlers);
  };

  return router;
}

/**
 * Async handler wrapper with pagination support
 */
export function paginatedHandler<T>(
  handler: (req: Request, pagination: PaginationOptions) => Promise<{ data: T[]; total: number }>,
): (req: Request, res: Response, next: NextFunction) => Promise<void> {
  return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const pagination = req.pagination || getPaginationParams(req);
      const result = await handler(req, pagination);

      const response = createPaginatedResponse(
        result.data,
        {
          page: pagination.page,
          limit: pagination.limit,
          total: result.total,
        },
        `${req.protocol}://${req.get('host')}${req.originalUrl.split('?')[0]}`,
      );

      setPaginationHeaders(res, response.pagination);
      res.json(response);
    } catch (error: unknown) {
      next(error);
    }
  };
}

