/**
 * Performance monitoring for paginated endpoints
 */
export function monitorPagination(metricPrefix: string): (req: Request, res: Response, next: NextFunction) => void {
  return (req: Request, res: Response, next: NextFunction): void => {
    const start = Date.now();
    const pagination = req.pagination || getPaginationParams(req);

    // Monitor response
    res.on('finish', (): void => {
      const duration = Date.now() - start;
      logger.info(
        `Pagination metrics - ${metricPrefix}.pagination: page=${pagination.page} limit=${pagination.limit} duration=${duration}ms status=${res.statusCode}`,
      );

      // Log slow queries
      if (duration > 1000) {
        logger.warn(`Slow paginated query - ${req.path}: ${duration}ms`);
      }
    });

    next();
  };
}

import { randomUUID } from 'crypto';
import { performance } from 'perf_hooks';

import type { Request, Response, NextFunction } from 'express';

// import '../types/express.js';
import { logger } from '../logger.js';

// Extend Request interface to include logger and timing
interface ExtendedRequest extends Request {
  logger: typeof logger;
  requestId: string;
  startTime: number;
  // Allow for additional properties
  [key: string]: unknown;
}

/**
 * Request logging middleware that provides structured logging for all requests
 */
export function requestLoggingMiddleware(req: Request, res: Response, next: NextFunction): void {
  const extendedReq = req as ExtendedRequest;
  // Generate unique request ID
  const requestId = randomUUID();
  const startTime = performance.now();

  // Add request ID and timing to request object
  extendedReq.requestId = requestId;
  extendedReq.startTime = startTime;

  // Create child logger with request context
  extendedReq.logger = logger.child({
    requestId,
    method: extendedReq.method,
    url: extendedReq.url,
    userAgent: extendedReq.get('User-Agent'),
    ip: extendedReq.ip !== null && extendedReq.ip !== undefined && extendedReq.ip !== '' ? extendedReq.ip : extendedReq.connection.remoteAddress,
  });

  // Set request ID in main logger for this request
  logger.setRequestId(requestId);

  // Log incoming request
  extendedReq.logger.apiRequest(extendedReq, {
    query: extendedReq.query,
    body: sanitizeRequestBody(extendedReq.body),
    headers: sanitizeHeaders(extendedReq.headers),
  });

  // Override response methods to log response
  const originalJson = res.json;
  const originalSend = res.send;
  const originalEnd = res.end;

  // Track if response has been logged to avoid duplicates
  let responseLogged = false;

  function logResponse(): void {
    if (responseLogged) {
return;
}
    responseLogged = true;

    const duration = performance.now() - startTime;

    extendedReq.logger.apiResponse(
      extendedReq as Record<string, unknown>,
      res as unknown as Record<string, unknown>,
      duration,
      {
        responseSize: res.get('Content-Length') || 0,
        cacheStatus: res.get('X-Cache') || 'MISS',
      },
    );

    // Log slow requests
    if (duration > 2000) {
      extendedReq.logger.warn(
        {
          slowRequest: true,
          duration,
          threshold: 2000,
        },
        `Slow request detected: ${extendedReq.method} ${extendedReq.url} took ${duration}ms`,
      );
    }

    // Log errors
    if (res.statusCode >= 400) {
      const level = res.statusCode >= 500 ? 'error' : 'warn';
      extendedReq.logger[level](
        {
          errorResponse: true,
          statusCode: res.statusCode,
          duration,
        },
        `Error response: ${extendedReq.method} ${extendedReq.url} - ${res.statusCode}`,
      );
    }
  }

  // Override response methods
  res.json = function (obj: unknown) {
    logResponse();
    return originalJson.call(this, obj);
  };

  res.send = function (body: unknown) {
    logResponse();
    return originalSend.call(this, body);
  };

  res.end = function (this: Response, ...args: unknown[]): Response {
    logResponse();

    // Forward all arguments to original method
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore - Complex Express method signature, let runtime handle it
    return originalEnd.apply(this, args);
  };

  // Handle request completion
  res.on('finish', () => {
    logResponse();
  });

  // Handle request errors
  res.on('error', (error) => {
    extendedReq.logger.error(
      {
        responseError: true,
        error: (error instanceof Error ? error.message : String(error)),
        stack: error.stack,
      },
      `Response error: ${(error instanceof Error ? error.message : String(error))}`,
    );
  });

  next();
}

/**
 * Sanitize request body to remove sensitive information
 */
function sanitizeRequestBody(body: unknown): unknown {
  if (!body || typeof body !== 'object') {
    return body;
  }

  const sanitized = { ...body } as Record<string, unknown>;

  // Remove sensitive fields
  const sensitiveFields = [
    'password',
    'token',
    'secret',
    'apiKey',
    'authorization',
    'jwt',
    'sessionId',
    'cookie',
    'passphrase',
    'privateKey',
  ];

  sensitiveFields.forEach((field) => {
    if (sanitized[field]) {
      sanitized[field] = '[REDACTED]';
    }
  });

  // Recursively sanitize nested objects
  Object.keys(sanitized).forEach((key) => {
    if (typeof sanitized[key] === 'object' && sanitized[key] !== null) {
      sanitized[key] = sanitizeRequestBody(sanitized[key]);
    }
  });

  return sanitized;
}

/**
 * Sanitize headers to remove sensitive information
 */
function sanitizeHeaders(headers: unknown): unknown {
  if (!headers || typeof headers !== 'object') {
    return headers;
  }

  const sanitized = { ...headers } as Record<string, unknown>;

  // Remove or redact sensitive headers
  if (sanitized.authorization) {
    sanitized.authorization = '[REDACTED]';
  }

  if (sanitized.cookie) {
    sanitized.cookie = '[REDACTED]';
  }

  if (sanitized['x-api-key']) {
    sanitized['x-api-key'] = '[REDACTED]';
  }

  // Keep only relevant headers for logging
  const relevantHeaders = [
    'content-type',
    'content-length',
    'user-agent',
    'accept',
    'accept-encoding',
    'accept-language',
    'cache-control',
    'x-requested-with',
    'x-forwarded-for',
    'authorization',
  ];

  const filtered: Record<string, unknown> = {};
  relevantHeaders.forEach((header) => {
    if (sanitized[header]) {
      filtered[header] = sanitized[header];
    }
  });

  return filtered;
}

/**
 * Error logging middleware - catches and logs unhandled errors
 */
export function errorLoggingMiddleware(
  error: Error,
  req: Request,
  _res: Response,
  next: NextFunction,
): void {
  const extendedReq = req as ExtendedRequest;
  const requestLogger = extendedReq.logger || logger;

  requestLogger.error(
    {
      unhandledError: true,
      error: {
        name: error.name,
        message: (error instanceof Error ? error.message : String(error)),
        stack: error.stack,
      },
      request: {
        method: extendedReq.method,
        url: extendedReq.url,
        headers: sanitizeHeaders(extendedReq.headers),
        body: sanitizeRequestBody(extendedReq.body),
      },
    },
    `Unhandled error: ${(error instanceof Error ? error.message : String(error))}`,
  );

  next(error);
}

/**
 * Security event logging helper
 */
export function logSecurityEvent(
  req: Request,
  event: string,
  details: Record<string, unknown> = {},
): void {
  const extendedReq = req as ExtendedRequest;
  const requestLogger = extendedReq.logger || logger;

  requestLogger.security(event, {
    ...details,
    ip: extendedReq.ip || extendedReq.connection.remoteAddress,
    userAgent: extendedReq.get('User-Agent'),
    method: extendedReq.method,
    url: extendedReq.url,
    timestamp: new Date().toISOString(),
  });
}

/**
 * Business operation logging helper
 */
export function logBusinessOperation(
  req: Request,
  operation: string,
  context: Record<string, unknown> = {},
): void {
  const extendedReq = req as ExtendedRequest;
  const requestLogger = extendedReq.logger || logger;

  requestLogger.business(operation, {
    ...context,
    userId: (extendedReq.user as { id?: unknown }).id,
    timestamp: new Date().toISOString(),
  });
}

/**
 * Audit trail logging helper
 */
export function logAuditEvent(
  req: Request,
  operation: string,
  details: Record<string, unknown> = {},
): void {
  const extendedReq = req as ExtendedRequest;
  const requestLogger = extendedReq.logger || logger;

  requestLogger.audit(operation, {
    ...details,
    userId: (extendedReq.user as { id?: unknown }).id,
    ip: extendedReq.ip || extendedReq.connection.remoteAddress,
    timestamp: new Date().toISOString(),
  });
}

import * as cors from 'cors';
import type { Request, Response, NextFunction } from 'express';
import helmet from 'helmet';
import Redis from 'ioredis';
import { RateLimiterMemory, RateLimiterRedis } from 'rate-limiter-flexible';

import { logger } from '../logger.js';

// Security configuration
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS ?? 'http://localhost:5173').split(',');
const UPLOAD_SIZE_LIMIT = parseInt(process.env.UPLOAD_SIZE_LIMIT ?? '10485760'); // 10MB default
const ALLOWED_FILE_TYPES = [
  'application/pdf',
  'text/csv',
  'application/vnd.ms-excel',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
];

/**
 * Configure CORS with strict settings
 */
export const corsOptions: cors.CorsOptions = {
  origin: (origin, callback) => {
    // Allow requests with no origin (mobile apps, Postman)
    if (origin == null || origin === '' || ALLOWED_ORIGINS.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With', 'X-CSRF-Token'],
  exposedHeaders: ['X-Total-Count', 'X-Page-Count'],
  maxAge: 86400, // 24 hours
};

/**
 * Configure security headers with Helmet
 */
export const helmetConfig = helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'", "'unsafe-eval'"], // Allow inline scripts for development
      styleSrc: ["'self'", "'unsafe-inline'", 'https://fonts.googleapis.com'],
      imgSrc: ["'self'", 'data:', 'blob:', 'https:'],
      fontSrc: ["'self'", 'https://fonts.gstatic.com'],
      connectSrc: ["'self'", ...ALLOWED_ORIGINS],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
      workerSrc: ["'self'", 'blob:'],
      formAction: ["'self'"],
      frameAncestors: ["'none'"],
      baseUri: ["'self'"],
      manifestSrc: ["'self'"],
    },
  },
  crossOriginEmbedderPolicy: process.env.NODE_ENV === 'production',
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
});

/**
 * Create rate limiter instance
 */
// Function reserved for future use - exported for potential future use
export function _createRateLimiter(): RateLimiterRedis | RateLimiterMemory {
  // Use Redis in production for distributed rate limiting
  if (process.env.REDIS_URL != null && process.env.REDIS_URL !== '' && process.env.NODE_ENV === 'production') {
    const redis = new Redis(process.env.REDIS_URL);
    return new RateLimiterRedis({
      storeClient: redis,
      keyPrefix: 'rl:',
      points: 100, // Number of requests
      duration: 900, // Per 15 minutes
      blockDuration: 900, // Block for 15 minutes
    });
  }

  // Use memory storage for development/testing
  return new RateLimiterMemory({
    points: process.env.NODE_ENV === 'test' ? 10000 : 100, // Higher limit for tests
    duration: 900, // Per 15 minutes
