/**
 * File upload validation middleware
 */
export function validateFileUpload(allowedTypes: string[] = ALLOWED_FILE_TYPES): (req: Request, res: Response, next: NextFunction) => Response | void {
  return (req: Request, res: Response, next: NextFunction): Response | void => {
    if (req.file == null && req.files == null) {
      next(); 
      return;
    }

    const files = req.file ? [req.file] : Object.values(req.files ?? {}).flat();

    for (const file of files as Express.Multer.File[]) {
      // Check file size
      if (file.size > UPLOAD_SIZE_LIMIT) {
        return res.status(400).json({
          error: 'File Too Large',
          message: `File size exceeds maximum allowed size of ${UPLOAD_SIZE_LIMIT / 1024 / 1024}MB`,
        });
      }

      // Check file type
      if (allowedTypes.includes(file.mimetype) === false) {
        return res.status(400).json({
          error: 'Invalid File Type',
          message: `File type ${file.mimetype} is not allowed. Allowed types: ${allowedTypes.join(', ')}`,
        });
      }

      // Additional security checks
      if (
        file.originalname.includes('..') ||
        file.originalname.includes('/') ||
        file.originalname.includes('\\')
      ) {
        return res.status(400).json({
          error: 'Invalid Filename',
          message: 'Filename contains invalid characters',
        });
      }
    }

    next();
  };
}

/**
 * Security headers middleware for enhanced protection
 */
export function securityHeaders(_req: Request, res: Response, next: NextFunction): void {
  // Set additional security headers not covered by Helmet
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');

  // Remove sensitive headers
  res.removeHeader('X-Powered-By');
  res.removeHeader('Server');

  // Set secure cookie policy
  if (process.env.NODE_ENV === 'production') {
    res.setHeader('Set-Cookie', 'SameSite=Strict; Secure; HttpOnly');
  }

  next();
}

/**
 * Input sanitization middleware
 */
export function sanitizeInput(req: Request, _res: Response, next: NextFunction): void {
  // Sanitize request body
  if (req.body != null && typeof req.body === 'object') {
    sanitizeObject(req.body as Record<string, unknown>);
  }

  // Sanitize query parameters
  if (req.query != null && typeof req.query === 'object') {
    sanitizeObject(req.query);
  }

  // Sanitize params
  if (req.params != null && typeof req.params === 'object') {
    sanitizeObject(req.params);
  }

  next();
}

/**
 * Recursively sanitize object properties
 */
function sanitizeObject(obj: Record<string, unknown>): void {
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      if (typeof obj[key] === 'string') {
        // Remove null bytes
        obj[key] = (obj[key]).replace(/\0/g, '');

        // Trim whitespace
        obj[key] = (obj[key] as string).trim();

        // Remove script tags
        obj[key] = (obj[key] as string).replace(
          /<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi,
          '',
        );

        // Remove event handlers
        obj[key] = (obj[key] as string).replace(/on\w+\s*=\s*["'][^"']*["']/gi, '');
      } else if (typeof obj[key] === 'object' && obj[key] !== null) {
        sanitizeObject(obj[key] as Record<string, unknown>);
      }
    }
  }
}

/**
 * CSRF protection middleware
 */
export function csrfProtection(req: Request, res: Response, next: NextFunction): Response | void {
  // Skip CSRF for GET requests and API endpoints that use JWT
  if (req.method === 'GET' || req.path.startsWith('/api/')) {
    next(); 
    return;
  }

  const token = req.headers['x-csrf-token'] ?? (req.body as Record<string, unknown>)._csrf as string;
  const sessionToken = (req as { session?: { csrfToken?: string } }).session?.csrfToken;

  if (token == null || token === '' || sessionToken == null || sessionToken === '' || token !== sessionToken) {
    return res.status(403).json({
      error: 'Forbidden',
      message: 'Invalid CSRF token',
    });
  }

  next();
}

/**
 * Generate CSRF token for session
 */
export function generateCSRFToken(): string {
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const crypto = require('crypto') as { randomBytes: (size: number) => { toString: (encoding: string) => string } };
  return crypto.randomBytes(32).toString('hex');
}

/**
 * Apply all security middleware
 */
export function applySecurityMiddleware(app: { use: (middleware: unknown) => void }) {
  // Apply Helmet for security headers
  app.use(helmetConfig);

  // Apply CORS
  // Handle both CommonJS and ES module formats for cors
  const corsMiddleware = typeof cors === 'function' 
    ? cors(corsOptions)
    : cors.default != null
      ? cors.default(corsOptions)
      : (cors as unknown as typeof cors.default)(corsOptions);
  app.use(corsMiddleware);

  // Apply custom security headers
  app.use(securityHeaders);

  // Apply input sanitization
  app.use(sanitizeInput);

  // Apply general rate limiting
  // DISABLED FOR SINGLE USER APP - Using new rate limit system instead
  // app.use(rateLimitMiddleware);

  // Log security middleware applied
  logger.info('Security middleware applied successfully');
}

