    condition: async (): Promise<boolean> => {
      try {
        // Check for sudden spikes in user activity
        const now = new Date();
        const fiveMinutesAgo = new Date(now.getTime() - 5 * 60 * 1000);

        const recentActivity = await prisma.daybookEntry.count({
          where: {
