  }

  async findById(id: string): Promise<ETFOLessonPlan | null> {
    try {
      const result = await this.prisma.eTFOLessonPlan.findUnique({
        where: { id },
      });
      return result;
    } catch (error) {
      logger.error('Error finding ETFO lesson plan by id:', error as string | undefined);
      throw error;
    }
  }

  async findByUserId(
    userId: number,
    options?: {
      includeRelations?: boolean;
      skip?: number;
      take?: number;
    },
  ): Promise<ETFOLessonPlanWithRelations[]> {
    try {
      const { includeRelations = false, skip = 0, take = 20 } = options ?? {};

      const plans = await this.prisma.eTFOLessonPlan.findMany({
        where: { userId },
        include: includeRelations
          ? {
              unitPlan: {
                select: {
                  id: true,
                  title: true,
                  longRangePlan: {
                    select: {
                      id: true,
                      title: true,
                      subject: true,
                      grade: true,
                    },
                  },
