export interface UserWithoutPassword {
  id: number;
  email: string;
  name: string;
  role: string;
  preferredLanguage: string;
}

export class UserRepository extends BaseRepository<
  User,
  Prisma.UserCreateInput,
  Prisma.UserUpdateInput
> {
  protected modelDelegate: PrismaModelDelegate<User, Prisma.UserCreateInput, Prisma.UserUpdateInput>;

  constructor(prisma: PrismaClient) {
    super(prisma, 'user');
    this.modelDelegate = prisma.user;
  }

  async findByEmail(email: string): Promise<User | null> {
    try {
      const user = await this.prisma.user.findUnique({
        where: { email: email.toLowerCase() },
      });
      return user;
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error('Error finding user by email:', errorMessage);
      throw error;
    }
  }

  async findByIdWithoutPassword(id: number): Promise<UserWithoutPassword | null> {
    try {
      const user = await this.prisma.user.findUnique({
        where: { id },
        select: {
          id: true,
          email: true,
          name: true,
          role: true,
          preferredLanguage: true,
        },
      });
      return user;
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error('Error finding user by id without password:', errorMessage);
      throw error;
    }
  }

  async createUser(data: {
    email: string;
    password: string;
    name: string;
    role?: string;
  }): Promise<UserWithoutPassword> {
    try {
      const hashedPassword = await hashPassword(data.password);
      const user = await this.prisma.user.create({
        data: {
          email: data.email.toLowerCase(),
          password: hashedPassword,
          name: data.name,
          role: data.role ?? 'teacher',
        },
        select: {
          id: true,
          email: true,
          name: true,
          role: true,
          preferredLanguage: true,
        },
      });
      logger.info(`Created user with email: ${user.email}`);
      return user;
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error('Error creating user:', errorMessage);
      throw error;
    }
  }

  async updatePassword(userId: number, newPassword: string): Promise<void> {
    try {
      const hashedPassword = await hashPassword(newPassword);
      await this.prisma.user.update({
        where: { id: userId },
        data: { password: hashedPassword },
      });
      logger.info(`Updated password for user id: ${String(userId)}`);
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error('Error updating password:', errorMessage);
      throw error;
    }
  }

  async findActiveUsers(pagination?: {
    skip?: number;
    take?: number;
  }): Promise<UserWithoutPassword[]> {
    try {
      const users = await this.prisma.user.findMany({
        select: {
          id: true,
          email: true,
          name: true,
          role: true,
          preferredLanguage: true,
        },
        skip: pagination?.skip,
        take: pagination?.take,
        orderBy: { id: 'desc' },
      });
      return users;
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error('Error finding active users:', errorMessage);
      throw error;
    }
  }

}

import type { PrismaClient } from '@prisma/client';

import { logger } from '../../logger';
import {
  isRepositoryError} from '../../types/repository';
import type {
  PrismaModelDelegate,
  BaseModel,
  FindManyOptions,
  FindFirstOptions,
  CursorPaginationOptions,
  CursorPaginationResult,
} from '../../types/repository';
import type {
  PaginatedResponse} from '../../utils/pagination';
import {
  createPaginatedResponse,
  getPrismaArgs,
  createSearchFilter,
  combineFilters,
  fetchPaginatedData,
} from '../../utils/pagination';

import type { IRepository } from './IRepository';

export abstract class BaseRepository<T extends BaseModel, CreateInput, UpdateInput>
  implements IRepository<T, CreateInput, UpdateInput> {
  protected prisma: PrismaClient;
  protected modelName: string;
  protected abstract modelDelegate: PrismaModelDelegate<T, CreateInput, UpdateInput>;

  constructor(prisma: PrismaClient, modelName: string) {
    this.prisma = prisma;
    this.modelName = modelName;
  }

  // Type-safe model access - subclasses must implement this
  protected get model(): PrismaModelDelegate<T, CreateInput, UpdateInput> {
    return this.modelDelegate;
  }

  async findById(id: number): Promise<T | null> {
    try {
      const result = await this.model.findUnique({
        where: { id },
      });
      return result;
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error(`Error finding ${this.modelName} by id:`, errorMessage);
      throw error;
    }
  }

  async findMany(options?: FindManyOptions): Promise<PaginatedResponse<T>> {
    try {
      const {
        where = {},
        include = {},
        pagination = { page: 1, limit: 20 },
        searchFields = [],
      } = options ?? {};

      // Build search filter if search term provided
      const searchFilter = createSearchFilter(pagination.search, searchFields);
      const combinedWhere = combineFilters(where, searchFilter);

      // Get Prisma args for pagination
      const prismaArgs = getPrismaArgs(pagination);

      // Fetch data and count in parallel
      const { data, total } = await fetchPaginatedData(
        () => this.model.count({ where: combinedWhere }),
        () =>
          this.model.findMany({
            where: combinedWhere,
            include,
            ...prismaArgs,
          }),
        pagination,
      );

      return createPaginatedResponse(data, {
        page: pagination.page,
        limit: pagination.limit,
        total,
      });
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error(`Error finding many ${this.modelName}:`, errorMessage);
      throw error;
    }
  }

  async findFirst(options?: FindFirstOptions): Promise<T | null> {
    try {
      const { where = {}, include = {} } = options || {};
      const result = await this.model.findFirst({
        where,
        include,
      });
      return result;
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error(`Error finding first ${this.modelName}:`, errorMessage);
      throw error;
    }
  }

  async create(data: CreateInput): Promise<T> {
    try {
      const result = await this.model.create({
        data,
      });
      logger.info(`Created ${this.modelName} with id: ${String(result.id)}`);
      return result;
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error(`Error creating ${this.modelName}:`, errorMessage);
      throw error;
    }
  }

  async update(id: number, data: UpdateInput): Promise<T> {
    try {
      const result = await this.model.update({
        where: { id },
        data,
      });
      logger.info(`Updated ${this.modelName} with id: ${String(id)}`);
      return result;
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error(`Error updating ${this.modelName}:`, errorMessage);
      throw error;
    }
  }

  async delete(id: number): Promise<T> {
    try {
      const result = await this.model.delete({
        where: { id },
      });
      logger.info(`Deleted ${this.modelName} with id: ${String(id)}`);
      return result;
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error(`Error deleting ${this.modelName}:`, errorMessage);
      throw error;
    }
  }

  async count(where?: Record<string, unknown>): Promise<number> {
    try {
      const result = await this.model.count({ where });
      return result;
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error(`Error counting ${this.modelName}:`, errorMessage);
      throw error;
    }
  }

  async exists(id: number): Promise<boolean> {
    try {
      const count = await this.model.count({
        where: { id },
      });
      return count > 0;
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error(`Error checking existence of ${this.modelName}:`, errorMessage);
      throw error;
    }
  }

  // Transaction support
  async transaction<R>(
    fn: (
      tx: Omit<
        PrismaClient,
        '$connect' | '$disconnect' | '$on' | '$transaction' | '$use' | '$extends'
      >,
    ) => Promise<R>,
  ): Promise<R> {
    return this.prisma.$transaction(fn);
  }

  // Cursor-based pagination for real-time data
  async findManyCursor(options?: CursorPaginationOptions): Promise<CursorPaginationResult<T>> {
    try {
      const {
        where = {},
        include = {},
        cursor,
        limit = 20,
        orderBy = { id: 'desc' },
      } = options ?? {};

      const queryArgs: {
        where: Record<string, unknown>;
        include: Record<string, boolean>;
        take: number;
        orderBy: Record<string, 'asc' | 'desc'>;
        cursor?: { id: number };
        skip?: number;
      } = {
        where,
        include,
        take: limit + 1, // Fetch one extra to check if there's more
        orderBy,
      };

      if (cursor) {
        queryArgs.cursor = { id: cursor };
        queryArgs.skip = 1; // Skip the cursor item
      }

      const items = await this.model.findMany(queryArgs);

      let nextCursor: number | undefined;
      if (items.length > limit) {
        const nextItem = items.pop();
        if (nextItem) {
          nextCursor = nextItem.id;
        }
      }

      return {
        data: items,
        nextCursor,
      };
    } catch (error: unknown) {
      const errorMessage = isRepositoryError(error) ? error.message : String(error);
      logger.error(`Error finding many with cursor ${this.modelName}:`, errorMessage);
      throw error;
    }
  }
}

import type { PaginationOptions, PaginatedResponse } from '../../utils/pagination';

export interface IRepository<T, CreateInput, UpdateInput> {
  findById(id: number): Promise<T | null>;
  findMany(options?: {
    where?: Record<string, unknown>;
    include?: Record<string, boolean>;
    pagination?: PaginationOptions;
    searchFields?: string[];
  }): Promise<PaginatedResponse<T>>;
  findFirst(options?: {
    where?: Record<string, unknown>;
    include?: Record<string, boolean>;
  }): Promise<T | null>;
  create(data: CreateInput): Promise<T>;
  update(id: number, data: UpdateInput): Promise<T>;
  delete(id: number): Promise<T>;
  count(where?: Record<string, unknown>): Promise<number>;
  exists(id: number): Promise<boolean>;
  findManyCursor(options?: {
    where?: Record<string, unknown>;
    include?: Record<string, boolean>;
    cursor?: number;
    limit?: number;
    orderBy?: Record<string, 'asc' | 'desc'>;
  }): Promise<{ data: T[]; nextCursor?: number }>;
}

