    if (updateData.isSubFriendly !== undefined) {
baseUpdateData.isSubFriendly = updateData.isSubFriendly;
}
    if (updateData.subNotes !== undefined) {
baseUpdateData.subNotes = updateData.subNotes;
}

    // Handle date conversion
    if (data.date && data.date !== '') {
      baseUpdateData.date = new Date(data.date);
    }

    // Handle expectations relationship if provided
    const updateInput =
      expectationIds !== undefined && Array.isArray(expectationIds)
        ? {
            ...baseUpdateData,
            expectations: {
              deleteMany: {},
              create: expectationIds.map((expectationId: unknown) => ({
                expectationId: String(expectationId),
              })),
            },
          }
        : baseUpdateData;

    return prisma.eTFOLessonPlan.update({
      where: { id },
      data: updateInput,
      include: {
        expectations: {
          include: {
            expectation: true,
          },
        },
      },
    });
  }

  async delete(id: string, userId: number): Promise<boolean> {
    const lessonPlan = await prisma.eTFOLessonPlan.findFirst({
      where: { id, userId },
    });

    if (!lessonPlan) {
      return false;
    }

    await prisma.eTFOLessonPlan.delete({
      where: { id },
    });

    return true;
  }

  async addResource(
    lessonPlanId: string,
    resourceData: { url?: string; title: string; type: string; content?: string },
    userId: number,
  ) {
    // Verify ownership
    const lessonPlan = await prisma.eTFOLessonPlan.findFirst({
      where: { id: lessonPlanId, userId },
    });

    if (!lessonPlan) {
      throw new Error('Lesson plan not found or access denied');
    }

    // Map resource data to match Prisma schema
    const createData = {
      lessonPlanId,
      title: resourceData.title,
      type: resourceData.type,
      url: resourceData.url,
      content: resourceData.content,
    };

    return prisma.eTFOLessonPlanResource.create({
      data: createData,
    });
  }

  async removeResource(lessonPlanId: string, resourceId: string, userId: number): Promise<boolean> {
    // Verify ownership through lesson plan
    const resource = await prisma.eTFOLessonPlanResource.findFirst({
      where: {
        id: resourceId,
        lessonPlan: {
          id: lessonPlanId,
          userId,
        },
      },
    });

    if (!resource) {
      return false;
    }

    await prisma.eTFOLessonPlanResource.delete({
      where: { id: resourceId },
    });

    return true;
  }

  async createSubVersion(lessonPlanId: string, userId: number) {
    const originalLesson = await prisma.eTFOLessonPlan.findFirst({
      where: { id: lessonPlanId, userId },
      include: {
        expectations: true,
        resources: true,
      },
    });

    if (!originalLesson) {
      throw new Error('Lesson plan not found or access denied');
    }

    return prisma.eTFOLessonPlan.create({
      data: {
        title: `${originalLesson.title} (Sub-Friendly)`,
        titleFr: originalLesson.titleFr ? `${originalLesson.titleFr} (Sub-Friendly)` : undefined,
        unitPlanId: originalLesson.unitPlanId,
        userId,
        date: originalLesson.date,
        duration: originalLesson.duration,
        mindsOn: originalLesson.mindsOn,
        mindsOnFr: originalLesson.mindsOnFr,
        action: originalLesson.action,
        actionFr: originalLesson.actionFr,
        consolidation: originalLesson.consolidation,
        consolidationFr: originalLesson.consolidationFr,
        learningGoals: originalLesson.learningGoals,
        learningGoalsFr: originalLesson.learningGoalsFr,
        materials: originalLesson.materials || undefined,
        grouping: originalLesson.grouping,
        accommodations: originalLesson.accommodations || undefined,
        modifications: originalLesson.modifications || undefined,
        extensions: originalLesson.extensions || undefined,
        assessmentType: originalLesson.assessmentType,
        assessmentNotes: originalLesson.assessmentNotes,
        isSubFriendly: true,
        subNotes:
          'Auto-generated substitute-friendly version. Please review and customize as needed.',
        expectations: {
          create: originalLesson.expectations.map((exp: { expectationId: string }) => ({
            expectationId: exp.expectationId,
          })),
        },
        resources: {
          create: originalLesson.resources.map((resource: { title: string; url: string | null; type: string; content: string | null }) => ({
            title: resource.title,
            url: resource.url,
            type: resource.type,
            content: resource.content,
          })),
        },
      },
    });
  }

  async reschedule(
    lessonPlanId: string,
    rescheduleData: { newDate: string | Date; updateRelated?: boolean },
    userId: number,
  ) {
    const { newDate, updateRelated } = rescheduleData;

    const lessonPlan = await prisma.eTFOLessonPlan.findFirst({
      where: { id: lessonPlanId, userId },
    });

    if (!lessonPlan) {
      throw new Error('Lesson plan not found or access denied');
    }

    // Update the lesson plan date
    const updatedLesson = await prisma.eTFOLessonPlan.update({
      where: { id: lessonPlanId },
      data: { date: new Date(newDate) },
    });

    // If requested, update related daybook entries
    if (updateRelated === true) {
      await prisma.daybookEntry.updateMany({
        where: {
          lessonPlanId,
          userId,
        },
        data: {
          date: new Date(newDate),
        },
      });
    }

    return updatedLesson;
  }

  async duplicate(
    duplicateData: {
      lessonPlanId: string;
      unitPlanId: string;
      date?: string | Date;
      title?: string;
    },
    userId: number,
  ) {
    const { lessonPlanId, unitPlanId, date, title } = duplicateData;

    // Verify user owns both the source lesson plan and target unit plan
    const [sourceLessonPlan, targetUnitPlan] = await Promise.all([
      prisma.eTFOLessonPlan.findFirst({
        where: { id: lessonPlanId, userId },
        include: {
          expectations: true,
          resources: true,
        },
      }),
      prisma.unitPlan.findFirst({
        where: {
          id: unitPlanId,
          longRangePlan: { userId },
        },
      }),
    ]);

    if (!sourceLessonPlan || !targetUnitPlan) {
      throw new Error('Source lesson plan or target unit plan not found');
    }

    return prisma.eTFOLessonPlan.create({
      data: {
        title: title || `${sourceLessonPlan.title} (Copy)`,
        titleFr: sourceLessonPlan.titleFr,
        unitPlanId,
        userId,
        date: date ? new Date(date) : sourceLessonPlan.date,
        duration: sourceLessonPlan.duration,
        mindsOn: sourceLessonPlan.mindsOn,
        mindsOnFr: sourceLessonPlan.mindsOnFr,
        action: sourceLessonPlan.action,
        actionFr: sourceLessonPlan.actionFr,
        consolidation: sourceLessonPlan.consolidation,
        consolidationFr: sourceLessonPlan.consolidationFr,
        learningGoals: sourceLessonPlan.learningGoals,
        learningGoalsFr: sourceLessonPlan.learningGoalsFr,
        materials: sourceLessonPlan.materials || undefined,
        grouping: sourceLessonPlan.grouping,
        accommodations: sourceLessonPlan.accommodations || undefined,
        modifications: sourceLessonPlan.modifications || undefined,
        extensions: sourceLessonPlan.extensions || undefined,
        assessmentType: sourceLessonPlan.assessmentType,
        assessmentNotes: sourceLessonPlan.assessmentNotes,
        isSubFriendly: sourceLessonPlan.isSubFriendly,
        subNotes: sourceLessonPlan.subNotes,
        expectations: {
          create: sourceLessonPlan.expectations.map((exp: { expectationId: string }) => ({
            expectationId: exp.expectationId,
          })),
        },
        resources: {
          create: sourceLessonPlan.resources.map((resource: { title: string; url: string | null; type: string; content: string | null }) => ({
            title: resource.title,
            url: resource.url,
            type: resource.type,
            content: resource.content,
          })),
        },
      },
    });
  }
}

export class ETFOLessonPlansRouteHandler extends BaseRouteHandler {
  private lessonPlanService: ETFOLessonPlanService;

  constructor() {
    super({
      routeName: 'etfo-lesson-plans',
      requireAuth: true,
    });
    this.lessonPlanService = new ETFOLessonPlanService();
  }

  protected getService(): BaseService {
    return this.lessonPlanService;
  }

  protected getValidationSchemas() {
    return {
      create: lessonPlanCreateSchema,
      update: lessonPlanUpdateSchema,
      query: lessonPlanQuerySchema,
    };
  }

  protected getCrudOperations(): CrudOperations<unknown> {
    return {
      create: async (data: unknown, userId: number) => this.lessonPlanService.create(data as ETFOLessonPlanCreateData, userId),
      findMany: async (filters: unknown, userId: number) => {
        const result = await this.lessonPlanService.findMany(
          filters as {
            unitPlanId?: number;
            startDate?: Date;
            endDate?: Date;
            isSubFriendly?: boolean;
            assessmentType?: string;
            hasExpectations?: boolean;
            hasAccommodations?: boolean;
            hasTechIntegration?: boolean;
            subjects?: string[];
            resourceTypes?: string[];
            selectedActivityIds?: number[];
            limit?: number;
            offset?: number;
            sort?: string;
            order?: 'asc' | 'desc';
          },
          userId,
        );
        return result.lessonPlans;
      },
      findById: async (id: string, userId: number) => this.lessonPlanService.findById(id, userId),
      update: async (id: string, data: unknown, userId: number) => this.lessonPlanService.update(id, data as ETFOLessonPlanUpdateData, userId),
      delete: async (id: string, userId: number) => this.lessonPlanService.delete(id, userId),
    };
  }

  protected async handleList(
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction,
  ): Promise<void> {
    try {
      const {userId} = req;
      if (!userId) {
        res.status(401).json({ error: 'User not authenticated' });
        return;
      }
      const schemas = this.getValidationSchemas();
      const filters = schemas.query.parse(req.query);

      // Convert string dates to Date objects and fix field names for service
      const { sortBy, sortOrder, startDate, endDate, unitPlanId, ...filterBase } = filters;
      const convertedFilters = {
        ...filterBase,
        ...(startDate && { startDate: new Date(startDate) }),
        ...(endDate && { endDate: new Date(endDate) }),
        ...(unitPlanId && { unitPlanId: parseInt(String(unitPlanId), 10) }),
        // Convert sortBy/sortOrder to sort/order for service
        sort: sortBy,
        order: sortOrder,
      };

      const result = await this.lessonPlanService.findMany(convertedFilters, userId);
      res.json(result);
      return;
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      this.logger.error(`Error in ${this.routeName} list:`, message);
      next(error);
    }
  }

  protected setupCustomRoutes(): void {
    // POST /etfo-lesson-plans/:id/resources
    this.router.post(
      '/:id/resources',
      this.requireAuthentication,
      this.asyncHandler(this.handleAddResource.bind(this)),
    );

    // DELETE /etfo-lesson-plans/:id/resources/:resourceId
    this.router.delete(
      '/:id/resources/:resourceId',
      this.requireAuthentication,
      this.asyncHandler(this.handleRemoveResource.bind(this)),
    );

    // POST /etfo-lesson-plans/:id/sub-version
    this.router.post(
      '/:id/sub-version',
      this.requireAuthentication,
      this.asyncHandler(this.handleCreateSubVersion.bind(this)),
    );

    // PUT /etfo-lesson-plans/:id/reschedule
    this.router.put(
      '/:id/reschedule',
      this.requireAuthentication,
      this.asyncHandler(this.handleReschedule.bind(this)),
    );

    // POST /etfo-lesson-plans/duplicate
    this.router.post(
      '/duplicate',
      this.requireAuthentication,
      this.asyncHandler(this.handleDuplicate.bind(this)),
    );
  }

  private async handleAddResource(
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction,
  ): Promise<void> {
    try {
      const {userId} = req;
      if (!userId) {
        res.status(401).json({ error: 'User not authenticated' });
        return;
      }
      const { id: lessonPlanId } = req.params;
      const resourceData = resourceSchema.parse(req.body);

      const resource = await this.lessonPlanService.addResource(lessonPlanId, resourceData, userId);
      res.status(201).json(resource);
    } catch (_error) {
      this.logger.error('Error adding resource:', _error as string | undefined);
      next(_error); return;
    }
  }

  private async handleRemoveResource(
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction,
  ): Promise<void> {
    try {
      const {userId} = req;
      if (!userId) {
        res.status(401).json({ error: 'User not authenticated' });
        return;
      }
      const { id: lessonPlanId, resourceId } = req.params;

      const success = await this.lessonPlanService.removeResource(lessonPlanId, resourceId, userId);

      if (!success) {
        res.status(404).json({ error: 'Resource not found' });
        return;
      }

      res.status(204).send();
    } catch (_error) {
      this.logger.error('Error removing resource:', _error as string | undefined);
      next(_error); return;
    }
  }

  private async handleCreateSubVersion(
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction,
  ): Promise<void> {
    try {
      const {userId} = req;
      if (!userId) {
        res.status(401).json({ error: 'User not authenticated' });
        return;
      }
      const { id: lessonPlanId } = req.params;

      const subVersion = await this.lessonPlanService.createSubVersion(lessonPlanId, userId);
      res.status(201).json(subVersion);
    } catch (_error) {
      this.logger.error('Error creating sub version:', _error as string | undefined);
      next(_error); return;
    }
  }

  private async handleReschedule(
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction,
  ): Promise<void> {
    try {
      const {userId} = req;
      if (!userId) {
        res.status(401).json({ error: 'User not authenticated' });
        return;
      }
      const { id: lessonPlanId } = req.params;
      const rescheduleData = rescheduleSchema.parse(req.body);

      const rescheduledLesson = await this.lessonPlanService.reschedule(
        lessonPlanId,
        rescheduleData,
        userId,
      );
      res.json(rescheduledLesson);
      return;
    } catch (_error) {
      this.logger.error('Error rescheduling lesson:', _error as string | undefined);
      next(_error); return;
    }
  }

  private async handleDuplicate(
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction,
  ): Promise<void> {
    try {
      const {userId} = req;
      if (!userId) {
        res.status(401).json({ error: 'User not authenticated' });
        return;
      }
      const duplicateData = duplicateSchema.parse(req.body);

      const duplicatedLesson = await this.lessonPlanService.duplicate(duplicateData, userId);
      res.status(201).json(duplicatedLesson);
    } catch (_error) {
      this.logger.error('Error duplicating lesson plan:', _error as string | undefined);
      next(_error); return;
    }
  }
}

/**
 * Substitute Plans Route Handler
 * Extends BaseRouteHandler with substitute plan-specific business logic
 */

import type { Prisma } from '@teaching-engine/database';
import type { Response, NextFunction } from 'express';
import { z } from 'zod';

import { prisma } from '../prisma.js';
import { BaseService } from '../services/base/BaseService.js';
import { SubstitutePlanService } from '../services/index.js';
import type { SubstitutePlanCreateData, SubstitutePlanUpdateData } from '../types/routes.js';

import type { AuthenticatedRequest, CrudOperations } from './base/BaseRouteHandler.js';
import { BaseRouteHandler } from './base/BaseRouteHandler.js';
import { commonValidations } from './base/validation.js';
import { optimizedQueries, queryPerformance } from './optimizations/queryOptimizations.js';

// Substitute plan-specific validation schemas
const scheduleItemSchema = z.object({
  time: z.string().regex(/^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$/, 'Invalid time format (HH:MM)'),
  activity: z.string().min(1).max(500),
  notes: z.string().max(1000).optional(),
  materials: z.array(z.string().max(100)).max(20).optional(),
  location: z.string().max(100).optional(),
});

const routineSchema = z.object({
  category: z.enum(['morning', 'transition', 'dismissal', 'behavior', 'emergency', 'other']),
  title: z.string().min(1).max(200),
  description: z.string().min(1).max(1000),
  timeOfDay: z.string().max(50).optional(),
  priority: z.number().int().min(1).max(10),
});

const emergencyContactSchema = z.object({
  name: z.string().min(1).max(100),
  role: z.string().max(100),
  phone: z.string().regex(/^[\d\s\-()+'". ]+$/, 'Invalid phone number format'),
  extension: z.string().max(10).optional(),
});

const emergencyInfoSchema = z.object({
  evacuationProcedure: z.string().min(1).max(2000),
  lockdownProcedure: z.string().min(1).max(2000),
  emergencyContacts: z.array(emergencyContactSchema).min(1).max(10),
  importantStudentInfo: z
    .array(
      z.object({
        studentName: z.string().min(1).max(100),
        info: z.string().min(1).max(500),
        priority: z.enum(['low', 'medium', 'high']),
      }),
    )
    .max(30)
    .optional(),
});

const generateSubPlanSchema = z.object({
  dateFor: z.string().datetime(),
  title: z.string().max(255).optional(),
  grade: z.number().int().min(1).max(12).optional(),
  subject: z.string().max(100).optional(),
  sourceUnitPlanId: z.string().cuid().optional(),
  sourceLessonPlanIds: z.array(z.string().cuid()).max(10).optional(),
  includeEmergencyInfo: z.boolean().default(true),
  includeClassroomRoutines: z.boolean().default(true),
  customInstructions: z.string().max(2000).optional(),
});

const substitutePlanCreateSchema = z.object({
  title: commonValidations.title,
  dateFor: z.string().datetime(),
  grade: z.number().int().min(1).max(12).optional(),
  subject: z.string().max(100).optional(),
  schedule: z.array(scheduleItemSchema).min(1).max(20),
  classroomRoutines: z.array(routineSchema).max(50),
  emergencyInfo: emergencyInfoSchema,
  customInstructions: z.string().max(2000).optional(),
  isActive: z.boolean().default(true),
});

const substitutePlanUpdateSchema = substitutePlanCreateSchema.partial().omit({ dateFor: true });

const substitutePlanQuerySchema = z.object({
  startDate: z.string().datetime().optional(),
  endDate: z.string().datetime().optional(),
  grade: z.coerce.number().int().min(1).max(12).optional(),
  subject: z.string().optional(),
  isActive: z.coerce.boolean().optional(),
  upcoming: z.coerce.boolean().optional(),
  limit: z.coerce.number().int().min(1).max(100).default(20),
  offset: z.coerce.number().int().min(0).default(0),
  sortBy: z.enum(['dateFor', 'title', 'createdAt', 'grade']).default('dateFor'),
  sortOrder: z.enum(['asc', 'desc']).default('asc'),
});

// Substitute plan service wrapper
class SubstitutePlanServiceWrapper extends BaseService {
  constructor() {
    super('SubstitutePlanServiceWrapper');
  }

  async findMany(
    filters: {
      startDate?: Date;
      endDate?: Date;
      grade?: string;
      subject?: string;
      isActive?: boolean;
      upcoming?: boolean;
      limit?: number;
      offset?: number;
      sortBy?: string;
      sortOrder?: 'asc' | 'desc';
    },
    userId: number,
  ) {
    const {
      startDate,
      endDate,
      grade,
      subject,
      isActive,
      upcoming,
      limit,
      offset,
      sortBy,
      sortOrder,
    } = filters;

    const where: Prisma.SubstitutePlanWhereInput = { userId };

    // Date filtering using optimized range function
    const dateWhere = optimizedQueries.createDateRangeWhere('dateFor', startDate, endDate);
    if (Object.keys(dateWhere).length > 0) {
      Object.assign(where, dateWhere);
    }

    if (grade) {
where.grade = parseInt(String(grade), 10);
}
    if (subject) {
where.subject = { contains: subject };
}
    if (isActive !== undefined) {
where.isActive = isActive;
}

    // Filter for upcoming plans
    if (upcoming) {
      const now = new Date();
      where.dateFor = { gte: now };
      where.isActive = true;
    }

    // Sorting with validation
    const orderBy = queryPerformance.createOptimizedSort(sortBy || 'dateFor', sortOrder || 'asc', [
      'dateFor',
      'title',
      'grade',
      'createdAt',
    ]);

    const result = await queryPerformance.monitorQuery('substitutePlan.findMany', () =>
      optimizedQueries.paginatedQuery(prisma.substitutePlan, where, {
        limit: limit ?? 10,
        offset: offset ?? 0,
        orderBy,
      }),
    );

    const { items: plans, total } = result;

    return {
      plans,
      pagination: {
        total,
        limit: limit ?? 10,
        offset: offset ?? 0,
        hasMore: (offset ?? 0) + (limit ?? 10) < total,
      },
    };
  }

  async findById(id: string, userId: number) {
    return queryPerformance.monitorQuery('substitutePlan.findById', () =>
      prisma.substitutePlan.findFirst({
        where: { id, userId },
      }),
    );
  }

  async create(data: SubstitutePlanCreateData, userId: number) {
    return prisma.substitutePlan.create({
      data: {
        userId,
        title: data.title,
        dateFor: new Date(data.dateFor),
        grade: data.gradeLevel ? parseInt(data.gradeLevel, 10) : null,
        subject: data.subject,
        schedule: data.activities
          ? [{ time: '9:00', activity: data.activities, notes: data.notes }]
          : [],
        classroomRoutines: data.classroomManagement
          ? [{ category: 'other', description: data.classroomManagement }]
          : [],
        emergencyInfo: data.emergencyContacts ? { contacts: data.emergencyContacts } : {},
        lessonPlans: data.objectives
          ? { objectives: data.objectives, materials: data.materials }
          : {},
        behaviorPlan: {},
        studentNotes: {},
        materialsList: data.materials ? { materials: data.materials } : {},
        importantInfo: data.importantNotes ? { notes: data.importantNotes } : undefined,
        isActive: data.isActive ?? true,
      },
    });
  }

  async update(id: string, data: SubstitutePlanUpdateData, userId: number) {
    // Verify ownership
    const plan = await prisma.substitutePlan.findFirst({
      where: { id, userId },
    });

    if (!plan) {
      throw new Error('Substitute plan not found or access denied');
    }

    return prisma.substitutePlan.update({
      where: { id },
      data,
    });
  }

  async delete(id: string, userId: number): Promise<boolean> {
    const plan = await prisma.substitutePlan.findFirst({
      where: { id, userId },
    });

    if (!plan) {
      return false;
    }

    await prisma.substitutePlan.delete({
      where: { id },
    });

    return true;
  }

  async generatePlan(generateData: unknown, _userId: number) {
    return SubstitutePlanService.generate(generateData);
  }

  async deactivatePlan(planId: string, userId: number) {
    const plan = await prisma.substitutePlan.findFirst({
      where: { id: planId, userId },
    });

    if (!plan) {
      throw new Error('Substitute plan not found or access denied');
    }

    return prisma.substitutePlan.update({
      where: { id: planId },
      data: { isActive: false },
    });
  }

  async getStats(userId: number) {
    const [totalPlans, activePlans, upcomingPlans, recentPlans] = await Promise.all([
      prisma.substitutePlan.count({ where: { userId } }),
      prisma.substitutePlan.count({ where: { userId, isActive: true } }),
      prisma.substitutePlan.count({
        where: {
          userId,
          isActive: true,
          dateFor: { gte: new Date() },
        },
      }),
      prisma.substitutePlan.count({
        where: {
          userId,
          createdAt: { gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000) }, // Last 30 days
        },
      }),
    ]);

    return {
      totalPlans,
      activePlans,
      upcomingPlans,
      recentPlans,
    };
  }

  async getUpcomingDates(userId: number, daysAhead = 30) {
    const startDate = new Date();
    const endDate = new Date();
    endDate.setDate(endDate.getDate() + daysAhead);

    const plans = await prisma.substitutePlan.findMany({
      where: {
        userId,
        isActive: true,
        dateFor: {
          gte: startDate,
          lte: endDate,
        },
      },
      select: {
        id: true,
        title: true,
        dateFor: true,
        grade: true,
        subject: true,
      },
      orderBy: { dateFor: 'asc' },
    });

    return plans;
  }
}

export class SubstitutePlansRouteHandler extends BaseRouteHandler {
  private substitutePlanService: SubstitutePlanServiceWrapper;

  constructor() {
    super({
      routeName: 'substitute-plans',
      requireAuth: true,
    });
    this.substitutePlanService = new SubstitutePlanServiceWrapper();
  }

  protected getService(): BaseService {
    return this.substitutePlanService;
  }

  protected getValidationSchemas() {
    return {
      create: substitutePlanCreateSchema,
      update: substitutePlanUpdateSchema,
      query: substitutePlanQuerySchema,
    };
  }

  protected getCrudOperations(): CrudOperations<unknown> {
    return {
      create: async (data: unknown, userId: number) => this.substitutePlanService.create(data as SubstitutePlanCreateData, userId),
      findMany: async (filters: unknown, userId: number) => {
        const result = await this.substitutePlanService.findMany(
          filters as {
            startDate?: Date;
            endDate?: Date;
            grade?: string;
            subject?: string;
            isActive?: boolean;
            upcoming?: boolean;
            limit?: number;
            offset?: number;
            sortBy?: string;
            sortOrder?: 'asc' | 'desc';
          },
          userId,
        );
        return result.plans;
      },
      findById: async (id: string, userId: number) => this.substitutePlanService.findById(id, userId),
      update: async (id: string, data: unknown, userId: number) => this.substitutePlanService.update(id, data as SubstitutePlanUpdateData, userId),
      delete: async (id: string, userId: number) => this.substitutePlanService.delete(id, userId),
    };
  }

  protected async handleList(
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction,
  ): Promise<void> {
    try {
      const {userId} = req;
      if (!userId) {
        res.status(401).json({ error: 'User not authenticated' });
        return;
      }
      const schemas = this.getValidationSchemas();
      const filters = schemas.query.parse(req.query);

      // Convert string dates to Date objects and fix types for service
      const { startDate, endDate, grade, ...filterBase } = filters;
      const convertedFilters = {
        ...filterBase,
        ...(startDate && { startDate: new Date(startDate) }),
        ...(endDate && { endDate: new Date(endDate) }),
        ...(grade && { grade: String(grade) }),
      };

      const result = await this.substitutePlanService.findMany(convertedFilters, userId);
      res.json(result);
      return;
    } catch (_error) {
      this.logger.error(`Error in ${this.routeName} list:`, _error as string | undefined);
      next(_error); return;
    }
  }

  protected setupCustomRoutes(): void {
    // POST /substitute-plans/generate
    this.router.post(
      '/generate',
      this.requireAuthentication,
      this.asyncHandler(this.handleGenerate.bind(this)),
    );

    // POST /substitute-plans/:id/deactivate
    this.router.post(
      '/:id/deactivate',
      this.requireAuthentication,
      this.asyncHandler(this.handleDeactivate.bind(this)),
    );

    // GET /substitute-plans/stats
    this.router.get(
      '/stats',
      this.requireAuthentication,
      this.asyncHandler(this.handleStats.bind(this)),
    );

    // GET /substitute-plans/upcoming-dates
    this.router.get(
      '/upcoming-dates',
      this.requireAuthentication,
      this.asyncHandler(this.handleUpcomingDates.bind(this)),
    );
  }

  private async handleGenerate(
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction,
  ): Promise<void> {
    try {
      const {userId} = req;
      if (!userId) {
        res.status(401).json({ error: 'User not authenticated' });
        return;
      }
      const generateData = generateSubPlanSchema.parse(req.body);

      const generatedPlan = await this.substitutePlanService.generatePlan(generateData, userId);
      res.status(201).json(generatedPlan);
    } catch (_error) {
      this.logger.error('Error generating substitute plan:', _error as string | undefined);
      next(_error); return;
    }
  }

  private async handleDeactivate(
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction,
  ): Promise<void> {
    try {
      const {userId} = req;
      if (!userId) {
        res.status(401).json({ error: 'User not authenticated' });
        return;
      }
      const { id: planId } = req.params;

      const deactivatedPlan = await this.substitutePlanService.deactivatePlan(planId, userId);
      res.json(deactivatedPlan);
      return;
    } catch (_error) {
      this.logger.error('Error deactivating substitute plan:', _error as string | undefined);
      next(_error); return;
    }
  }

  private async handleStats(
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction,
  ): Promise<void> {
    try {
      const {userId} = req;
      if (!userId) {
        res.status(401).json({ error: 'User not authenticated' });
        return;
      }
      const stats = await this.substitutePlanService.getStats(userId);
      res.json(stats);
      return;
    } catch (_error) {
      this.logger.error('Error getting substitute plan stats:', _error as string | undefined);
      next(_error); return;
    }
  }

  private async handleUpcomingDates(
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction,
  ): Promise<void> {
    try {
      const {userId} = req;
      if (!userId) {
        res.status(401).json({ error: 'User not authenticated' });
        return;
      }
      const daysAhead = req.query.days ? parseInt(req.query.days as string, 10) : 30;

      const upcomingDates = await this.substitutePlanService.getUpcomingDates(userId, daysAhead);
      res.json(upcomingDates);
      return;
    } catch (_error) {
      this.logger.error('Error getting upcoming dates:', _error as string | undefined);
      next(_error); return;
    }
  }
}

/**
