/**
 * Shared middleware for routes
 */

import type { Request, Response, NextFunction } from 'express';
import type { ParsedQs } from 'qs';
import { z } from 'zod';

import { logger } from '../../logger';

import { formatValidationError } from './validation.js';

export interface AuthenticatedRequest extends Request {
  userId?: number;
  user?: {
    id: number;
    email: string;
    name?: string;
    role: string;
    organizationId?: number;
    permissions?: string[];
  };
}

/**
 * Authentication middleware
 */
export const requireAuth = (req: AuthenticatedRequest, res: Response, next: NextFunction): void => {
  if (!req.user || !req.user.id) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }
  req.userId = req.user.id;
  next();
};

/**
 * Optional authentication middleware
 */
export const optionalAuth = (
  req: AuthenticatedRequest,
  _res: Response,
  next: NextFunction,
): void => {
  if (req.user && req.user.id) {
    req.userId = req.user.id;
  }
  next();
};

/**
 * Role-based authorization middleware
 */
export const requireRole = (requiredRole: string) => (req: AuthenticatedRequest, res: Response, next: NextFunction): void => {
    if (!req.user || !req.user.role || req.user.role !== requiredRole) {
      res.status(403).json({ error: 'Forbidden: Insufficient permissions' });
      return;
    }
    next();
  };

/**
 * Validation middleware factory
 */
export const validate = <T>(schema: z.ZodSchema<T>) => (req: Request, res: Response, next: NextFunction): void => {
    try {
      const validatedData: T = schema.parse(req.body);
      req.body = validatedData as unknown;
      next();
    } catch (_error) {
      if (_error instanceof z.ZodError) {
        const formattedError = formatValidationError(_error);
        res.status(400).json(formattedError);
        return;
      } 
        logger.error({ error: _error }, 'Validation error');
        res.status(500).json({ error: 'Internal server error' });
        return;

    }
  };

/**
 * Query parameter validation middleware
 */
export const validateQuery = <T>(schema: z.ZodSchema<T>) => (req: Request, res: Response, next: NextFunction): void => {
    try {
      const validatedQuery: T = schema.parse(req.query);
      req.query = validatedQuery as ParsedQs;
      next();
    } catch (_error) {
      if (_error instanceof z.ZodError) {
        const formattedError = formatValidationError(_error);
        res.status(400).json(formattedError);
        return;
      } 
        logger.error({ error: _error }, 'Query validation error');
        res.status(500).json({ error: 'Internal server error' });
        return;

    }
  };

/**
 * Async error handler wrapper
 */
export const asyncHandler = (
  fn: (req: Request, res: Response, next: NextFunction) => Promise<void>,
) => (req: Request, res: Response, next: NextFunction) => {
    // eslint-disable-next-line promise/no-callback-in-promise
    Promise.resolve(fn(req, res, next)).catch(next);
  };

/**
 * Request logging middleware
 */
export const requestLogger = (req: Request, res: Response, next: NextFunction): void => {
  const start = Date.now();
  const originalSend = res.send;

  res.send = function (body) {
    const duration = Date.now() - start;
    logger.info(
      {
        method: req.method,
        url: req.url,
        statusCode: res.statusCode,
        duration: `${duration}ms`,
        userAgent: req.get('User-Agent'),
        ip: req.ip,
      },
      'Request completed',
    );
    return originalSend.call(this, body);
  };

  next();
};

/**
 * Rate limiting middleware factory
 */
export const createRateLimit = (options: { windowMs: number; max: number; message?: string }): ((req: Request, res: Response, next: NextFunction) => void) => {
  const requests = new Map<string, { count: number; resetTime: number }>();

  return (req: Request, res: Response, next: NextFunction): void => {
    const key = req.ip ?? 'unknown';
    const now = Date.now();
    const windowStart = now - options.windowMs;

    // Clean up old entries
    for (const [ip, data] of requests.entries()) {
      if (data.resetTime < windowStart) {
        requests.delete(ip);
      }
    }

    // Get or create entry for this IP
    let entry = requests.get(key);
    if (!entry || entry.resetTime < windowStart) {
      entry = { count: 0, resetTime: now + options.windowMs };
      requests.set(key, entry);
    }

    // Check if limit exceeded
    if (entry.count >= options.max) {
      res.status(429).json({
        error: options.message ?? 'Too many requests',
        retryAfter: Math.ceil((entry.resetTime - now) / 1000),
      });
      return;
    }

    // Increment count
    entry.count++;
    next();
  };
};

/**
 * Input sanitization middleware
 */
export const sanitizeInput = (req: Request, _res: Response, next: NextFunction): void => {
  const sanitizeValue = (value: unknown): unknown => {
    if (typeof value === 'string') {
      // Remove HTML tags, including content within script tags, and normalize whitespace
      return value
        .replace(/<script[^>]*>.*?<\/script>/gi, '') // Remove script tags and their content
        .replace(/<[^>]*>/g, '') // Remove all other HTML tags
        .trim()
        .replace(/\s+/g, ' ');
    }
    if (Array.isArray(value)) {
      return value.map(sanitizeValue);
    }
    if (value && typeof value === 'object') {
      const sanitized: Record<string, unknown> = {};
      for (const [key, val] of Object.entries(value)) {
        sanitized[key] = sanitizeValue(val);
      }
      return sanitized;
    }
    return value;
  };

  if (req.body) {
    req.body = sanitizeValue(req.body);
  }
  if (req.query) {
    req.query = sanitizeValue(req.query) as ParsedQs;
  }

  next();
};

/**
 * Error handling middleware
 */
export const errorHandler = (
  err: Error,
  req: Request,
  res: Response,
  _next: NextFunction,
): void => {
  logger.error(
    {
      error: err.message,
      stack: err.stack,
      method: req.method,
      url: req.url,
      body: req.body,
      query: req.query,
    },
    'Route error',
  );

  // Handle specific error types
  if (err instanceof z.ZodError) {
    const formattedError = formatValidationError(err);
    res.status(400).json(formattedError);
    return;
  }

  // Handle Prisma errors
  if (err.message.includes('Unique constraint')) {
    res.status(409).json({ error: 'Resource already exists' });
    return;
  }

  if (err.message.includes('Foreign key constraint')) {
    res.status(400).json({ error: 'Invalid reference to related resource' });
    return;
  }

  // Default error response
  res.status(500).json({
    error: 'Internal server error',
    ...(process.env.NODE_ENV === 'development' && {
      details: err.message,
      stack: err.stack,
    }),
  });
  return;
};

/**
 * CORS middleware for specific origins
 */
export const corsMiddleware = (allowedOrigins: string[]) => (req: Request, res: Response, next: NextFunction): void => {
    const {origin} = req.headers;
    if (origin && allowedOrigins.includes(origin)) {
      res.setHeader('Access-Control-Allow-Origin', origin);
    }
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
    res.setHeader('Access-Control-Allow-Credentials', 'true');

    if (req.method === 'OPTIONS') {
      res.status(200).end();
      return;
    }

    next();
  };

/**
 * Security headers middleware
 */
export const securityHeaders = (_req: Request, res: Response, next: NextFunction): void => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
};

/**
 * Shared validation utilities for routes
 */

import { z } from 'zod';

/**
 * Common validation patterns used across routes
 */
export const commonValidations = {
  // Basic field validations
  title: z
    .string()
    .min(1, 'Title is required')
    .max(255, 'Title must be 255 characters or less')
    .regex(/^[^<>]*$/, 'Title cannot contain HTML tags'),

  titleFr: z
    .string()
    .max(255, 'French title must be 255 characters or less')
    .regex(/^[^<>]*$/, 'French title cannot contain HTML tags')
    .optional(),

  description: z
    .string()
    .max(2000, 'Description must be 2000 characters or less')
    .optional(),

  descriptionFr: z
    .string()
    .max(2000, 'French description must be 2000 characters or less')
    .optional(),

  // ID validations
  cuidId: z.string().cuid('Invalid ID format'),
  uuid: z.string().uuid('Invalid UUID format'),
  objectId: z.string().regex(/^[0-9a-fA-F]{24}$/, 'Invalid ObjectId format'),

  // Date validations
  dateString: z.string().datetime('Invalid date format'),
  dateRange: z.object({
    startDate: z.string().datetime('Invalid start date format'),
    endDate: z.string().datetime('Invalid end date format')
  }).refine(
    (data) => new Date(data.startDate) < new Date(data.endDate),
    {
      message: 'End date must be after start date',
      path: ['endDate']
    }
  ),

  // Grade validations
  grade: z.number().int().min(1).max(12),
  gradeRange: z.object({
    gradeMin: z.number().int().min(1).max(12).optional(),
    gradeMax: z.number().int().min(1).max(12).optional()
  }).refine(
    (data) => !data.gradeMin || !data.gradeMax || data.gradeMin <= data.gradeMax,
    {
      message: 'Maximum grade must be greater than or equal to minimum grade',
      path: ['gradeMax']
    }
  ),

  // Subject validation
  subject: z.string().max(100, 'Subject must be 100 characters or less').optional(),

  // Array validations
  tags: z.array(z.string().max(50, 'Tag must be 50 characters or less')).max(20, 'Maximum 20 tags allowed').optional(),
  keywords: z.array(z.string().max(50, 'Keyword must be 50 characters or less')).max(20, 'Maximum 20 keywords allowed').optional(),

  // Time validations
  estimatedMinutes: z.number().int().positive('Estimated minutes must be positive').max(480, 'Estimated minutes cannot exceed 480 (8 hours)').optional(),
  estimatedWeeks: z.number().int().positive('Estimated weeks must be positive').max(52, 'Estimated weeks cannot exceed 52').optional(),

  // Enum validations
  planType: z.enum(['UNIT_PLAN', 'LESSON_PLAN']),
  category: z.enum(['BY_SUBJECT', 'BY_GRADE', 'BY_THEME', 'BY_SEASON', 'BY_SKILL', 'CUSTOM']),
  priority: z.enum(['LOW', 'MEDIUM', 'HIGH']),
  status: z.enum(['DRAFT', 'PUBLISHED', 'ARCHIVED']),

  // Pagination
  pagination: z.object({
    limit: z.number().int().min(1).max(100).default(10),
    offset: z.number().int().min(0).default(0),
    sortBy: z.string().optional(),
    sortOrder: z.enum(['asc', 'desc']).default('desc')
  }),

  // Search and filtering
  searchQuery: z.string().max(255).optional(),
  filters: z.object({
    subject: z.string().max(100).optional(),
    grade: z.number().int().min(1).max(12).optional(),
    category: z.string().optional(),
    tags: z.array(z.string()).optional(),
    dateFrom: z.string().datetime().optional(),
    dateTo: z.string().datetime().optional()
  }).optional()
};

/**
 * Common query parameter schemas
 */
export const commonQuerySchemas = {
  // Basic list query
  list: z.object({
    limit: z.coerce.number().int().min(1).max(100).default(10),
    offset: z.coerce.number().int().min(0).default(0),
    sortBy: z.string().optional(),
    sortOrder: z.enum(['asc', 'desc']).default('desc'),
    search: z.string().max(255).optional()
  }),

  // Educational content query
  educational: z.object({
    subject: z.string().max(100).optional(),
    grade: z.coerce.number().int().min(1).max(12).optional(),
    category: z.string().optional(),
    tags: z.union([z.string(), z.array(z.string())]).optional().transform(val => {
      if (!val || val === '') {
return undefined;
}
      if (Array.isArray(val)) {
return val;
}
      // Split comma-separated string into array
      return val.split(',').map(tag => tag.trim()).filter(tag => tag.length > 0);
    })
  }),

  // Date range query
  dateRange: z.object({
    startDate: z.string().datetime().optional(),
    endDate: z.string().datetime().optional()
  })
};

/**
 * Helper function to create validation schemas with common patterns
 */
export const createValidationSchema = {
  /**
   * Create a basic CRUD schema set
   */
  crud: <T extends z.ZodRawShape>(fields: T) => {
    const baseSchema = z.object(fields);
    return {
      create: baseSchema,
      update: baseSchema.partial(),
      query: commonQuerySchemas.list
    };
  },

  /**
   * Create educational content schema set
   */
  educational: <T extends z.ZodRawShape>(fields: T) => {
    const baseObjectSchema = z.object({
      ...fields,
      gradeMin: z.number().int().min(1).max(12).optional(),
      gradeMax: z.number().int().min(1).max(12).optional(),
      subject: commonValidations.subject,
      tags: commonValidations.tags,
      keywords: commonValidations.keywords
    });

    const baseSchema = baseObjectSchema.refine(
      (data) => !data.gradeMin || !data.gradeMax || data.gradeMin <= data.gradeMax,
      {
        message: 'Maximum grade must be greater than or equal to minimum grade',
        path: ['gradeMax']
      }
    );

    return {
      create: baseSchema,
      update: baseObjectSchema.partial(),
      query: commonQuerySchemas.list.merge(commonQuerySchemas.educational)
    };
  },

  /**
   * Create a schema with title and description
   */
  withTitleDescription: <T extends z.ZodRawShape>(fields: T) => {
    const baseSchema = z.object({
      ...fields,
      title: commonValidations.title,
      titleFr: commonValidations.titleFr,
      description: commonValidations.description,
      descriptionFr: commonValidations.descriptionFr
    });
    return {
      create: baseSchema,
      update: baseSchema.partial(),
      query: commonQuerySchemas.list
    };
  }
};

/**
 * Sanitization functions
 */
export const sanitize = {
  /**
   * Remove HTML tags from string
   */
  removeHtmlTags: (input: string): string => input.replace(/<[^>]*>/g, ''),

  /**
   * Trim and normalize whitespace
   */
  normalizeWhitespace: (input: string): string => input.trim().replace(/\s+/g, ' '),

  /**
   * Sanitize array of strings
   */
  stringArray: (input: string[]): string[] => input
      .map(str => {
        // First remove script tags and their content completely
        let cleaned = str.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
        // Then remove any other HTML tags
        cleaned = sanitize.removeHtmlTags(cleaned);
        // Finally normalize whitespace
        return sanitize.normalizeWhitespace(cleaned);
      })
      .filter(str => str.length > 0)
};

/**
 * Validation error formatter
 */
export const formatValidationError = (error: z.ZodError): {
  message: string;
  errors: { field: string; message: string }[];
} => ({
    message: 'Validation failed',
    errors: error.errors.map(err => ({
      field: err.path.join('.'),
      message: err.message
    }))
  });

