      dbStatus = 'unhealthy';
      logger.error('Database health check failed:', _error);
    }

    res.json({
      success: true,
      data: {
        performance: performanceSummary,
        cache: {
          stats: cacheStats,
          hitRateOverall: calculateOverallCacheHitRate(cacheStats),
