router.get('/resources', async (_req: Request, res: Response): Promise<void> => {
  try {
    const memUsage = process.memoryUsage();
    const cpuUsage = process.cpuUsage();

    // Convert memory to MB for readability
    const memoryMB = {
      rss: Math.round(memUsage.rss / 1024 / 1024),
      heapTotal: Math.round(memUsage.heapTotal / 1024 / 1024),
      heapUsed: Math.round(memUsage.heapUsed / 1024 / 1024),
      external: Math.round(memUsage.external / 1024 / 1024),
      arrayBuffers: Math.round(memUsage.arrayBuffers / 1024 / 1024),
    };

    // Calculate heap usage percentage
    const heapUsagePercent = (memoryMB.heapUsed / memoryMB.heapTotal) * 100;

    res.json({
      success: true,
      data: {
        memory: {
          ...memoryMB,
          heapUsagePercent: Math.round(heapUsagePercent * 100) / 100,
          unit: 'MB',
        },
        cpu: {
          user: cpuUsage.user,
          system: cpuUsage.system,
          userMs: cpuUsage.user / 1000,
          systemMs: cpuUsage.system / 1000,
        },
        process: {
          pid: process.pid,
          uptime: process.uptime(),
          platform: process.platform,
          arch: process.arch,
          nodeVersion: process.version,
        },
      },
      timestamp: new Date().toISOString(),
    });
  } catch (_error) {
    logger.error('Error getting resource usage:', _error);
    res.status(500).json({
