        time: `${9 + index}:00 AM`,
        subject,
        activity: `${subject} Activity`,
        materials: ['Textbook', 'Worksheets'],
        notes: 'Follow the lesson plan in the binder',
      })),
      generalNotes: input.notes ?? 'Please follow the daily routine',
      emergencyContacts: [
