/**
 * BaseService - Base class for all services in the Teaching Engine
 * Provides common functionality and lifecycle management
 */

import type { Logger } from '../../logger.js';
import { logger } from '../../logger.js';
import { recordDatabaseQuery } from '../../middleware/metrics.js';
import { prisma } from '../../prisma.js';

export interface OperationMetrics {
  count: number;
  totalDuration: number;
  averageDuration: number;
}

export interface ServiceMetrics {
  totalRequests: number;
  successfulRequests: number;
  failedRequests: number;
  operations: Record<string, OperationMetrics>;
}

export interface ServiceHealth {
  status: 'healthy' | 'degraded' | 'unhealthy';
  service: string;
  uptime: number;
  metrics: ServiceMetrics;
  dependencies: Record<string, boolean>;
}

export abstract class BaseService {
  protected readonly name: string;
  protected readonly logger: Logger;
  protected metrics: ServiceMetrics;
  protected startTime: Date;
  protected lastHealthCheck: Date;
  protected healthyState = true;
  private initialized = false;

  constructor(serviceName: string) {
    this.name = serviceName;
    this.logger = logger.child({ service: serviceName });
    this.startTime = new Date();
    this.lastHealthCheck = new Date();
    this.metrics = {
      totalRequests: 0,
      successfulRequests: 0,
      failedRequests: 0,
      operations: {},
    };
  }

  /**
   * Ensure the service is initialized
   */
  protected async ensureInitialized(): Promise<void> {
    if (!this.initialized) {
      await this.initialize();
      this.initialized = true;
    }
  }

  /**
   * Initialize the service
   */
  protected initialize(): void {
    this.logger.info(`Initializing ${this.name}`);
  }

  /**
   * Shutdown the service gracefully
   */
  public shutdown(): void {
    this.logger.info(`Service ${this.name} shutting down`);
  }

  /**
   * Perform health check
   */
  public healthCheck(): ServiceHealth {
    this.lastHealthCheck = new Date();
    const dependencies = this.checkDependencies();

    return {
      status: this.getHealthStatus(),
      service: this.name,
      uptime: Date.now() - this.startTime.getTime(),
      metrics: this.getServiceMetrics(),
      dependencies,
    };
  }

  /**
   * Check the health status of the service
   */
  protected getHealthStatus(): 'healthy' | 'degraded' | 'unhealthy' {
    const errorRate = this.metrics.totalRequests > 0 
      ? this.metrics.failedRequests / this.metrics.totalRequests 
      : 0;

    if (errorRate > 0.5) {
      return 'unhealthy';
    } else if (errorRate > 0.2) {
      return 'degraded';
    }

    return 'healthy';
  }

  /**
   * Check dependencies (database, external services, etc.)
   */
  protected checkDependencies(): Record<string, boolean> {
    return {
      logger: true,
    };
  }

  /**
   * Check if database connection is healthy
   */
  protected checkDatabaseConnection(): boolean {
    try {
      // Simple check - if prisma is available
      return prisma !== null;
    } catch (_error) {
      this.logger.error({ error: _error }, 'Database connection check failed');
      return false;
    }
  }

  /**
   * Execute a function with metrics recording
   */
  protected async executeWithMetrics<T>(
    operation: () => Promise<T> | T,
    operationName: string
  ): Promise<T> {
    const startTime = Date.now();
    let error: Error | undefined;

    try {
      this.logger.debug(`Executing ${operationName}`);
      const result = await operation();

      // Record success
      this.metrics.totalRequests++;
      this.metrics.successfulRequests++;

      // Update operation metrics
      const duration = Date.now() - startTime;
      this.updateOperationMetrics(operationName, duration);

      return result;
    } catch (_err) {
      error = _err instanceof Error ? _err : new Error(String(_err));

      // Record failure
      this.metrics.totalRequests++;
      this.metrics.failedRequests++;

      // Update operation metrics
      const duration = Date.now() - startTime;
      this.updateOperationMetrics(operationName, duration);

      // Log error
      this.logger.error({ error, operation: operationName }, `Operation failed: ${operationName}`);

      throw error;
    }
  }

  /**
   * Update operation-specific metrics
   */
  private updateOperationMetrics(operationName: string, duration: number): void {
    if (!this.metrics.operations[operationName]) {
      this.metrics.operations[operationName] = {
        count: 0,
        totalDuration: 0,
        averageDuration: 0,
      };
    }

    const opMetrics = this.metrics.operations[operationName];
    opMetrics.count++;
    opMetrics.totalDuration += duration;
    opMetrics.averageDuration = opMetrics.totalDuration / opMetrics.count;
  }

  /**
   * Get service metrics (protected)
   */
  protected getServiceMetrics(): ServiceMetrics {
    return { ...this.metrics };
  }

  /**
   * Execute database operation with metrics
   */
  protected async executeDbOperation<T>(
    operation: () => Promise<T>,
    operationName: string
  ): Promise<T> {
    return recordDatabaseQuery(operationName, operation);
  }

  /**
   * Get service name
   */
  public getServiceName(): string {
    return this.name;
  }

  /**
   * Check if service is healthy
   */
  public isHealthy(): boolean {
    return this.healthyState;
  }

  /**
   * Get service metrics (public)
   */
  public getMetrics(): ServiceMetrics {
    return {
      totalRequests: this.metrics.totalRequests,
      successfulRequests: this.metrics.successfulRequests,
      failedRequests: this.metrics.failedRequests,
      operations: { ...this.metrics.operations },
    };
  }
}

/**
 * In-Memory Cache Service
 * Fallback cache implementation for development/testing
 */

import { structuredLogger } from '../../utils/structuredLogger';

import type { CacheOptions, CacheStats } from './RedisCache';

interface CacheEntry<T> {
  value: T;
  expires: number;
  tags: string[];
}

export class MemoryCache {
  private cache = new Map<string, CacheEntry<unknown>>();
  private tagIndex = new Map<string, Set<string>>();
  private stats: CacheStats = {
    hits: 0,
    misses: 0,
    sets: 0,
    deletes: 0,
    errors: 0,
    hitRate: 0,
  };
  private cleanupInterval: NodeJS.Timeout | null = null;

  constructor(
    private config: {
      maxSize?: number;
      defaultTtl?: number;
      cleanupInterval?: number;
    } = {},
  ) {
    // Start cleanup interval
    const interval = config.cleanupInterval ?? 60000; // 1 minute default
    this.cleanupInterval = setInterval(() => {
 this.cleanup(); 
}, interval);
  }

  async connect(): Promise<void> {
    structuredLogger.info('Memory cache initialized');
  }

  async disconnect(): Promise<void> {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
      this.cleanupInterval = null;
    }
    this.cache.clear();
    this.tagIndex.clear();
    structuredLogger.info('Memory cache disconnected');
  }

  async get<T>(key: string): Promise<T | null> {
    const entry = this.cache.get(key);

    if (!entry) {
      this.stats.misses++;
      this.updateHitRate();
      return null;
    }

    // Check expiration
    if (entry.expires > 0 && entry.expires < Date.now()) {
      this.cache.delete(key);
      this.removeFromTags(key, entry.tags);
      this.stats.misses++;
      this.updateHitRate();
      return null;
    }

    this.stats.hits++;
    this.updateHitRate();
    return entry.value as T;
  }

  async set<T>(key: string, value: T, options: CacheOptions = {}): Promise<boolean> {
    try {
      // Check max size
      if (this.config.maxSize && this.cache.size >= this.config.maxSize) {
        this.evictOldest();
      }

      const ttl = options.ttl ?? this.config.defaultTtl ?? 3600;
      const expires = ttl > 0 ? Date.now() + ttl * 1000 : 0;
      const tags = options.tags ?? [];

      this.cache.set(key, { value, expires, tags });

      // Update tag index
      if (tags.length > 0) {
        this.addToTags(key, tags);
      }

      this.stats.sets++;
      return true;
    } catch (error) {
      structuredLogger.error('Memory cache set error', error as Error, { key });
      this.stats.errors++;
      return false;
    }
  }

  async delete(key: string): Promise<boolean> {
    const entry = this.cache.get(key);
    if (!entry) {
return false;
}

    this.cache.delete(key);
    this.removeFromTags(key, entry.tags);
    this.stats.deletes++;
    return true;
  }

  async deleteByPattern(pattern: string): Promise<number> {
    const regex = new RegExp(pattern.replace(/\*/g, '.*'));
    let deleted = 0;

    for (const [key, entry] of this.cache.entries()) {
      if (regex.test(key)) {
        this.cache.delete(key);
        this.removeFromTags(key, entry.tags);
        deleted++;
      }
    }

    this.stats.deletes += deleted;
    return deleted;
  }

  async invalidateByTags(tags: string[]): Promise<number> {
    let totalDeleted = 0;

    for (const tag of tags) {
      const keys = this.tagIndex.get(tag);
      if (!keys) {
continue;
}

      for (const key of keys) {
        if (this.cache.delete(key)) {
          totalDeleted++;
        }
      }

      this.tagIndex.delete(tag);
    }

    this.stats.deletes += totalDeleted;
    return totalDeleted;
  }

  async clear(): Promise<void> {
    this.cache.clear();
    this.tagIndex.clear();
    this.resetStats();
  }

  async getOrSet<T>(
    key: string,
    factory: () => Promise<T>,
    options: CacheOptions = {},
  ): Promise<T> {
    const cached = await this.get<T>(key);
    if (cached !== null) {
      return cached;
    }

    const value = await factory();
    await this.set(key, value, options);
    return value;
  }

  async increment(key: string, amount = 1): Promise<number> {
    const current = (await this.get<number>(key)) ?? 0;
    const newValue = current + amount;
    await this.set(key, newValue);
    return newValue;
  }

  getStats(): CacheStats {
    return { ...this.stats };
  }

  resetStats(): void {
    this.stats = {
      hits: 0,
      misses: 0,
      sets: 0,
      deletes: 0,
      errors: 0,
      hitRate: 0,
    };
  }

  healthCheck(): boolean {
    return true;
  }

  // Private helper methods

  private cleanup(): void {
    const now = Date.now();
    let cleaned = 0;

    for (const [key, entry] of this.cache.entries()) {
      if (entry.expires > 0 && entry.expires < now) {
        this.cache.delete(key);
        this.removeFromTags(key, entry.tags);
        cleaned++;
      }
    }

    if (cleaned > 0) {
      structuredLogger.debug('Memory cache cleanup', { cleaned });
    }
  }

  private evictOldest(): void {
    // Simple FIFO eviction
    const firstKey = this.cache.keys().next().value;
    if (firstKey) {
      const entry = this.cache.get(firstKey);
      this.cache.delete(firstKey);
      if (entry) {
        this.removeFromTags(firstKey, entry.tags);
      }
    }
  }

  private addToTags(key: string, tags: string[]): void {
    for (const tag of tags) {
      if (!this.tagIndex.has(tag)) {
        this.tagIndex.set(tag, new Set());
      }
      const tagSet = this.tagIndex.get(tag);
      if (tagSet) {
        tagSet.add(key);
      }
    }
  }

  private removeFromTags(key: string, tags: string[]): void {
    for (const tag of tags) {
      const keys = this.tagIndex.get(tag);
      if (keys) {
        keys.delete(key);
        if (keys.size === 0) {
          this.tagIndex.delete(tag);
        }
      }
    }
  }

  private updateHitRate(): void {
    const total = this.stats.hits + this.stats.misses;
    if (total > 0) {
      this.stats.hitRate = this.stats.hits / total;
    }
  }
}

// Singleton instance
let memoryCacheInstance: MemoryCache | null = null;

/**
 * Get or create memory cache instance
 */
export function getMemoryCache(): MemoryCache {
  if (!memoryCacheInstance) {
    memoryCacheInstance = new MemoryCache({
      maxSize: 1000,
      defaultTtl: 3600,
      cleanupInterval: 60000,
    });
  }

  return memoryCacheInstance;
}

/**
 * Redis Cache Service
 * Production-ready caching layer with Redis
 */

import type { Request, Response, NextFunction } from 'express';
import type { RedisClientType } from 'redis';
import { createClient } from 'redis';

import { PerformanceLogger } from '../../utils/logger-migration';
import { structuredLogger } from '../../utils/structuredLogger';
import { safeJsonParse } from '../../utils/type-guards.js';

export interface CacheOptions {
  ttl?: number; // Time to live in seconds
  tags?: string[]; // Cache tags for invalidation
  compress?: boolean; // Compress large values
}

export interface CacheStats {
  hits: number;
  misses: number;
  sets: number;
  deletes: number;
  errors: number;
  hitRate: number;
}

export class RedisCache {
  private client: RedisClientType;
  private isConnected = false;
  private stats: CacheStats = {
    hits: 0,
    misses: 0,
    sets: 0,
    deletes: 0,
    errors: 0,
    hitRate: 0,
  };

  constructor(
    private config: {
      url?: string;
      host?: string;
      port?: number;
      password?: string;
      db?: number;
      keyPrefix?: string;
      defaultTtl?: number;
      maxRetries?: number;
      enableCompression?: boolean;
    } = {},
  ) {
    this.client = createClient({
      url: config.url ?? `redis://${config.host ?? 'localhost'}:${config.port ?? 6379}`,
      password: config.password,
      database: config.db ?? 0,
      socket: {
        reconnectStrategy: (retries) => {
          const maxRetries = config.maxRetries ?? 3;
          if (retries > maxRetries) {
            structuredLogger.error('Redis reconnection failed', new Error('Max retries exceeded'), {
              retries,
              maxRetries,
            });
            return false;
          }
          return Math.min(retries * 100, 3000);
        },
      },
    });

    this.setupEventHandlers();
  }

  private setupEventHandlers() {
    this.client.on('connect', () => {
      structuredLogger.info('Redis client connected');
      this.isConnected = true;
    });

    this.client.on('ready', () => {
      structuredLogger.info('Redis client ready');
    });

    this.client.on('error', (err) => {
      structuredLogger.error('Redis client error', err);
      this.stats.errors++;
    });

    this.client.on('end', () => {
      structuredLogger.info('Redis client disconnected');
      this.isConnected = false;
    });
  }

  async connect(): Promise<void> {
    if (this.isConnected) {
return;
}

    try {
      await this.client.connect();
    } catch (error) {
      structuredLogger.error('Failed to connect to Redis', error as Error);
      throw error;
    }
  }

  async disconnect(): Promise<void> {
    if (!this.isConnected) {
return;
}

    try {
      await this.client.quit();
    } catch (error) {
      structuredLogger.error('Failed to disconnect from Redis', error as Error);
      throw error;
    }
  }

  /**
   * Get value from cache
   */
  async get<T>(key: string): Promise<T | null> {
    if (!this.isConnected) {
      structuredLogger.warn('Redis not connected, cache bypassed');
      return null;
    }

    const perfLogger = new PerformanceLogger('cache.get');
    const fullKey = this.getFullKey(key);

    try {
      const value = await this.client.get(fullKey);

      if (value === null) {
        this.stats.misses++;
        this.updateHitRate();
        perfLogger.end({ hit: false, key });
        return null;
      }

      this.stats.hits++;
      this.updateHitRate();

      const parsed = this.deserializeValue<T>(value);
      perfLogger.end({ hit: true, key, size: value.length });

      return parsed;
    } catch (error) {
      structuredLogger.error('Cache get error', error as Error, { key });
      this.stats.errors++;
      return null;
    }
  }

  /**
   * Set value in cache
   */
  async set<T>(key: string, value: T, options: CacheOptions = {}): Promise<boolean> {
    if (!this.isConnected) {
      structuredLogger.warn('Redis not connected, cache bypassed');
      return false;
    }

    const perfLogger = new PerformanceLogger('cache.set');
    const fullKey = this.getFullKey(key);
    const ttl = options.ttl ?? this.config.defaultTtl ?? 3600; // Default 1 hour

    try {
      const serialized = this.serializeValue(value, options.compress);

      if (ttl > 0) {
        await this.client.setEx(fullKey, ttl, serialized);
      } else {
        await this.client.set(fullKey, serialized);
      }

      // Handle tags
      if (options.tags && options.tags.length > 0) {
        await this.addToTags(fullKey, options.tags);
      }

      this.stats.sets++;
      perfLogger.end({ key, ttl, size: serialized.length });

      return true;
    } catch (error) {
      structuredLogger.error('Cache set error', error as Error, { key });
      this.stats.errors++;
      return false;
    }
  }

  /**
   * Delete value from cache
   */
  async delete(key: string): Promise<boolean> {
    if (!this.isConnected) {
return false;
}

    const fullKey = this.getFullKey(key);

    try {
      const result = await this.client.del(fullKey);
      this.stats.deletes++;

      structuredLogger.debug('Cache key deleted', { key, deleted: result > 0 });
      return result > 0;
    } catch (error) {
      structuredLogger.error('Cache delete error', error as Error, { key });
      this.stats.errors++;
      return false;
    }
  }

  /**
   * Delete multiple keys by pattern
   */
  async deleteByPattern(pattern: string): Promise<number> {
    if (!this.isConnected) {
return 0;
}

    const fullPattern = this.getFullKey(pattern);

    try {
      const keys = await this.client.keys(fullPattern);
      if (keys.length === 0) {
return 0;
}

      const result = await this.client.del(keys);
      this.stats.deletes += result;

      structuredLogger.info('Cache keys deleted by pattern', { pattern, count: result });
      return result;
    } catch (error) {
      structuredLogger.error('Cache delete by pattern error', error as Error, { pattern });
      this.stats.errors++;
      return 0;
    }
  }

  /**
   * Invalidate cache by tags
   */
  async invalidateByTags(tags: string[]): Promise<number> {
    if (!this.isConnected || tags.length === 0) {
return 0;
}

    let totalDeleted = 0;

    try {
      for (const tag of tags) {
        const tagKey = `${this.config.keyPrefix ?? 'cache'}:tag:${tag}`;
        const keys = await this.client.sMembers(tagKey);

        if (keys.length > 0) {
          const deleted = await this.client.del(keys);
          totalDeleted += deleted;

          // Clean up the tag set
          await this.client.del(tagKey);
        }
      }

      structuredLogger.info('Cache invalidated by tags', { tags, deleted: totalDeleted });
      return totalDeleted;
    } catch (error) {
      structuredLogger.error('Cache invalidate by tags error', error as Error, { tags });
      this.stats.errors++;
      return 0;
    }
  }

  /**
   * Clear all cache
   */
  async clear(): Promise<void> {
    if (!this.isConnected) {
return;
}

    try {
      await this.client.flushDb();
      this.resetStats();

      structuredLogger.warn('Cache cleared');
    } catch (error) {
      structuredLogger.error('Cache clear error', error as Error);
      this.stats.errors++;
    }
  }

  /**
   * Get or set cache value
   */
  async getOrSet<T>(
    key: string,
    factory: () => Promise<T>,
    options: CacheOptions = {},
  ): Promise<T> {
    // Try to get from cache first
    const cached = await this.get<T>(key);
    if (cached !== null) {
      return cached;
    }

    // Generate value
    const perfLogger = new PerformanceLogger('cache.factory');
    const value = await factory();
    perfLogger.end({ key });

    // Store in cache
    await this.set(key, value, options);

    return value;
  }

  /**
   * Increment counter
   */
  async increment(key: string, amount = 1): Promise<number> {
    if (!this.isConnected) {
return 0;
}

    const fullKey = this.getFullKey(key);

    try {
      const result = await this.client.incrBy(fullKey, amount);
      return result;
    } catch (error) {
      structuredLogger.error('Cache increment error', error as Error, { key });
      this.stats.errors++;
      return 0;
    }
  }

  /**
   * Get cache statistics
   */
  getStats(): CacheStats {
    return { ...this.stats };
  }

  /**
   * Reset statistics
   */
  resetStats(): void {
    this.stats = {
      hits: 0,
      misses: 0,
      sets: 0,
      deletes: 0,
      errors: 0,
      hitRate: 0,
    };
  }

  /**
   * Health check
   */
  async healthCheck(): Promise<boolean> {
    if (!this.isConnected) {
return false;
}

    try {
      await this.client.ping();
      return true;
    } catch (error) {
      return false;
    }
  }

  // Private helper methods

  private getFullKey(key: string): string {
    return this.config.keyPrefix ? `${this.config.keyPrefix}:${key}` : key;
  }

  private serializeValue<T>(value: T, compress?: boolean): string {
    const json = JSON.stringify(value);

    if (compress && this.config.enableCompression && json.length > 1024) {
      // In production, use zlib compression
      // For now, just return JSON
      return json;
    }

    return json;
  }

  private deserializeValue<T>(value: string): T {
    try {
      const parsed = safeJsonParse(value, {});
      if (parsed === undefined) {
        throw new Error('Failed to parse JSON value');
      }
      return parsed as T;
    } catch (error) {
      structuredLogger.error('Cache deserialization error', error as Error);
      throw error;
    }
  }

  private async addToTags(key: string, tags: string[]): Promise<void> {
    const pipeline = this.client.multi();

    for (const tag of tags) {
      const tagKey = `${this.config.keyPrefix ?? 'cache'}:tag:${tag}`;
      pipeline.sAdd(tagKey, key);
    }

    await pipeline.exec();
  }

  private updateHitRate(): void {
    const total = this.stats.hits + this.stats.misses;
    if (total > 0) {
      this.stats.hitRate = this.stats.hits / total;
    }
  }
}

// Singleton instance
let cacheInstance: RedisCache | null = null;

/**
 * Get or create cache instance
 */
export function getCache(): RedisCache {
  if (!cacheInstance) {
    cacheInstance = new RedisCache({
      url: process.env.REDIS_URL,
      keyPrefix: 'teaching-engine',
      defaultTtl: 3600,
      enableCompression: true,
    });

    // Auto-connect in non-test environments
    if (process.env.NODE_ENV !== 'test') {
      cacheInstance.connect().catch((error) => {
        structuredLogger.error('Failed to connect to Redis on startup', error);
      });
    }
  }

  return cacheInstance;
}

/**
 * Express middleware for cache
 */
export function cacheMiddleware(keyPattern: string, options: CacheOptions = {}) {
  const cache = getCache();

  return async (req: Request, res: Response, next: NextFunction) => {
    const key = keyPattern
      .replace(':id', req.params.id ?? '')
      .replace(':userId', (req as Request & { user?: { id: string } }).user?.id ?? 'anonymous');

    // Try to get from cache
    const cached = await cache.get(key);
    if (cached) {
      res.setHeader('X-Cache', 'HIT');
      return res.json(cached);
    }

    // Store original json method
    const originalJson = res.json.bind(res);

    // Override json to cache the response
    res.json = function (data: unknown) {
      res.setHeader('X-Cache', 'MISS');

      // Cache the response asynchronously
      cache.set(key, data, options).catch((error) => {
        structuredLogger.error('Failed to cache response', error);
      });

      return originalJson(data);
    };

    next();
    return;
  };
}

/**
 * Unified Cache Service
 * Provides a consistent interface with automatic fallback
 */

import { structuredLogger } from '../../utils/structuredLogger';

import type { MemoryCache} from './MemoryCache';
import { getMemoryCache } from './MemoryCache';
import type { RedisCache, CacheOptions, CacheStats } from './RedisCache';
import { getCache as getRedisCache } from './RedisCache';

export type { CacheOptions, CacheStats } from './RedisCache';
export { cacheMiddleware } from './RedisCache';

export interface ICache {
  connect(): Promise<void>;
  disconnect(): Promise<void>;
  get<T>(key: string): Promise<T | null>;
  set<T>(key: string, value: T, options?: CacheOptions): Promise<boolean>;
  delete(key: string): Promise<boolean>;
  deleteByPattern(pattern: string): Promise<number>;
  invalidateByTags(tags: string[]): Promise<number>;
  clear(): Promise<void>;
  getOrSet<T>(key: string, factory: () => Promise<T>, options?: CacheOptions): Promise<T>;
  increment(key: string, amount?: number): Promise<number>;
  getStats(): CacheStats;
  resetStats(): void;
  healthCheck(): Promise<boolean>;
}

class UnifiedCache implements ICache {
  private primaryCache: RedisCache | null = null;
  private fallbackCache: MemoryCache;
  private useRedis: boolean;

  constructor() {
    this.useRedis = process.env.REDIS_URL !== undefined && process.env.NODE_ENV !== 'test';
    this.fallbackCache = getMemoryCache();

    if (this.useRedis) {
      try {
        this.primaryCache = getRedisCache();
      } catch (error) {
        structuredLogger.error('Failed to initialize Redis cache', error as Error);
        this.useRedis = false;
      }
    }

    structuredLogger.info('Cache initialized', {
      type: this.useRedis ? 'redis' : 'memory',
      redisUrl: process.env.REDIS_URL !== null && process.env.REDIS_URL !== undefined && process.env.REDIS_URL !== '' ? 'configured' : 'not configured',
    });
  }

  async connect(): Promise<void> {
    if (this.primaryCache) {
      try {
        await this.primaryCache.connect();
      } catch (error) {
        structuredLogger.error(
          'Redis connection failed, falling back to memory cache',
          error as Error,
        );
        this.primaryCache = null;
        this.useRedis = false;
      }
    }
    await this.fallbackCache.connect();
  }

  async disconnect(): Promise<void> {
    if (this.primaryCache) {
      await this.primaryCache.disconnect();
    }
    await this.fallbackCache.disconnect();
  }

  async get<T>(key: string): Promise<T | null> {
    const cache = this.getActiveCache();
    return cache.get<T>(key);
  }

  async set<T>(key: string, value: T, options?: CacheOptions): Promise<boolean> {
    const cache = this.getActiveCache();
    return cache.set(key, value, options);
  }

  async delete(key: string): Promise<boolean> {
    const cache = this.getActiveCache();
    return cache.delete(key);
  }

  async deleteByPattern(pattern: string): Promise<number> {
    const cache = this.getActiveCache();
    return cache.deleteByPattern(pattern);
  }

  async invalidateByTags(tags: string[]): Promise<number> {
    const cache = this.getActiveCache();
    return cache.invalidateByTags(tags);
  }

  async clear(): Promise<void> {
    const cache = this.getActiveCache();
    return cache.clear();
  }

  async getOrSet<T>(key: string, factory: () => Promise<T>, options?: CacheOptions): Promise<T> {
    const cache = this.getActiveCache();
    return cache.getOrSet(key, factory, options);
  }

  async increment(key: string, amount?: number): Promise<number> {
    const cache = this.getActiveCache();
    return cache.increment(key, amount);
  }

  getStats(): CacheStats {
    const cache = this.getActiveCache();
    return cache.getStats();
  }

  resetStats(): void {
    const cache = this.getActiveCache();
    cache.resetStats();
  }

  async healthCheck(): Promise<boolean> {
    const cache = this.getActiveCache();
    return cache.healthCheck();
  }

  private getActiveCache(): ICache {
    if (this.primaryCache && this.useRedis) {
      return this.primaryCache;
    }
    return this.fallbackCache;
  }

  isUsingRedis(): boolean {
    return this.useRedis && this.primaryCache !== null;
  }
}

// Singleton instance
let cacheInstance: UnifiedCache | null = null;

/**
 * Get cache instance
 */
export function cache(): ICache {
  if (!cacheInstance) {
    cacheInstance = new UnifiedCache();

    // Auto-connect in non-test environments
    if (process.env.NODE_ENV !== 'test') {
      cacheInstance.connect().catch((error) => {
        structuredLogger.error('Failed to connect cache on startup', error);
      });
    }
  }

  return cacheInstance;
}

/**
 * Cache decorator for methods
 */
export function Cacheable(options: CacheOptions & { keyPrefix?: string } = {}) {
  return function (target: unknown, propertyKey: string, descriptor: PropertyDescriptor) {
    const originalMethod = descriptor.value;

    descriptor.value = async function (...args: unknown[]) {
      const cacheService = cache();
      const keyPrefix =
        options.keyPrefix ||
        `${(target as { constructor: { name: string } }).constructor.name}.${propertyKey}`;
      const key = `${keyPrefix}:${JSON.stringify(args)}`;

      return cacheService.getOrSet(key, () => originalMethod.apply(this, args), options);
    };

    return descriptor;
  };
}

/**
 * Cache invalidation decorator
 */
export function CacheInvalidate(tags: string[] | ((args: unknown[]) => string[])) {
  return function (_target: unknown, _propertyKey: string, descriptor: PropertyDescriptor) {
    const originalMethod = descriptor.value;

    descriptor.value = async function (...args: unknown[]) {
      const result = await originalMethod.apply(this, args);

      const cacheService = cache();
      const tagsToInvalidate = typeof tags === 'function' ? tags(args) : tags;

      await cacheService.invalidateByTags(tagsToInvalidate);

      return result;
    };

    return descriptor;
  };
}

