/**
 * CSV Curriculum Parser
 * Parses curriculum expectations from CSV files
 */

import { parse } from 'csv-parse/sync';

import { CurriculumParser, type ParsedCurriculum, type ParsedExpectation } from './CurriculumParser';

export interface CSVRow {
  code?: string;
  expectation_code?: string;
  description?: string;
  expectation_description?: string;
  type?: string;
  expectation_type?: string;
  strand?: string;
  substrand?: string;
  grade?: string | number;
  subject?: string;
  [key: string]: unknown;
}

export class CSVParser extends CurriculumParser {
  /**
   * Parse CSV content
   */
  async parse(content: string | Buffer): Promise<ParsedCurriculum> {
    const stringContent = content instanceof Buffer ? content.toString('utf-8') : content;

    // Parse CSV with error handling for malformed data
    let records: CSVRow[];
    try {
      records = parse(stringContent, {
        columns: true,
        skip_empty_lines: true,
        trim: true,
        cast: true,
        cast_date: false,
        relax_quotes: true, // Allow unescaped quotes
        skip_records_with_error: true, // Skip malformed records
      }) as CSVRow[];
    } catch (_error) {
      // If parsing fails, try with more relaxed settings
      try {
        records = parse(stringContent, {
          columns: true,
          skip_empty_lines: true,
          trim: true,
          cast: false, // Don't cast types
          relax_quotes: true,
          relax_column_count: true, // Allow varying column counts
          skip_records_with_error: true,
        }) as CSVRow[];
      } catch (fallbackError) {
        const errorMessage = fallbackError instanceof Error ? fallbackError.message : 'Unknown error';
        throw new Error(`Failed to parse CSV: ${errorMessage}`);
      }
    }

    if (records.length === 0) {
      // In non-strict mode, return empty curriculum
      if (this.options.strict !== true) {
        return {
          subject: 'Unknown',
          grade: 1,
          expectations: [],
          metadata: {
            source: 'CSV Import',
            lastUpdated: new Date(),
          },
        };
      }
      throw new Error('No data found in CSV file');
    }

    // Extract metadata from first row or headers
    const [firstRow] = records;
    const grade = this.extractGrade(firstRow);
    const subject = this.extractSubject(firstRow);

    // Parse expectations
    const expectations: ParsedExpectation[] = [];

    for (const row of records) {
      const expectation = this.parseRow(row, grade, subject);
      if (expectation && this.isValidExpectation(expectation)) {
        expectations.push(expectation);
      }
    }

    // Try to extract subject and grade from any row if not found in first row
    let finalSubject = subject;
    let finalGrade = grade;

    if ((finalSubject === null || finalSubject === '') || (finalGrade === null)) {
      for (const expectation of expectations) {
        if ((finalSubject === null || finalSubject === '') && (expectation.subject !== null && expectation.subject !== '')) {
          finalSubject = expectation.subject;
        }
        if ((finalGrade === null) && (expectation.grade !== null)) {
          finalGrade = expectation.grade;
        }
        if ((finalSubject !== null && finalSubject !== '') && (finalGrade !== null)) {
break;
}
      }
    }

    const curriculum: ParsedCurriculum = {
      subject: finalSubject ?? 'Unknown',
      grade: finalGrade ?? 1,
      expectations,
      metadata: {
        source: 'CSV Import',
        lastUpdated: new Date(),
      },
    };

    // In non-strict mode, always return the curriculum even if validation would fail
    if (this.options.strict !== true) {
      return curriculum;
    }

    if (!this.validate(curriculum)) {
      throw new Error('Invalid curriculum data structure');
    }

    return curriculum;
  }

  /**
   * Parse a single CSV row
   */
  private parseRow(row: CSVRow, defaultGrade?: number, defaultSubject?: string): ParsedExpectation | null {
    // Try different column name variations
    const code = this.cleanText(
      this.ensureString((() => {
        if (row.code !== null && row.code !== '') {
return row.code;
}
        if (row.expectation_code !== null && row.expectation_code !== '') {
return row.expectation_code;
}
        if (row.Code !== null && row.Code !== '') {
return row.Code;
}
        if (row['Expectation Code'] !== null && row['Expectation Code'] !== undefined && row['Expectation Code'] !== '') {
return row['Expectation Code'];
}
        return '';
      })())
    );

    const description = this.cleanText(
      this.ensureString((() => {
        if (row.description !== null && row.description !== '') {
return row.description;
}
        if (row.expectation_description !== null && row.expectation_description !== '') {
return row.expectation_description;
}
        if (row.Description !== null && row.Description !== '') {
return row.Description;
}
        if (row['Expectation Description'] !== null && row['Expectation Description'] !== undefined && row['Expectation Description'] !== '') {
return row['Expectation Description'];
}
        return '';
      })())
    );

    if ((code === null || code === '') || (description === null || description === '')) {
      return null;
    }

    const type = this.parseType(row);
    const strand = this.cleanText(this.ensureString((() => {
      if (row.strand !== null && row.strand !== '') {
return row.strand;
}
      if (row.Strand !== null && row.Strand !== '') {
return row.Strand;
}
      return '';
    })()));
    const substrand = this.cleanText(this.ensureString((() => {
      if (row.substrand !== null && row.substrand !== '') {
return row.substrand;
}
      if (row.Substrand !== null && row.Substrand !== '') {
return row.Substrand;
}
      return '';
    })()));

    const expectation: ParsedExpectation = {
      code,
      description,
      type,
      strand: strand || this.extractStrandFromCode(code),
      substrand: substrand ?? undefined,
      grade: this.extractGrade(row) ?? defaultGrade,
      subject: (() => {
        const extractedSubject = this.extractSubject(row);
        const finalSubject = extractedSubject ?? defaultSubject;
        return finalSubject ?? undefined;
      })(),
    };

    if (this.options.extractKeywords) {
      expectation.keywords = this.extractKeywords(description);
    }

    return expectation;
  }

  /**
   * Parse expectation type
   */
  private parseType(row: CSVRow): 'overall' | 'specific' {
    const typeValue = (() => {
      if (row.type !== null && row.type !== '') {
return row.type;
}
      if (row.expectation_type !== null && row.expectation_type !== '') {
return row.expectation_type;
}
      if (row.Type !== null && row.Type !== '') {
return row.Type;
}
      if (row['Expectation Type'] !== null && row['Expectation Type'] !== '') {
return row['Expectation Type'];
}
      return '';
    })();

    if (typeValue !== '') {
      const normalizedType = typeValue.toString().toLowerCase();
      if (normalizedType.includes('overall')) {
return 'overall';
}
      if (normalizedType.includes('specific')) {
return 'specific';
}
    }

    // Fall back to code analysis
    const code = (() => {
      if (row.code !== null && row.code !== '') {
return row.code;
}
      if (row.expectation_code !== null && row.expectation_code !== '') {
return row.expectation_code;
}
      return '';
    })();
    const description = (() => {
      if (row.description !== null && row.description !== '') {
return row.description;
}
      if (row.expectation_description !== null && row.expectation_description !== '') {
return row.expectation_description;
}
      return '';
    })();

    return this.parseExpectationType(code, description);
  }

  /**
   * Extract grade from row
   */
  private extractGrade(row: CSVRow): number | undefined {
    const gradeValue = row.grade ?? row.Grade ?? row.grade_level ?? row['Grade Level'];

    if (gradeValue !== null && gradeValue !== undefined && gradeValue !== '') {
      const numericGrade = typeof gradeValue === 'number' 
        ? gradeValue 
        : parseInt(gradeValue.toString().replace(/\D/g, ''));

      if (!isNaN(numericGrade) && numericGrade >= 1 && numericGrade <= 12) {
        return numericGrade;
      }
    }

    return undefined;
  }

  /**
   * Extract subject from row
   */
  private extractSubject(row: CSVRow): string | undefined {
    const subjectValue = (() => {
      if (row.subject !== null && row.subject !== '') {
return row.subject;
}
      if (row.Subject !== null && row.Subject !== '') {
return row.Subject;
}
      if (row.subject_area !== null && row.subject_area !== '') {
return row.subject_area;
}
      if (row['Subject Area'] !== null && row['Subject Area'] !== '') {
return row['Subject Area'];
}
      return undefined;
    })();
    return (subjectValue !== null && subjectValue !== '') ? this.cleanText(subjectValue.toString()) : undefined;
  }

  /**
   * Extract strand from expectation code
   */
  private extractStrandFromCode(code: string): string {
    const parts = code.split('.');
    if (parts.length >= 2) {
      return parts[1];
    }
    return 'General';
  }

  /**
   * Ensure value is a string
   */
  private ensureString(value: unknown): string {
    if (value === null) {
      return '';
    }
    return String(value);
  }

  /**
   * Check if expectation is valid
   */
  private isValidExpectation(expectation: ParsedExpectation): boolean {
    if (this.options.strict !== true) {
      return true;
    }

    if (!((this.options.validateCodes === true) && this.validateExpectationCode(expectation.code))) {
      return false;
    }

    return expectation.code.length > 0 && expectation.description.length > 0;
  }

  /**
   * Validate parsed curriculum
   */
  validate(data: ParsedCurriculum): boolean {
    if ((data.subject === null || data.subject === '') || (data.grade === null)) {
      return false;
    }

    // In strict mode, require non-empty expectations
    if ((this.options.strict === true) && data.expectations.length === 0) {
      return false;
    }

    // Don't require overall expectations - some curriculum files might only have specific expectations
    // This was causing valid data to be rejected

    return true;
  }

  /**
   * Get supported file extensions
   */
  getSupportedExtensions(): string[] {
    return ['.csv', '.txt'];
  }
}

/**
 * Base Curriculum Parser Interface
 * Defines the contract for all curriculum file parsers
 */

export interface ParsedExpectation {
  code: string;
  description: string;
  type: 'overall' | 'specific';
  strand: string;
  substrand?: string;
  grade?: number;
  subject?: string;
  keywords?: string[];
}

export interface ParsedCurriculum {
  subject: string;
  grade: number;
  expectations: ParsedExpectation[];
  metadata?: {
    source?: string;
    version?: string;
    lastUpdated?: Date;
  };
}

export interface ParserOptions {
  strict?: boolean;
  validateCodes?: boolean;
  extractKeywords?: boolean;
}

export abstract class CurriculumParser {
  protected options: ParserOptions;

  constructor(options: ParserOptions = {}) {
    this.options = {
      strict: true,
      validateCodes: true,
      extractKeywords: true,
      ...options,
    };
  }

  /**
   * Parse curriculum file content
   */
  abstract parse(content: string | Buffer): Promise<ParsedCurriculum>;

  /**
   * Validate parsed data
   */
  abstract validate(data: ParsedCurriculum): boolean;

  /**
   * Get supported file extensions
   */
  abstract getSupportedExtensions(): string[];

  /**
   * Extract keywords from description
   */
  protected extractKeywords(description: string): string[] {
    // Common educational keywords to extract
    const keywordPatterns = [
      /\b(understand|identify|analyze|create|evaluate|apply|compare|describe|explain)\b/gi,
      /\b(measurement|number|geometry|algebra|data|probability)\b/gi,
      /\b(reading|writing|oral|media|literacy)\b/gi,
      /\b(science|technology|engineering|arts|mathematics)\b/gi,
    ];

    const keywords = new Set<string>();

    keywordPatterns.forEach(pattern => {
      const matches = description.match(pattern);
      if (matches) {
        matches.forEach(match => keywords.add(match.toLowerCase()));
      }
    });

    return Array.from(keywords);
  }

  /**
   * Validate expectation code format
   */
  protected validateExpectationCode(code: string): boolean {
    // Ontario curriculum code format: supports both single codes (A1) and multi-part codes (A1.1, A1.1.2)
    const codePattern = /^[A-Z0-9]+(\.[A-Z0-9]+)*$/;
    return codePattern.test(code);
  }

  /**
   * Parse expectation type from code or description
   */
  protected parseExpectationType(code: string, description: string): 'overall' | 'specific' {
    // Check description first for explicit type indicators
    const lowerDesc = description.toLowerCase();
    if (lowerDesc.includes('overall')) {
      return 'overall';
    }
    if (lowerDesc.includes('specific')) {
      return 'specific';
    }

    // Overall expectations typically have single-part codes (e.g., A1, B2)
    // Specific expectations have multi-part codes (e.g., A1.1, B2.3)
    const parts = code.split('.');
    if (parts.length === 1) {
      return 'overall';
    }
    return 'specific';
  }

  /**
   * Clean and normalize text
   */
  protected cleanText(text: string): string {
    return text
      .trim()
      .replace(/\s+/g, ' ')
      .replace(/[\u2018\u2019]/g, "'")
      .replace(/[\u201C\u201D]/g, '"');
  }
}

/**
 * Excel Curriculum Parser
 * Parses curriculum expectations from Excel files
 */

import * as XLSX from '@datalens-tech/xlsx';

import type { ParsedCurriculum, ParsedExpectation } from './CurriculumParser';
import { CurriculumParser } from './CurriculumParser';

export type ExcelRow = Record<string, unknown>;

export class ExcelParser extends CurriculumParser {
  /**
   * Parse Excel content
   */
  async parse(content: string | Buffer): Promise<ParsedCurriculum> {
    // Read workbook
    const workbook = XLSX.read(content, { type: 'buffer' });

    if (!workbook.SheetNames || workbook.SheetNames.length === 0) {
      throw new Error('No sheets found in Excel file');
    }

    // Process first sheet (or sheet named 'Expectations' if exists)
    const sheetName = workbook.SheetNames.includes('Expectations')
      ? 'Expectations'
      : workbook.SheetNames[0];

    const worksheet = workbook.Sheets[sheetName];

    if (!worksheet) {
      throw new Error(`Worksheet ${sheetName} not found`);
    }

    // Convert to JSON
    const rows: ExcelRow[] = XLSX.utils.sheet_to_json(worksheet, {
      raw: false,
      defval: '',
    });

    if (!rows || rows.length === 0) {
      throw new Error('No data found in Excel file');
    }

    // Extract metadata
    const metadata = this.extractMetadata(workbook, rows);
    const { grade, subject } = metadata;

    // Parse expectations
    const expectations: ParsedExpectation[] = [];

    for (const row of rows) {
      const expectation = this.parseRow(row, grade, subject);
      if (expectation && this.isValidExpectation(expectation)) {
        expectations.push(expectation);
      }
    }

    // Group and organize expectations
    const organized = this.organizeExpectations(expectations);

    const curriculum: ParsedCurriculum = {
      subject: subject ?? 'Unknown',
      grade: grade ?? 0,
      expectations: organized,
      metadata: {
        source: 'Excel Import',
        lastUpdated: new Date(),
        version: metadata.version,
      },
    };

    if (!this.validate(curriculum)) {
      throw new Error('Invalid curriculum data structure');
    }

    return curriculum;
  }

  /**
   * Extract metadata from workbook
   */
  private extractMetadata(
    workbook: XLSX.WorkBook,
    rows: ExcelRow[],
  ): {
    grade?: number;
    subject?: string;
    version?: string;
  } {
    // Try to extract from workbook properties
    const props = workbook.Props;
    const metadata: {
      grade?: number;
      subject?: string;
      version?: string;
    } = {};

    if (props) {
      metadata.version = props.Title ?? props.Subject;
    }

    // Try to extract from first few rows
    const firstRow = rows[0];
    if (firstRow) {
      metadata.grade = this.extractGrade(firstRow);
      metadata.subject = this.extractSubject(firstRow);
    }

    // Try to find metadata in sheet names or cell values
    if ((!metadata.grade) || (!metadata.subject || metadata.subject === '')) {
      for (const sheetName of workbook.SheetNames) {
        const gradeMatch = sheetName.match(/Grade\s*(\d+)/i);
        if (gradeMatch) {
          metadata.grade = parseInt(gradeMatch[1]);
        }

        // Check for subject in sheet name
        const subjects = ['Mathematics', 'Language', 'Science', 'Social Studies', 'Arts'];
        for (const subject of subjects) {
          if (sheetName.toLowerCase().includes(subject.toLowerCase())) {
            metadata.subject = subject;
            break;
          }
        }
      }
    }

    return metadata;
  }

  /**
   * Parse a single Excel row
   */
  private parseRow(
    row: ExcelRow,
    defaultGrade?: number,
    defaultSubject?: string,
  ): ParsedExpectation | null {
    // Find code column (try various naming conventions)
    const codeKeys = ['Code', 'code', 'Expectation Code', 'expectation_code', 'ID', 'Reference'];
    const code = this.findValue(row, codeKeys);

    if (!code || code === '') {
      return null;
    }

    // Find description column
    const descKeys = [
      'Description',
      'description',
      'Expectation',
      'expectation',
      'Text',
      'Content',
    ];
    const description = this.findValue(row, descKeys);

    if (!description || description === '') {
      return null;
    }

    // Find other fields
    const typeKeys = ['Type', 'type', 'Category', 'Level'];
    const type = this.parseType(this.findValue(row, typeKeys) ?? '', code, description);

    const strandKeys = ['Strand', 'strand', 'Domain', 'Area'];
    const strand = this.findValue(row, strandKeys) ?? this.extractStrandFromCode(code);

    const substrandKeys = ['Substrand', 'substrand', 'Topic', 'Subtopic'];
    const substrand = this.findValue(row, substrandKeys);

    const expectation: ParsedExpectation = {
      code: this.cleanText(code),
      description: this.cleanText(description),
      type,
      strand: this.cleanText(strand),
      substrand: substrand && substrand !== '' ? this.cleanText(substrand) : undefined,
      grade: this.extractGrade(row) ?? defaultGrade,
      subject: this.extractSubject(row) ?? defaultSubject,
    };

    if (this.options.extractKeywords) {
      expectation.keywords = this.extractKeywords(description);
    }

    return expectation;
  }

  /**
   * Find value from row using multiple possible keys
   */
  private findValue(row: ExcelRow, keys: string[]): string | undefined {
    for (const key of keys) {
      if (row[key] !== undefined && row[key] !== null && row[key] !== '') {
        return String(row[key]);
      }
    }
    return undefined;
  }

  /**
   * Parse expectation type
   */
  private parseType(typeValue: string, code: string, description: string): 'overall' | 'specific' {
    if (typeValue && typeValue !== '') {
      const normalized = typeValue.toLowerCase();
      if (normalized.includes('overall')) {
        return 'overall';
      }
      if (normalized.includes('specific')) {
        return 'specific';
      }
    }

    return this.parseExpectationType(code, description);
  }

  /**
   * Extract grade from row
   */
  private extractGrade(row: ExcelRow): number | undefined {
    const gradeKeys = ['Grade', 'grade', 'Level', 'Year'];
    const gradeValue = this.findValue(row, gradeKeys);

    if (gradeValue && gradeValue !== '') {
      const numericGrade = parseInt(gradeValue.replace(/\D/g, ''));
      if (!isNaN(numericGrade) && numericGrade >= 1 && numericGrade <= 12) {
        return numericGrade;
      }
    }

    return undefined;
  }

  /**
   * Extract subject from row
   */
  private extractSubject(row: ExcelRow): string | undefined {
    const subjectKeys = ['Subject', 'subject', 'Course', 'Area'];
    const subjectValue = this.findValue(row, subjectKeys);
    return subjectValue ? this.cleanText(subjectValue) : undefined;
  }

  /**
   * Extract strand from expectation code
   */
  private extractStrandFromCode(code: string): string {
    const parts = code.split('.');
    if (parts.length >= 2) {
      return parts[1];
    }

    // Try to extract from code pattern
    const match = code.match(/^[A-Z0-9]+\.([A-Z]+)/);
    if (match) {
      return match[1];
    }

    return 'General';
  }

  /**
   * Organize expectations (group overall before specific)
   */
  private organizeExpectations(expectations: ParsedExpectation[]): ParsedExpectation[] {
    const overall = expectations.filter((e) => e.type === 'overall');
    const specific = expectations.filter((e) => e.type === 'specific');

    // Sort by code
    overall.sort((a, b) => a.code.localeCompare(b.code));
    specific.sort((a, b) => a.code.localeCompare(b.code));

    return [...overall, ...specific];
  }

  /**
   * Check if expectation is valid
   */
  private isValidExpectation(expectation: ParsedExpectation): boolean {
    if (!this.options.strict) {
      return true;
    }

    if (this.options.validateCodes && !this.validateExpectationCode(expectation.code)) {
      return false;
    }

    return expectation.code.length > 0 && expectation.description.length > 0;
  }

  /**
   * Validate parsed curriculum
   */
  validate(data: ParsedCurriculum): boolean {
    if ((!data.subject || data.subject === '') || 
        (!data.grade) || 
        (!data.expectations)) {
      return false;
    }

    if (data.expectations.length === 0) {
      return false;
    }

    return true;
  }

  /**
   * Get supported file extensions
   */
  getSupportedExtensions(): string[] {
    return ['.xlsx', '.xls', '.xlsm'];
  }
}

/* eslint-disable @typescript-eslint/no-explicit-any */
/**
 * JSON Curriculum Parser
 * Parses curriculum expectations from JSON files
 */

import { safeJsonParse } from '../../../utils/type-guards.js';

import type { ParsedCurriculum, ParsedExpectation } from './CurriculumParser';
import { CurriculumParser } from './CurriculumParser';

export interface JSONExpectation {
  code?: string;
  id?: string;
  description?: string;
  content?: string;
  text?: string;
  type?: string;
  category?: string;
  strand?: string;
  domain?: string;
  substrand?: string;
  topic?: string;
  grade?: number | string;
  level?: number | string;
  subject?: string;
  course?: string;
  keywords?: string[];
  [key: string]: unknown;
}

export interface JSONCurriculum {
  subject?: string;
  course?: string;
  grade?: number | string;
  level?: number | string;
  expectations?: JSONExpectation[];
  outcomes?: JSONExpectation[];
  standards?: JSONExpectation[];
  metadata?: unknown;
  [key: string]: unknown;
}

export class JSONParser extends CurriculumParser {
  /**
   * Parse JSON content
   */
  async parse(content: string | Buffer): Promise<ParsedCurriculum> {
    let stringContent: string;
    if (content instanceof Buffer) {
      stringContent = content.toString('utf-8');
    } else {
      stringContent = content as string;
    }

    let data: unknown;
    try {
      data = safeJsonParse(stringContent, {});
    } catch (_error) {
      throw new Error(`Invalid JSON format: ${_error instanceof Error ? _error.message : String(_error)}`);
    }

    // Handle array of expectations
    if (Array.isArray(data)) {
      return this.parseExpectationArray(data);
    }

    // Handle object with expectations
    if (typeof data === 'object' && data !== null) {
      return this.parseCurriculumObject(data as JSONCurriculum);
    }

    throw new Error('Invalid JSON structure for curriculum data');
  }

  /**
   * Parse array of expectations
   */
  private parseExpectationArray(data: unknown[]): ParsedCurriculum {
    const expectations: ParsedExpectation[] = [];
    let inferredGrade: number | undefined;
    let inferredSubject: string | undefined;

    for (const item of data) {
      const expectation = this.parseExpectation(item as JSONExpectation);
      if (expectation !== null) {
        expectations.push(expectation);

        // Try to infer grade and subject
        if ((inferredGrade === null) && (expectation.grade !== null)) {
          inferredGrade = expectation.grade;
        }
        if ((inferredSubject === null || inferredSubject === '') && (expectation.subject !== null && expectation.subject !== '')) {
          inferredSubject = expectation.subject;
        }
      }
    }

    const curriculum: ParsedCurriculum = {
      subject: (inferredSubject !== null && inferredSubject !== '') ? inferredSubject : 'Unknown',
      grade: (inferredGrade !== null) ? inferredGrade : 0,
      expectations,
      metadata: {
        source: 'JSON Import',
        lastUpdated: new Date(),
      },
    };

    if (this.validate(curriculum) !== true) {
      throw new Error('Invalid curriculum data structure');
    }

    return curriculum;
  }

  /**
   * Parse curriculum object
   */
  private parseCurriculumObject(data: JSONCurriculum): ParsedCurriculum {
    // Extract metadata
    const grade = this.parseGrade((data.grade !== null) ? data.grade : data.level);
    const subject = (data.subject !== null && data.subject !== '') ? data.subject : ((data.course !== null && data.course !== '') ? data.course : 'Unknown');

    // Find expectations array
    const expectationsList = 
      data.expectations || 
      data.outcomes || 
      data.standards ||
      this.findExpectationsArray(data);

    if ((expectationsList === null) || !Array.isArray(expectationsList)) {
      throw new Error('No expectations array found in JSON');
    }

    // Parse expectations
    const expectations: ParsedExpectation[] = [];

    for (const item of expectationsList) {
      const expectation = this.parseExpectation(item as JSONExpectation, grade, subject);
      if (expectation !== null) {
        expectations.push(expectation);
      }
    }

    const curriculum: ParsedCurriculum = {
      subject,
      grade: (grade !== null) ? grade : 0,
      expectations: this.organizeExpectations(expectations),
      metadata: {
        source: 'JSON Import',
        lastUpdated: new Date(),
        ...(typeof data.metadata === 'object' && data.metadata !== null ? data.metadata : {}),
      },
    };

    if (this.validate(curriculum) !== true) {
      throw new Error('Invalid curriculum data structure');
    }

    return curriculum;
  }

  /**
   * Find expectations array in nested object
   */
  private findExpectationsArray(obj: unknown, depth = 0): unknown[] | null {
    if (depth > 3) {
return null;
} // Prevent deep recursion

    if (typeof obj !== 'object' || obj === null) {
return null;
}

    for (const key in obj as Record<string, unknown>) {
      const value = (obj as Record<string, unknown>)[key];

      if (Array.isArray(value) && value.length > 0) {
        // Check if this looks like an expectations array
        const firstItem = value[0];
        if (
          typeof firstItem === 'object' &&
          (firstItem.code || firstItem.id || firstItem.description || firstItem.content)
        ) {
          return value;
        }
      } else if (typeof value === 'object' && value !== null) {
        // Recurse into objects
        const found = this.findExpectationsArray(value, depth + 1);
        if (found) {
return found;
}
      }
    }

    return null;
  }

  /**
   * Parse individual expectation
   */
  private parseExpectation(
    item: JSONExpectation,
    defaultGrade?: number,
    defaultSubject?: string
  ): ParsedExpectation | null {
    // Extract code
    const code = this.cleanText(
      item.code || item.id || `EXP-${Date.now()}-${Math.random()}`
    );

    // Extract description
    const description = this.cleanText(
      item.description || item.content || item.text || ''
    );

    if (!description) {
return null;
}

    // Extract type
    const type = this.parseExpectationTypeFromJSON(
      item.type || item.category || '',
      code,
      description
    );

    // Extract strand
    const strand = this.cleanText(
      item.strand || item.domain || this.extractStrandFromCode(code)
    );

    // Extract other fields
    const expectation: ParsedExpectation = {
      code,
      description,
      type: type === 'overall' || type === 'specific' ? type : 'specific',
      strand,
      substrand: item.substrand || item.topic,
      grade: this.parseGrade(item.grade || item.level) || defaultGrade,
      subject: item.subject || item.course || defaultSubject,
    };

    // Handle keywords
    if (item.keywords && Array.isArray(item.keywords)) {
      expectation.keywords = item.keywords;
    } else if (this.options.extractKeywords) {
      expectation.keywords = this.extractKeywords(description);
    }

    return expectation;
  }

  /**
   * Parse grade value
   */
  private parseGrade(value: unknown): number | undefined {
    if (typeof value === 'number') {
      return value;
    }

    if (typeof value === 'string') {
      const numeric = parseInt(value.replace(/\D/g, ''));
      if (!isNaN(numeric) && numeric >= 1 && numeric <= 12) {
        return numeric;
      }
    }

    return undefined;
  }

  /**
   * Parse expectation type from JSON value or fallback to parent logic
   */
  private parseExpectationTypeFromJSON(typeValue: string, code: string, description: string): 'overall' | 'specific' {
    if (typeValue) {
      const normalized = typeValue.toLowerCase();
      if (normalized.includes('overall')) {
return 'overall';
}
      if (normalized.includes('specific')) {
return 'specific';
}
      if (normalized === 'o') {
return 'overall';
}
      if (normalized === 's') {
return 'specific';
}
    }

    return super.parseExpectationType(code, description);
  }

  /**
   * Extract strand from code
   */
  private extractStrandFromCode(code: string): string {
    const parts = code.split('.');
    if (parts.length >= 2) {
      return parts[1];
    }
    return 'General';
  }

  /**
   * Organize expectations
   */
  private organizeExpectations(expectations: ParsedExpectation[]): ParsedExpectation[] {
    // Group by strand, then by type
    const grouped = new Map<string, { overall: ParsedExpectation[]; specific: ParsedExpectation[] }>();

    for (const exp of expectations) {
      if (!grouped.has(exp.strand)) {
        grouped.set(exp.strand, { overall: [], specific: [] });
      }

      const group = grouped.get(exp.strand);
      if (group) {
        if (exp.type === 'overall') {
          group.overall.push(exp);
        } else {
          group.specific.push(exp);
        }
      }
    }

    // Sort and flatten
    const organized: ParsedExpectation[] = [];

    for (const [_strand, group] of grouped) {
      // Sort within groups
      group.overall.sort((a, b) => a.code.localeCompare(b.code));
      group.specific.sort((a, b) => a.code.localeCompare(b.code));

      // Add to organized list
      organized.push(...group.overall, ...group.specific);
    }

    return organized;
  }

  /**
   * Validate parsed curriculum
   */
  validate(data: ParsedCurriculum): boolean {
    if (!data.subject || !data.grade || !data.expectations) {
      return false;
    }

    if (data.expectations.length === 0) {
      return false;
    }

    // Validate each expectation
    for (const exp of data.expectations) {
      if (!exp.code || !exp.description || !exp.type || !exp.strand) {
        return false;
      }
    }

    return true;
  }

  /**
   * Get supported file extensions
   */
  getSupportedExtensions(): string[] {
    return ['.json'];
  }
}

/**
 * PDF Curriculum Parser
 * Parses curriculum expectations from PDF files
 */

// Temporarily disabled to avoid startup issues
// import * as pdfParse from 'pdf-parse';
import { pdfParse } from '../../../__mocks__/pdf-parse';

import type { ParsedCurriculum, ParsedExpectation } from './CurriculumParser';
import { CurriculumParser } from './CurriculumParser';

export interface PDFSection {
  title: string;
  content: string;
  pageNumber: number;
}

export class PDFParser extends CurriculumParser {
  /**
   * Parse PDF content
   */
  async parse(content: string | Buffer): Promise<ParsedCurriculum> {
    // Parse PDF
    const buffer = content instanceof Buffer ? content : Buffer.from(content);
    const data = await pdfParse(buffer);

    if (!data.text) {
      throw new Error('No text content found in PDF');
    }

    // Extract metadata from PDF info
    const metadata = this.extractMetadata(data);

    // Split into sections
    const sections = this.extractSections(data.text);

    // Find curriculum sections
    const curriculumSections = this.findCurriculumSections(sections);

    if (curriculumSections.length === 0) {
      throw new Error('No curriculum expectations found in PDF');
    }

    // Parse expectations from sections
    const expectations: ParsedExpectation[] = [];

    for (const section of curriculumSections) {
      const sectionExpectations = this.parseSection(section, metadata);
      expectations.push(...sectionExpectations);
    }

    const curriculum: ParsedCurriculum = {
      subject: metadata.subject ?? 'Unknown',
      grade: metadata.grade ?? 0,
      expectations: this.deduplicateExpectations(expectations),
      metadata: {
        source: 'PDF Import',
        lastUpdated: new Date(),
        version: metadata.version,
      },
    };

    if (!this.validate(curriculum)) {
      throw new Error('Invalid curriculum data structure');
    }

    return curriculum;
  }

  /**
   * Extract metadata from PDF
   */
  private extractMetadata(pdfData: unknown): {
    grade?: number;
    subject?: string;
    version?: string;
  } {
    const metadata: {
      grade?: number;
      subject?: string;
      version?: string;
    } = {};

    // Try to extract from PDF metadata
    if (pdfData && typeof pdfData === 'object' && 'info' in pdfData) {
      const {info} = (pdfData as { info?: { Title?: string; Subject?: string } });
      metadata.version = info.Title ?? info.Subject;
    }

    // Extract from text content
    const text =
      pdfData && typeof pdfData === 'object' && 'text' in pdfData
        ? (pdfData as { text: string }).text
        : '';

    // Look for grade
    const gradeMatch = text.match(/Grade\s*(\d+)/i);
    if (gradeMatch) {
      metadata.grade = parseInt(gradeMatch[1]);
    }

    // Look for subject
    const subjects = [
      'Mathematics',
      'Language',
      'Science',
      'Social Studies',
      'The Arts',
      'Health and Physical Education',
      'French',
    ];

    for (const subject of subjects) {
      if (text.includes(subject)) {
        metadata.subject = subject;
        break;
      }
    }

    return metadata;
  }

  /**
   * Extract sections from PDF text
   */
  private extractSections(text: string): PDFSection[] {
    const sections: PDFSection[] = [];

    // Split by common section headers
    const sectionPatterns = [
      /^Overall Expectations?$/im,
      /^Specific Expectations?$/im,
      /^Strand [A-Z]:/im,
      /^[A-Z0-9]+\.\s+[A-Z][^.]+$/m,
    ];

    // Split text into lines
    const lines = text.split('\n');
    let currentSection: PDFSection | null = null;
    let pageNumber = 1;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();

      // Check for page break
      if (line.includes('Page') && line.match(/\d+/)) {
        const match = line.match(/Page\s*(\d+)/i);
        if (match) {
          pageNumber = parseInt(match[1]);
        }
      }

      // Check if line is a section header
      let isHeader = false;
      for (const pattern of sectionPatterns) {
        if (pattern.test(line)) {
          isHeader = true;
          break;
        }
      }

      if (isHeader) {
        // Save previous section
        if (currentSection) {
          sections.push(currentSection);
        }

        // Start new section
        currentSection = {
          title: line,
          content: '',
          pageNumber,
        };
      } else if (currentSection && line.length > 0) {
        // Add to current section
        currentSection.content += `${line  }\n`;
      }
    }

    // Save last section
    if (currentSection) {
      sections.push(currentSection);
    }

    return sections;
  }

  /**
   * Find sections containing curriculum expectations
   */
  private findCurriculumSections(sections: PDFSection[]): PDFSection[] {
    return sections.filter((section) => {
      const title = section.title.toLowerCase();
      const content = section.content.toLowerCase();

      return (
        title.includes('expectation') ||
        title.includes('strand') ||
        content.includes('students will') ||
        content.includes('demonstrate') ||
        content.includes('understanding')
      );
    });
  }

  /**
   * Parse expectations from a section
   */
  private parseSection(
    section: PDFSection,
    metadata: { grade?: number; subject?: string },
  ): ParsedExpectation[] {
    const expectations: ParsedExpectation[] = [];

    // Determine if this is overall or specific expectations
    const isOverall = section.title.toLowerCase().includes('overall');
    const type: 'overall' | 'specific' = isOverall ? 'overall' : 'specific';

    // Extract strand from section title
    const strand = this.extractStrand(section.title) ?? 'General';

    // Parse expectations using different patterns
    const patterns = [
      // Pattern 1: Code. Description
      /([A-Z0-9]+\.[A-Z0-9]+(?:\.[A-Z0-9]+)?)\.\s*(.+?)(?=\n[A-Z0-9]+\.|$)/gs,
      // Pattern 2: Numbered list
      /(\d+)\.\s*(.+?)(?=\n\d+\.|$)/gs,
      // Pattern 3: Bullet points
      /[•·]\s*(.+?)(?=\n[•·]|$)/gs,
    ];

    for (const pattern of patterns) {
      const matches = [...section.content.matchAll(pattern)];

      for (const match of matches) {
        let code: string;
        let description: string;

        if (match.length >= 3) {
          // Pattern with code and description
          code = match[1];
          description = match[2];
        } else if (match.length >= 2) {
          // Pattern with just description
          code = `${strand}.${expectations.length + 1}`;
          description = match[1];
        } else {
          continue;
        }

        description = this.cleanText(description);

        if (description.length < 10) {
continue;
} // Skip very short descriptions

        const expectation: ParsedExpectation = {
          code: this.cleanText(code),
          description,
          type,
          strand,
          grade: metadata.grade,
          subject: metadata.subject,
        };

        if (this.options.extractKeywords) {
          expectation.keywords = this.extractKeywords(description);
        }

        expectations.push(expectation);
      }

      // If we found expectations with this pattern, don't try others
      if (expectations.length > 0) {
        break;
      }
    }

    return expectations;
  }

  /**
   * Extract strand from section title
   */
  private extractStrand(title: string): string | undefined {
    // Pattern: Strand A: Number Sense
    const strandMatch = title.match(/Strand\s*([A-Z]):\s*(.+)/i);
    if (strandMatch) {
      return strandMatch[2].trim();
    }

    // Pattern: A. Number Sense
    const letterMatch = title.match(/^([A-Z])\.\s*(.+)/);
    if (letterMatch) {
      return letterMatch[2].trim();
    }

    // Check for known strand names
    const strandNames = [
      'Number Sense',
      'Measurement',
      'Geometry',
      'Patterning',
      'Data Management',
      'Probability',
      'Algebra',
    ];

    for (const strandName of strandNames) {
      if (title.includes(strandName)) {
        return strandName;
      }
    }

    return undefined;
  }

  /**
   * Remove duplicate expectations
   */
  private deduplicateExpectations(expectations: ParsedExpectation[]): ParsedExpectation[] {
    const seen = new Set<string>();
    const unique: ParsedExpectation[] = [];

    for (const exp of expectations) {
      const key = `${exp.code}-${exp.description.substring(0, 50)}`;
      if (!seen.has(key)) {
        seen.add(key);
        unique.push(exp);
      }
    }

    return unique;
  }

  /**
   * Validate parsed curriculum
   */
  validate(data: ParsedCurriculum): boolean {
    if (!data.subject || !data.grade || !data.expectations) {
      return false;
    }

    if (data.expectations.length === 0) {
      return false;
    }

    return true;
  }

  /**
   * Get supported file extensions
   */
  getSupportedExtensions(): string[] {
    return ['.pdf'];
  }
}

/**
 * Parser Factory
 * Creates appropriate parser based on file type
 */

import path from 'path';

import { CSVParser } from './CSVParser';
import type { CurriculumParser, ParserOptions } from './CurriculumParser';
import { ExcelParser } from './ExcelParser';
import { JSONParser } from './JSONParser';
import { PDFParser } from './PDFParser';

export class ParserFactory {
  private static parsers = new Map<string, new (options?: ParserOptions) => CurriculumParser>([
    ['.csv', CSVParser],
    ['.txt', CSVParser],
    ['.xlsx', ExcelParser],
    ['.xls', ExcelParser],
    ['.xlsm', ExcelParser],
    ['.pdf', PDFParser],
    ['.json', JSONParser],
  ]);

  /**
   * Create parser for file
   */
  static createParser(
    filename: string,
    options?: ParserOptions
  ): CurriculumParser {
    const ext = path.extname(filename).toLowerCase();

    const ParserClass = this.parsers.get(ext);

    if (!ParserClass) {
      throw new Error(`Unsupported file type: ${ext}`);
    }

    return new ParserClass(options);
  }

  /**
   * Get supported file extensions
   */
  static getSupportedExtensions(): string[] {
    return Array.from(this.parsers.keys());
  }

  /**
   * Check if file type is supported
   */
  static isSupported(filename: string): boolean {
    const ext = path.extname(filename).toLowerCase();
    return this.parsers.has(ext);
  }

  /**
   * Register custom parser
   */
  static registerParser(
    extension: string,
    parserClass: new (options?: ParserOptions) => CurriculumParser
  ): void {
    this.parsers.set(extension.toLowerCase(), parserClass);
  }

  /**
   * Create parser from MIME type
   */
  static createParserFromMimeType(
    mimeType: string,
    options?: ParserOptions
  ): CurriculumParser {
    const mimeToExt: Record<string, string> = {
      'text/csv': '.csv',
      'text/plain': '.txt',
      'application/vnd.ms-excel': '.xls',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': '.xlsx',
      'application/pdf': '.pdf',
      'application/json': '.json',
    };

    const ext = mimeToExt[mimeType];

    if (!ext) {
      throw new Error(`Unsupported MIME type: ${mimeType}`);
    }

    const ParserClass = this.parsers.get(ext);

    if (!ParserClass) {
      throw new Error(`No parser found for MIME type: ${mimeType}`);
    }

    return new ParserClass(options);
  }
}

