    this.initializeCategories();
  }

  /**
   * Initialize partial categories
   */
  private initializeCategories(): void {
    this.categories.set('layout', {
      name: 'Layout',
      description: 'Headers, footers, and structural components',
      partials: [],
    });

    this.categories.set('student', {
      name: 'Student',
      description: 'Student-related information displays',
      partials: [],
    });

    this.categories.set('educational', {
      name: 'Educational',
      description: 'Educational content like grades and assignments',
      partials: [],
    });

    this.categories.set('newsletter', {
      name: 'Newsletter',
      description: 'Newsletter-specific components',
      partials: [],
    });

    this.categories.set('charts', {
      name: 'Charts',
      description: 'Data visualization components',
      partials: [],
    });

    this.categories.set('contact', {
      name: 'Contact',
      description: 'Contact information displays',
      partials: [],
    });

    // Populate category partial lists
    this.updateCategoryMembership();
  }

  /**
   * Register a partial
   */
  public registerPartial(name: string, partial: Omit<PartialInfo, 'name'>): void {
    this.partials.set(name, { name, ...partial });

    // Update category membership
    this.updateCategoryMembership();

    this.logger.debug(`Partial registered: ${name} (category: ${partial.category})`);
  }

  /**
   * Get partial content
   */
  public getPartial(name: string): string | null {
    const partial = this.partials.get(name);
    return partial ? partial.content : null;
  }

  /**
   * Get all partials as a record for template engines
   */
  public getPartialsRecord(): Record<string, string> {
    const record: Record<string, string> = {};

    for (const [name, partial] of this.partials) {
      record[name] = partial.content;
    }

    return record;
  }

  /**
   * Get partial info
   */
  public getPartialInfo(name: string): PartialInfo | null {
    return this.partials.get(name) ?? null;
  }

  /**
   * List all partials
   */
  public listPartials(): PartialInfo[] {
    return Array.from(this.partials.values());
  }

  /**
   * Get partials by category
   */
  public getPartialsByCategory(category: string): PartialInfo[] {
    return Array.from(this.partials.values()).filter((p) => p.category === category);
  }

  /**
   * List all categories
   */
  public listCategories(): PartialCategory[] {
    return Array.from(this.categories.values());
  }

  /**
   * Search partials
   */
  public searchPartials(query: string): PartialInfo[] {
    const lowerQuery = query.toLowerCase();

    return Array.from(this.partials.values()).filter(
      (partial) =>
        partial.name.toLowerCase().includes(lowerQuery) ||
        (partial.description && partial.description.toLowerCase().includes(lowerQuery)) ||
        partial.content.toLowerCase().includes(lowerQuery),
    );
  }

  /**
   * Load partials from file system
   */
  private async loadPartialsFromFiles(): Promise<void> {
    try {
      // Check if partials directory exists
      try {
        await fs.access(this.partialsDirectory);
      } catch (_error) {
        this.logger.info('Partials directory does not exist, skipping file loading');
        return;
      }

      const files = await fs.readdir(this.partialsDirectory);
      const partialFiles = files.filter(
        (file) => file.endsWith('.hbs') || file.endsWith('.handlebars') || file.endsWith('.html'),
      );

      for (const file of partialFiles) {
        try {
          const filePath = path.join(this.partialsDirectory, file);
          const content = await fs.readFile(filePath, 'utf-8');
          const stats = await fs.stat(filePath);

          const name = path.basename(file, path.extname(file));
          const category = this.inferCategoryFromFilename(name);

          this.registerPartial(name, {
            content: content.trim(),
            category,
            description: `Loaded from ${file}`,
            variables: this.extractVariables(content),
            lastModified: stats.mtime,
            source: 'file',
          });

          this.logger.debug('Partial loaded from file');
        } catch (_error) {
          this.logger.error(`Failed to load partial file: ${file} - ${_error instanceof Error ? _error.message : _error}`);
        }
      }

      this.logger.info(`Partials loaded from files: ${partialFiles.length} loaded from ${this.partialsDirectory}`);
    } catch (_error) {
      this.logger.error(`Failed to load partials from files in ${this.partialsDirectory}: ${_error instanceof Error ? _error.message : _error}`);
    }
  }

  /**
   * Save partial to file
   */
  public async savePartialToFile(name: string): Promise<void> {
    const partial = this.partials.get(name);
    if (!partial) {
      throw new Error(`Partial not found: ${name}`);
    }

    try {
      // Ensure directory exists
      await fs.mkdir(this.partialsDirectory, { recursive: true });

      const filePath = path.join(this.partialsDirectory, `${name}.hbs`);
      await fs.writeFile(filePath, partial.content, 'utf-8');

      // Update partial info
      partial.source = 'file';
      partial.lastModified = new Date();

      this.logger.info(`Partial saved to file: ${name} -> ${filePath}`);
    } catch (_error) {
      this.logger.error(`Failed to save partial to file ${name}: ${_error instanceof Error ? _error.message : _error}`);
      throw _error;
    }
  }

  /**
   * Delete partial
   */
  public removePartial(name: string): boolean {
    const removed = this.partials.delete(name);
    if (removed) {
      this.updateCategoryMembership();
      this.logger.debug(`Partial removed: ${name}`);
    }
    return removed;
  }

  /**
   * Update partial content
   */
  public updatePartial(name: string, content: string, description?: string): void {
    const partial = this.partials.get(name);
    if (partial) {
      partial.content = content;
      partial.lastModified = new Date();
      partial.variables = this.extractVariables(content);

      if (description) {
        partial.description = description;
      }

      this.logger.debug(`Partial updated: ${name}`);
    } else {
      throw new Error(`Partial not found: ${name}`);
    }
  }

  /**
   * Extract variables from template content
   */
  private extractVariables(content: string): string[] {
    const variables = new Set<string>();

    // Match Handlebars variables: {{variable}} or {{object.property}}
    const variableRegex = /\{\{([^{}#/]+)\}\}/g;
    let match;

    while ((match = variableRegex.exec(content)) !== null) {
      const variable = match[1].trim();

      // Skip helpers and special syntax
      if (
        !variable.startsWith('#') &&
        !variable.startsWith('/') &&
        !variable.startsWith('else') &&
        !variable.startsWith('this.')
      ) {
        variables.add(variable);
      }
    }

    return Array.from(variables);
  }

  /**
   * Infer category from filename
   */
  private inferCategoryFromFilename(name: string): string {
    const lowerName = name.toLowerCase();

    if (
      lowerName.includes('header') ||
      lowerName.includes('footer') ||
      lowerName.includes('layout')
    ) {
      return 'layout';
    }
    if (lowerName.includes('student')) {
      return 'student';
    }
    if (
      lowerName.includes('grade') ||
      lowerName.includes('assignment') ||
      lowerName.includes('lesson')
    ) {
      return 'educational';
    }
    if (lowerName.includes('newsletter')) {
      return 'newsletter';
    }
    if (lowerName.includes('chart') || lowerName.includes('graph')) {
      return 'charts';
    }
    if (lowerName.includes('contact') || lowerName.includes('teacher')) {
      return 'contact';
    }

    return 'misc';
  }

  /**
   * Update category membership
   */
  private updateCategoryMembership(): void {
    // Clear current memberships
    for (const category of this.categories.values()) {
      category.partials = [];
    }

    // Rebuild memberships
    for (const partial of this.partials.values()) {
      if (partial.category) {
        const category = this.categories.get(partial.category);
        if (category) {
          category.partials.push(partial.name);
        }
      }
    }
  }

  /**
   * Validate partial dependencies
   */
  public validateDependencies(): {
    valid: string[];
    invalid: { name: string; missing: string[] }[];
  } {
    const valid: string[] = [];
    const invalid: { name: string; missing: string[] }[] = [];

    for (const [name, partial] of this.partials) {
      if (partial.dependencies && partial.dependencies.length > 0) {
        const missing = partial.dependencies.filter((dep) => !this.partials.has(dep));

        if (missing.length > 0) {
          invalid.push({ name, missing });
        } else {
          valid.push(name);
        }
      } else {
        valid.push(name);
      }
    }

    return { valid, invalid };
  }

  /**
   * Get usage statistics
   */
  public getUsageStats(): {
    totalPartials: number;
    byCategory: Record<string, number>;
    bySource: Record<string, number>;
    averageVariables: number;
  } {
    const stats = {
      totalPartials: this.partials.size,
      byCategory: {} as Record<string, number>,
      bySource: {} as Record<string, number>,
      averageVariables: 0,
    };

    let totalVariables = 0;

    for (const partial of this.partials.values()) {
      // Count by category
      if (partial.category) {
        stats.byCategory[partial.category] = (stats.byCategory[partial.category] ?? 0) + 1;
      }

      // Count by source
      stats.bySource[partial.source] = (stats.bySource[partial.source] ?? 0) + 1;

      // Count variables
      totalVariables += partial.variables.length ?? 0;
    }

    stats.averageVariables = this.partials.size > 0 ? totalVariables / this.partials.size : 0;

    return stats;
  }
}

// Export singleton instance
export const partialManager = PartialManager.getInstance();

/* eslint-disable @typescript-eslint/no-explicit-any */
/**
 * Render Coordinator Service
 * Coordinates the template rendering process using all template services
 */

import { BaseService } from '../base/BaseService';

import type { FetchContext } from './data/TemplateDataFetcher';
import { TemplateDataFetcher } from './data/TemplateDataFetcher';
import type { RenderResult, RenderContext } from './engines/RenderEngine';
import { PartialManager } from './PartialManager';
import type { TemplateProvider, TemplateContext, RenderOptions, Template } from './providers/TemplateProvider';
import { TemplateCache } from './TemplateCache';
import { TemplateHelpers } from './TemplateHelpers';
import { TemplateRegistry } from './TemplateRegistry';

export interface RenderRequest {
  context: TemplateContext;
  options: RenderOptions & {
    templateType: string;
    templateId?: string;
    data?: Record<string, unknown>;
    filters?: Record<string, unknown>;
    fetchData?: boolean;
    useCache?: boolean;
  };
}

export interface RenderResponse extends RenderResult {
  cacheHit?: boolean;
  renderTime: number;
  dataFetchTime?: number;
  templateResolutionTime: number;
}

export class RenderCoordinator extends BaseService {
  private static instance: RenderCoordinator | undefined;
  private registry: TemplateRegistry;
  private cache: TemplateCache;
  private helpers: TemplateHelpers;
  private partialManager: PartialManager;
  private dataFetcher: TemplateDataFetcher;

  private constructor() {
    super('RenderCoordinator');
    this.registry = TemplateRegistry.getInstance();
    this.cache = TemplateCache.getInstance();
    this.helpers = TemplateHelpers.getInstance();
    this.partialManager = PartialManager.getInstance();
    this.dataFetcher = new TemplateDataFetcher();
  }

  /**
   * Get singleton instance
   */
  public static getInstance(): RenderCoordinator {
    if (!RenderCoordinator.instance) {
      RenderCoordinator.instance = new RenderCoordinator();
    }
    return RenderCoordinator.instance;
  }

  /**
   * Initialize service
   */
  protected async initialize(): Promise<void> {
    await super.initialize();

    // Dependent services will initialize themselves on first use
    // No need to explicitly initialize them here

    this.logger.info('Render coordinator initialized');
  }

  /**
   * Check dependencies
   */
  protected checkDependencies(): Record<string, boolean> {
    const baseDeps = super.checkDependencies();
    return {
      ...baseDeps,
      registry: this.registry.isHealthy(),
      cache: this.cache.isHealthy(),
      helpers: this.helpers.isHealthy(),
      partialManager: this.partialManager.isHealthy(),
      dataFetcher: !!this.dataFetcher,
    };
  }

  /**
   * Main render method
   */
  public async render(request: RenderRequest): Promise<RenderResponse> {
    return this.executeWithMetrics(
      async () => {
        const startTime = Date.now();
        const { context, options } = request;

        // Step 1: Check cache first
        let cacheHit = false;
        if (options.useCache !== false) {
          const cacheKey = this.generateCacheKey(context, options);
          const cachedResult = this.cache.get(cacheKey);

          if (cachedResult) {
            cacheHit = true;
            const renderTime = Date.now() - startTime;

            this.logger.debug(`Returning cached render result: cacheKey=${cacheKey}, renderTime=${renderTime}ms`);

            return {
              ...cachedResult,
              cacheHit,
              renderTime,
              templateResolutionTime: 0,
            };
          }
        }

        // Step 2: Resolve template provider and template
        const templateStartTime = Date.now();
        const { provider: _provider, template } = await this.resolveTemplate(options.templateType, context, options);
        const templateResolutionTime = Date.now() - templateStartTime;

        // Step 3: Fetch data if needed
        let data = options.data || {};
        let dataFetchTime: number | undefined;

        if (options.fetchData !== false && template.dataRequirements.length > 0) {
          const fetchStartTime = Date.now();
          data = await this.fetchTemplateData(template, context, options);
          dataFetchTime = Date.now() - fetchStartTime;
        }

        // Step 4: Resolve render engine
        const engine = this.registry.getEngine(template.engine);
        if (!engine) {
          throw new Error(`Render engine not found: ${template.engine}`);
        }

        // Step 5: Prepare render context
        const renderContext = await this.prepareRenderContext(data, options);

        // Step 6: Perform rendering
        const result = await engine.render(template, renderContext);

        // Step 7: Cache result if appropriate
        if (options.useCache !== false && !options.debug) {
          const cacheKey = this.generateCacheKey(context, options);
          this.cache.set(cacheKey, result);
        }

        const totalRenderTime = Date.now() - startTime;

        this.logger.info(`Template rendered successfully: type=${options.templateType}, id=${template.id}, engine=${template.engine}, format=${result.format}, renderTime=${totalRenderTime}ms, templateResolutionTime=${templateResolutionTime}ms, dataFetchTime=${dataFetchTime}ms, cacheHit=false`);

        return {
          ...result,
          cacheHit: false,
          renderTime: totalRenderTime,
          dataFetchTime,
          templateResolutionTime,
        };
      },
      `render-${request.options.templateType}`
    );
  }

  /**
   * Render multiple templates in batch
   */
  public async renderBatch(requests: RenderRequest[]): Promise<RenderResponse[]> {
    return this.executeWithMetrics(
      async () => {
        const results = await Promise.all(
          requests.map(request => this.render(request))
        );

        this.logger.info(`Batch rendering completed: requestCount=${requests.length}, totalTime=${results.reduce((sum, r) => sum + r.renderTime, 0)}ms`);

        return results;
      },
      'renderBatch'
    );
  }

  /**
   * Resolve template provider and template
   */
  private async resolveTemplate(
    templateType: string, 
    context: TemplateContext, 
    options: RenderRequest['options']
  ): Promise<{ provider: TemplateProvider; template: Template }> {
    // Get provider
    const provider = this.registry.getProvider(templateType);
    if (!provider) {
      throw new Error(`Template provider not found: ${templateType}`);
    }

    // Validate context
    if (!provider.validateContext(context)) {
      throw new Error('Invalid template context for provider');
    }

    // Build template context
    const templateContext: TemplateContext = {
      ...context,
      templateId: options.templateId,
      parameters: {
        ...context.parameters,
        ...options,
      },
    };

    // Get template
    const template = await provider.getTemplate(templateContext);
    if (!template) {
      throw new Error(`Template not found: ${templateType}:${options.templateId || 'default'}`);
    }

    return { provider, template };
  }

  /**
   * Fetch template data
   */
  private async fetchTemplateData(
    template: Template,
    context: TemplateContext,
    options: RenderRequest['options']
  ): Promise<Record<string, unknown>> {
    const fetchContext: FetchContext = {
      userId: context.userId,
      filters: options.filters,
      options: {
        includeRelations: true,
      },
    };

    const fetchedData = await this.dataFetcher.fetchData(
      template.dataRequirements,
      fetchContext
    );

    // Merge with provided data (provided data takes precedence)
    return { ...fetchedData, ...options.data };
  }

  /**
   * Prepare render context
   */
  private async prepareRenderContext(
    data: Record<string, unknown>,
    options: RenderRequest['options']
  ): Promise<RenderContext> {
    return {
      data,
      helpers: this.helpers.getHelpersRecord(),
      partials: this.partialManager.getPartialsRecord(),
      options: {
        format: options.format,
        locale: options.locale,
        timezone: options.timezone,
        includeStyles: options.includeStyles,
        debug: options.debug,
      },
    };
  }

  /**
   * Generate cache key
   */
  private generateCacheKey(
    context: TemplateContext, 
    options: RenderRequest['options']
  ): string {
    const keyParts = [
      options.templateType,
      options.templateId || 'default',
      context.userId.toString(),
      options.format || 'html',
      options.locale || 'en',
    ];

    // Add filters to key if present
    if (options.filters && Object.keys(options.filters).length > 0) {
      keyParts.push(JSON.stringify(options.filters));
    }

    // Add data hash if provided
    if (options.data && Object.keys(options.data).length > 0) {
      keyParts.push(this.hashObject(options.data));
    }

    return keyParts.join('|');
  }

  /**
   * Hash object for cache key
   */
  private hashObject(obj: unknown): string {
    const str = JSON.stringify(obj, Object.keys(obj as any).sort());
    let hash = 0;

    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32-bit integer
    }

    return hash.toString(36);
  }

  /**
   * Preview template with sample data
   */
  public async previewTemplate(
    templateType: string,
    templateId: string,
    sampleData: Record<string, unknown> = {},
    options: Partial<RenderRequest['options']> = {}
  ): Promise<RenderResponse> {
    const request: RenderRequest = {
      context: {
        userId: 0, // Preview user
        parameters: {},
      },
      options: {
        templateType,
        templateId,
        data: sampleData,
        fetchData: false,
        useCache: false,
        debug: true,
        format: 'html',
        ...options,
      },
    };

    return this.render(request);
  }

  /**
   * Validate template rendering capability
   */
  public async validateTemplate(
    templateType: string,
    templateId?: string
  ): Promise<{
    isValid: boolean;
    issues: string[];
    recommendations: string[];
  }> {
    const issues: string[] = [];
    const recommendations: string[] = [];

    try {
      // Check if provider exists
      const provider = this.registry.getProvider(templateType);
      if (!provider) {
        issues.push(`Template provider not found: ${templateType}`);
        return { isValid: false, issues, recommendations };
      }

      // Check if template exists
      if (templateId) {
        const template = await provider.getTemplateById(templateId);
        if (!template) {
          issues.push(`Template not found: ${templateId}`);
        } else {
          // Check if engine exists
          const engine = this.registry.getEngine(template.engine);
          if (!engine) {
            issues.push(`Render engine not found: ${template.engine}`);
          }

          // Check data requirements
          if (template.dataRequirements.length > 0) {
            recommendations.push('Template requires data fetching - ensure data sources are available');
          }

          // Check for missing variables in template
          const variables = this.extractTemplateVariables(template.content);
          if (variables.length > 0) {
            recommendations.push(`Template uses variables: ${variables.join(', ')}`);
          }
        }
      }

      // Check helper availability
      const missingHelpers = this.checkRequiredHelpers(templateType);
      if (missingHelpers.length > 0) {
        issues.push(`Missing required helpers: ${missingHelpers.join(', ')}`);
      }

      // Check partial availability
      const missingPartials = this.checkRequiredPartials(templateType);
      if (missingPartials.length > 0) {
        issues.push(`Missing required partials: ${missingPartials.join(', ')}`);
      }

    } catch (_error) {
      issues.push(`Validation error: ${_error instanceof Error ? _error.message : _error}`);
    }

    return {
      isValid: issues.length === 0,
      issues,
      recommendations,
    };
  }

  /**
   * Extract variables from template content
   */
  private extractTemplateVariables(content: string): string[] {
    const variables = new Set<string>();
    const variableRegex = /\{\{([^{}#/]+)\}\}/g;
    let match;

    while ((match = variableRegex.exec(content)) !== null) {
      const variable = match[1].trim();
      if (!variable.startsWith('#') && !variable.startsWith('/') && 
          !variable.startsWith('else') && !variable.startsWith('this.')) {
        variables.add(variable);
      }
    }

    return Array.from(variables);
  }

  /**
   * Check required helpers for template type
   */
  private checkRequiredHelpers(templateType: string): string[] {
    const missingHelpers: string[] = [];

    // Define required helpers by template type
    const requiredHelpers: Record<string, string[]> = {
      lesson: ['formatDate', 'gradeLevel'],
      newsletter: ['formatDate', 'truncate'],
      report: ['formatGrade', 'percentage', 'formatDate'],
    };

    const required = requiredHelpers[templateType] ?? [];

    for (const helper of required) {
      if (!this.helpers.getHelper(helper)) {
        missingHelpers.push(helper);
      }
    }

    return missingHelpers;
  }

  /**
   * Check required partials for template type
   */
  private checkRequiredPartials(templateType: string): string[] {
    const missingPartials: string[] = [];

    // Define required partials by template type
    const requiredPartials: Record<string, string[]> = {
      lesson: ['header', 'footer'],
      newsletter: ['header', 'footer', 'newsletterSection'],
      report: ['header', 'footer', 'studentInfo'],
    };

    const required = requiredPartials[templateType] ?? [];

    for (const partial of required) {
      if (!this.partialManager.getPartial(partial)) {
        missingPartials.push(partial);
      }
    }

    return missingPartials;
  }

  /**
   * Get rendering statistics
   */
  public async getRenderingStats(): Promise<{
    cacheStats: unknown;
    registryStats: unknown;
    recentRenders: {
      templateType: string;
      renderTime: number;
      cacheHit: boolean;
      timestamp: Date;
    }[];
  }> {
    return {
      cacheStats: this.cache.getStats(),
      registryStats: await this.registry.getStats(),
      recentRenders: [], // Would need to track this in implementation
    };
  }

  /**
   * Clear all caches
   */
  public clearCaches(): void {
    this.cache.clear();
    this.logger.info('All rendering caches cleared');
  }

  /**
   * Warm up caches with common templates
   */
  public async warmupCaches(
    commonTemplates: {
      templateType: string;
      templateId?: string;
      sampleData?: Record<string, unknown>;
    }[]
  ): Promise<void> {
    this.logger.info(`Starting cache warmup: templateCount=${commonTemplates.length}`);

    for (const template of commonTemplates) {
      try {
        await this.previewTemplate(
          template.templateType,
          template.templateId || 'default',
          template.sampleData || {}
        );
      } catch (_error) {
        this.logger.error(`Failed to warm up template cache for ${template.templateType}/${template.templateId || 'default'}: ${_error instanceof Error ? _error.message : _error}`);
      }
    }

    this.logger.info('Cache warmup completed');
  }

  /**
   * Cleanup resources
   */
  public async cleanup(): Promise<void> {
    await this.registry.cleanup();
    await this.cache.cleanup();
    await this.partialManager.cleanup();

    this.logger.info('Render coordinator cleanup completed');
  }
}

