/**
 * Pagination utilities for list endpoints
 * Provides consistent pagination across all API endpoints
 */

import type { Request, Response, NextFunction } from 'express';
import { z } from 'zod';

// Pagination query schema
export const paginationSchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
  sortBy: z.string().optional(),
  sortOrder: z.enum(['asc', 'desc']).default('desc'),
  search: z.string().optional(),
});

export type PaginationQuery = z.infer<typeof paginationSchema>;

export interface PaginationOptions {
  page: number;
  limit: number;
  sortBy?: string;
  sortOrder?: 'asc' | 'desc';
  search?: string;
}

export interface PaginatedResponse<T> {
  data: T[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
    hasNext: boolean;
    hasPrevious: boolean;
  };
  links?: {
    first?: string;
    previous?: string;
    next?: string;
    last?: string;
  };
}

export interface PaginationMeta {
  total: number;
  page: number;
  limit: number;
}

/**
 * Extract pagination parameters from request query
 */
export function getPaginationParams(req: Request): PaginationOptions {
  const result = paginationSchema.safeParse(req.query);

  if (!result.success) {
    // Return defaults if validation fails
    return {
      page: 1,
      limit: 20,
      sortOrder: 'desc',
    };
  }

  return {
    page: result.data.page ?? 1,
    limit: result.data.limit ?? 20,
    sortBy: result.data.sortBy,
    sortOrder: result.data.sortOrder ?? 'desc',
    search: result.data.search,
  };
}

/**
 * Calculate offset for database queries
 */
export function calculateOffset(page: number, limit: number): number {
  return (page - 1) * limit;
}

/**
 * Calculate total pages
 */
export function calculateTotalPages(total: number, limit: number): number {
  return Math.ceil(total / limit);
}

/**
 * Create paginated response
 */
export function createPaginatedResponse<T>(
  data: T[],
  meta: PaginationMeta,
  baseUrl?: string,
): PaginatedResponse<T> {
  const totalPages = calculateTotalPages(meta.total, meta.limit);
  const hasNext = meta.page < totalPages;
  const hasPrevious = meta.page > 1;

  const response: PaginatedResponse<T> = {
    data,
    pagination: {
      page: meta.page,
      limit: meta.limit,
      total: meta.total,
      totalPages,
      hasNext,
      hasPrevious,
    },
  };

  // Add navigation links if base URL provided
  if (baseUrl !== undefined && baseUrl !== null && baseUrl !== '') {
    response.links = {};

    const url = new URL(baseUrl);

    // First page
    if (meta.page > 1) {
      url.searchParams.set('page', '1');
      response.links.first = url.toString();
    }

    // Previous page
    if (hasPrevious) {
      url.searchParams.set('page', (meta.page - 1).toString());
      response.links.previous = url.toString();
    }

    // Next page
    if (hasNext) {
      url.searchParams.set('page', (meta.page + 1).toString());
      response.links.next = url.toString();
    }

    // Last page
    if (meta.page < totalPages) {
      url.searchParams.set('page', totalPages.toString());
      response.links.last = url.toString();
    }
  }

  return response;
}

/**
 * Prisma pagination helper
 */
export function getPrismaArgs(options: PaginationOptions): { skip: number; take: number; orderBy?: Record<string, 'asc' | 'desc'> } {
  const skip = calculateOffset(options.page, options.limit);

  const args: {
    skip: number;
    take: number;
    orderBy?: Record<string, 'asc' | 'desc'>;
  } = {
    skip,
    take: options.limit,
  };

  // Add sorting
  if (options.sortBy) {
    args.orderBy = {
      [options.sortBy]: options.sortOrder ?? 'desc',
    };
  }

  return args;
}

/**
 * Create cursor-based pagination for real-time data
 */
export interface CursorPaginationOptions {
  cursor?: string | number;
  limit: number;
  sortBy?: string;
  sortOrder?: 'asc' | 'desc';
}

export interface CursorPaginatedResponse<T> {
  data: T[];
  pagination: {
    limit: number;
    hasMore: boolean;
    nextCursor?: string | number;
  };
}

export function createCursorPaginatedResponse<T>(
  data: T[],
  limit: number,
  getCursor: (item: T) => string | number,
): CursorPaginatedResponse<T> {
  const hasMore = data.length > limit;
  const items = hasMore ? data.slice(0, limit) : data;

  return {
    data: items,
    pagination: {
      limit,
      hasMore,
      nextCursor: hasMore && items.length > 0 ? getCursor(items[items.length - 1]) : undefined,
    },
  };
}

/**
 * Middleware to validate pagination parameters
 */
export function validatePagination(req: Request, res: Response, next: NextFunction): void {
  const result = paginationSchema.safeParse(req.query);

  if (!result.success) {
    res.status(400).json({
      error: 'Invalid pagination parameters',
      details: result.error.flatten(),
    });
    return;
  }

  // Attach validated params to request
  (req as Request & { pagination: PaginationQuery }).pagination = result.data;
  next();
}

/**
 * Create pagination metadata for response headers
 */
export function setPaginationHeaders<T>(
  res: Response,
  pagination: PaginatedResponse<T>['pagination'],
) {
  res.set({
    'X-Page': pagination.page.toString(),
    'X-Limit': pagination.limit.toString(),
    'X-Total': pagination.total.toString(),
    'X-Total-Pages': pagination.totalPages.toString(),
    'X-Has-Next': pagination.hasNext.toString(),
    'X-Has-Previous': pagination.hasPrevious.toString(),
  });
}

/**
 * Search filter helper for Prisma
 */
export function createSearchFilter(
  search: string | undefined,
  fields: string[],
): Record<string, unknown> | undefined {
  if (search === undefined || search === '' || fields.length === 0) {
    return undefined;
  }

  return {
    OR: fields.map((field) => ({
      [field]: {
        contains: search,
        mode: 'insensitive',
      },
    })),
  };
}

/**
 * Combine multiple filters for Prisma where clause
 */
export function combineFilters(
  ...filters: (Record<string, unknown> | undefined | null)[]
): Record<string, unknown> | undefined {
  const validFilters = filters.filter((f) => f !== undefined && f !== null);

  if (validFilters.length === 0) {
    return undefined;
  }

  if (validFilters.length === 1) {
    return validFilters[0];
  }

  return {
    AND: validFilters,
  };
}

/**
 * Performance optimization: Parallel count and data fetch
 */
export async function fetchPaginatedData<T>(
  countQuery: () => Promise<number>,
  dataQuery: () => Promise<T[]>,
  _options: PaginationOptions,
): Promise<{ data: T[]; total: number }> {
  const [total, data] = await Promise.all([countQuery(), dataQuery()]);

  return { data, total };
}

/**
 * Pagination cache key generator
 */
export function generatePaginationCacheKey(
  entity: string,
  options: PaginationOptions,
  additionalParams?: Record<string, unknown>,
): string {
  const params = {
    ...options,
    ...additionalParams,
  };

  const sortedKeys = Object.keys(params).sort();
  const keyParts = sortedKeys.map((key) => `${key}:${(params as Record<string, unknown>)[key]}`);

  return `pagination:${entity}:${keyParts.join(':')}`;
}

/**
 * Privacy utilities for protecting user data
 * This application does not store any student data
 */

export interface PrivacyOptions {
  showFullData?: boolean;
  isOwner?: boolean;
}

/**
 * Masks sensitive user information based on privacy settings
 */
export function maskUserData(user: Record<string, unknown>, options: PrivacyOptions = {}): Record<string, unknown> | null {
  const {
    showFullData = true,
    isOwner = true,
  } = options;

  if (!user) {
return null;
}

  const masked = { ...user };

  // Mask email if not owner
  if (!showFullData && !isOwner && typeof user.email === 'string') {
    const [localPart, domain] = user.email.split('@');
    masked.email = `${localPart.slice(0, 2)}***@${domain}`;
  }

  // Always remove sensitive fields
  delete masked.password;
  delete masked.passwordResetToken;
  delete masked.passwordResetExpires;

  // Remove system fields if not owner
  if (!isOwner) {
    delete masked.createdAt;
    delete masked.updatedAt;
  }

  return masked;
}

/**
 * Generates a privacy-safe user identifier for logging
 */
export function getUserIdentifier(user: Record<string, unknown>): string {
  if (!user) {
return 'unknown';
}

  // Use partial email + partial ID for privacy
  const email = typeof user.email === 'string' ? user.email : 'unknown@example.com';
  const [localPart] = email.split('@');
  const idSuffix = user.id ? String(user.id).slice(-4) : '0000';

  return `${localPart.slice(0, 3)}-${idSuffix}`;
}

/**
 * Validates data access permissions
 */
export function validateDataAccess(
  userId: number,
  targetUserId: number,
  role = 'teacher'
): boolean {
  // Teachers can only access their own data
  if (role === 'teacher') {
    return userId === targetUserId;
  }

  // Admins can access any data
  if (role === 'admin') {
    return true;
  }

  return false;
}

/**
 * Sanitizes user data for export
 */
export function sanitizeUserDataForExport(users: Record<string, unknown>[]): Record<string, unknown>[] {
  return users.map(user => ({
    userId: getUserIdentifier(user),
    role: user.role ?? 'teacher',
    // Only include non-sensitive fields
    name: user.name,
    preferredLanguage: user.preferredLanguage,
  }));
}

/**
 * Anonymizes data for analytics
 */
export function anonymizeForAnalytics(data: Record<string, unknown>): Record<string, unknown> {
  const anonymized = { ...data };

  // Remove all PII
  delete anonymized.email;
  delete anonymized.name;
  delete anonymized.userId;

  // Replace with anonymous identifiers
  anonymized.userHash = data.userId ? hashUserId(Number(data.userId)) : 'anonymous';

  return anonymized;
}

/**
 * Simple hash function for user IDs
 */
function hashUserId(userId: number): string {
  // Simple hash for demo - in production use proper hashing
  return `user_${(userId * 7919) % 10000}`;
}

import type { Response } from 'express';

import { logger } from '../logger';

// Standard response types
export interface SuccessResponse<T = unknown> {
  success: true;
  data: T;
  meta?: {
    timestamp: string;
    requestId?: string;
    [key: string]: unknown;
  };
}

export interface PaginatedResponse<T = unknown> extends SuccessResponse<T[]> {
  meta: {
    timestamp: string;
    requestId?: string;
    pagination: {
      page: number;
      pageSize: number;
      totalPages: number;
      totalItems: number;
      hasNextPage: boolean;
      hasPreviousPage: boolean;
    };
  };
}

export interface CreatedResponse<T = unknown> extends SuccessResponse<T> {
  meta: {
    timestamp: string;
    requestId?: string;
    location?: string;
  };
}

// Response builders
export const successResponse = <T>(
  data: T,
  meta?: Omit<SuccessResponse['meta'], 'timestamp'>
): SuccessResponse<T> => ({
    success: true,
    data,
    meta: {
      timestamp: new Date().toISOString(),
      ...meta,
    },
  });

export const paginatedResponse = <T>(
  data: T[],
  page: number,
  pageSize: number,
  totalItems: number,
  meta?: Record<string, unknown>
): PaginatedResponse<T> => {
  const totalPages = Math.ceil(totalItems / pageSize);

  return {
    success: true,
    data,
    meta: {
      timestamp: new Date().toISOString(),
      ...meta,
      pagination: {
        page,
        pageSize,
        totalPages,
        totalItems,
        hasNextPage: page < totalPages,
        hasPreviousPage: page > 1,
      },
    },
  };
};

export const createdResponse = <T>(
  data: T,
  location?: string,
  meta?: Record<string, unknown>
): CreatedResponse<T> => ({
    success: true,
    data,
    meta: {
      timestamp: new Date().toISOString(),
      location,
      ...meta,
    },
  });

// Response senders
export const sendSuccess = <T>(
  res: Response,
  data: T,
  statusCode = 200,
  meta?: Record<string, unknown>
): void => {
  const response = successResponse(data, {
    requestId: res.locals.requestId as string | undefined,
    ...meta,
  });

  res.status(statusCode).json(response);
};

export const sendCreated = <T>(
  res: Response,
  data: T,
  location?: string,
  meta?: Record<string, unknown>
): void => {
  const response = createdResponse(data, location, {
    requestId: res.locals.requestId as string | undefined,
    ...meta,
  });

  if (location) {
    res.setHeader('Location', location);
  }

  res.status(201).json(response);
};

export const sendPaginated = <T>(
  res: Response,
  data: T[],
  page: number,
  pageSize: number,
  totalItems: number,
  meta?: Record<string, unknown>
): void => {
  const response = paginatedResponse(data, page, pageSize, totalItems, {
    requestId: res.locals.requestId as string | undefined,
    ...meta,
  });

  res.status(200).json(response);
};

export const sendNoContent = (res: Response): void => {
  res.status(204).send();
};

export const sendAccepted = <T>(
  res: Response,
  data?: T,
  meta?: Record<string, unknown>
): void => {
  if (data) {
    sendSuccess(res, data, 202, meta);
  } else {
    res.status(202).json({
      success: true,
      message: 'Request accepted for processing',
      meta: {
        timestamp: new Date().toISOString(),
        requestId: res.locals.requestId as string | undefined,
        ...meta,
      },
    });
  }
};

// Utility response helpers
export const sendFile = (
  res: Response,
  filePath: string,
  filename?: string,
  contentType?: string
): void => {
  if (contentType) {
    res.setHeader('Content-Type', contentType);
  }

  if (filename) {
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
  }

  res.sendFile(filePath, (err) => {
    if (err) {
      logger.error({ error: err, filePath }, 'Failed to send file');
      res.status(500).json({
        success: false,
        error: {
          code: 'FILE_SEND_ERROR',
          message: 'Failed to send file',
        },
      });
    }
  });
};

export const sendJSON = (
  res: Response,
  data: unknown,
  filename = 'data.json'
): void => {
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
  res.send(JSON.stringify(data, null, 2));
};

export const sendCSV = (
  res: Response,
  csvContent: string,
  filename = 'data.csv'
): void => {
  res.setHeader('Content-Type', 'text/csv');
  res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
  res.send(csvContent);
};

// Cache control helpers
export const setCacheHeaders = (
  res: Response,
  maxAge = 300, // 5 minutes default
  isPrivate = true
): void => {
  const cacheControl = isPrivate
    ? `private, max-age=${maxAge}`
    : `public, max-age=${maxAge}`;

  res.setHeader('Cache-Control', cacheControl);
  res.setHeader('ETag', `"${Date.now()}"`);
};

export const setNoCacheHeaders = (res: Response): void => {
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');
};

import { z } from 'zod';

export interface BilingualField {
  base: string;
  en?: string;
  fr?: string;
}

export interface BilingualSchemaOptions {
  requireBilingual?: boolean;
  defaultLanguage?: 'en' | 'fr';
}

/**
 * Creates a bilingual schema for a field that has base, English, and French versions
 */
export function createBilingualSchema(
  fieldName: string,
  baseSchema: z.ZodTypeAny,
  options: BilingualSchemaOptions = {},
): Record<string, z.ZodTypeAny> {
  const { requireBilingual = false } = options;

  const schema: Record<string, z.ZodTypeAny> = {
    [fieldName]: baseSchema,
  };

  if (requireBilingual) {
    schema[`${fieldName}En`] = baseSchema;
    schema[`${fieldName}Fr`] = baseSchema;
  } else {
    schema[`${fieldName}En`] = baseSchema.optional();
    schema[`${fieldName}Fr`] = baseSchema.optional();
  }

  return schema;
}

/**
 * Creates a bilingual object schema with multiple fields
 */
export function createBilingualObjectSchema<T extends Record<string, z.ZodTypeAny>>(
  fields: T,
  options: BilingualSchemaOptions = {},
): z.ZodObject<T & Record<string, z.ZodTypeAny>> {
  const schemaFields: Record<string, z.ZodTypeAny> = {};

  Object.entries(fields).forEach(([fieldName, fieldSchema]) => {
    Object.assign(schemaFields, createBilingualSchema(fieldName, fieldSchema, options));
  });

  return z.object(schemaFields) as z.ZodObject<T & Record<string, z.ZodTypeAny>>;
}

/**
 * Helper to create common bilingual schemas
 */
export const bilingualSchemas = {
  // String field with bilingual support
  string: (
    fieldName: string,
    options?: BilingualSchemaOptions & { min?: number; max?: number },
  ): Record<string, z.ZodTypeAny> => {
    let schema = z.string();
    if (options?.min !== undefined && options.min !== null && options.min > 0) {
schema = schema.min(options.min);
}
    if (options?.max !== undefined && options.max !== null && options.max > 0) {
schema = schema.max(options.max);
}
    return createBilingualSchema(fieldName, schema, options);
  },

  // Required string with bilingual support
  requiredString: (
    fieldName: string,
    options?: BilingualSchemaOptions & { min?: number; max?: number },
  ): Record<string, z.ZodTypeAny> => {
    let schema = z.string().min(1, `${fieldName} is required`);
    if (options?.min !== undefined && options.min !== null && options.min > 0) {
schema = schema.min(options.min);
}
    if (options?.max !== undefined && options.max !== null && options.max > 0) {
schema = schema.max(options.max);
}
    return createBilingualSchema(fieldName, schema, options);
  },

  // Optional text field with bilingual support
  text: (fieldName: string, options?: BilingualSchemaOptions): Record<string, z.ZodTypeAny> => createBilingualSchema(fieldName, z.string().optional(), options),

  // Email field (usually not bilingual, but included for completeness)
  email: (fieldName = 'email'): Record<string, z.ZodTypeAny> => ({
    [fieldName]: z.string().email('Invalid email address'),
  }),

  // Date field
  date: (fieldName: string): Record<string, z.ZodTypeAny> => ({
    [fieldName]: z
      .string()
      .datetime()
      .or(z.date())
      .transform((val) => new Date(val)),
  }),

  // Number field
  number: (fieldName: string, options?: { min?: number; max?: number }): Record<string, z.ZodTypeAny> => {
    let schema = z.number();
    if (options?.min !== undefined) {
schema = schema.min(options.min);
}
    if (options?.max !== undefined) {
schema = schema.max(options.max);
}
    return { [fieldName]: schema };
  },

  // Boolean field
  boolean: (fieldName: string): Record<string, z.ZodTypeAny> => ({
    [fieldName]: z.boolean(),
  }),

  // Enum field
  enum: <T extends readonly [string, ...string[]]>(fieldName: string, values: T): Record<string, z.ZodTypeAny> => ({
    [fieldName]: z.enum(values),
  }),
};

/**
 * Merges multiple schema objects into one
 */
export function mergeSchemas(
  ...schemas: Record<string, z.ZodTypeAny>[]
): z.ZodObject<Record<string, z.ZodTypeAny>> {
  const merged = schemas.reduce((acc, schema) => ({ ...acc, ...schema }), {});
  return z.object(merged);
}

/**
 * Creates a schema that validates bilingual data consistency
 */
export function createBilingualValidation(
  fieldName: string,
  options?: {
    requireAtLeastOne?: boolean;
    requireAll?: boolean;
  },
) {
  return z
    .object({
      [fieldName]: z.string().optional(),
      [`${fieldName}En`]: z.string().optional(),
      [`${fieldName}Fr`]: z.string().optional(),
    })
    .refine(
      (data) => {
        const base = data[fieldName];
        const en = data[`${fieldName}En`];
        const fr = data[`${fieldName}Fr`];

        if (options?.requireAll) {
          return (base && base !== '') && (en && en !== '') && (fr && fr !== '');
        }

        if (options?.requireAtLeastOne) {
          return (base && base !== '') || (en && en !== '') || (fr && fr !== '');
        }

        return true;
      },
      {
        message: options?.requireAll
          ? `All versions of ${fieldName} are required`
          : options?.requireAtLeastOne
            ? `At least one version of ${fieldName} is required`
            : undefined,
      },
    );
}

/**
 * Example usage:
 *
 * const subjectSchema = mergeSchemas(
 *   bilingualSchemas.requiredString('name'),
 *   bilingualSchemas.text('description'),
 *   bilingualSchemas.number('estHours', { min: 0 }),
 *   bilingualSchemas.date('targetDate')
 * );
 *
 * // Or with custom validation:
 * const activitySchema = createBilingualObjectSchema({
 *   title: z.string().min(1).max(100),
 *   description: z.string().optional(),
 *   duration: z.number().min(0).max(480),
 * });
 */

/**
 * Structured logging with correlation IDs
 * Provides consistent, searchable logs with request tracing
 */

import { AsyncLocalStorage } from 'async_hooks';
import { performance } from 'perf_hooks';

import type { Request, Response, NextFunction } from 'express';
import { v4 as uuidv4 } from 'uuid';
import { createLogger, format, transports } from 'winston';

// Async context for storing request metadata
const asyncLocalStorage = new AsyncLocalStorage<LogContext>();

export interface LogContext {
  correlationId: string;
  userId?: number;
  requestId?: string;
  sessionId?: string;
  traceId?: string;
  spanId?: string;
  parentSpanId?: string;
  startTime?: number;
  [key: string]: unknown;
}

export type LogMeta = Record<string, unknown>;

// Log levels
export enum LogLevel {
  ERROR = 'error',
  WARN = 'warn',
  INFO = 'info',
  HTTP = 'http',
  DEBUG = 'debug',
  TRACE = 'trace',
}

// Custom log format
const logFormat = format.combine(
  format.timestamp({
    format: 'YYYY-MM-DD HH:mm:ss.SSS',
  }),
  format.errors({ stack: true }),
  format.printf((info) => {
    const context = asyncLocalStorage.getStore();

    const log = {
      timestamp: info.timestamp,
      level: info.level,
      message: info.message,
      correlationId: context?.correlationId ?? 'no-correlation-id',
      ...(context?.userId !== undefined ? { userId: context.userId } : {}),
      ...(context?.requestId !== null && context?.requestId !== '' ? { requestId: context?.requestId } : {}),
      ...(context?.sessionId !== null && context?.sessionId !== '' ? { sessionId: context?.sessionId } : {}),
      ...(info.duration !== undefined ? { duration: info.duration } : {}),
      ...(info.meta !== undefined ? { meta: info.meta } : {}),
      ...(info.error !== undefined && info.error !== null && typeof info.error === 'object' && 'message' in info.error ? {
        error: {
          message: (info.error as Error).message,
          stack: (info.error as Error).stack,
          code: (info.error as { code?: string }).code,
        },
      } : {}),
    };

    // Add trace context if available
    if (context?.traceId !== null && context?.traceId !== '') {
      (log as Record<string, unknown>).trace = {
        traceId: context?.traceId,
        spanId: context?.spanId,
        parentSpanId: context?.parentSpanId,
      };
    }

    return JSON.stringify(log);
  }),
);

// Create logger instance
const logger = createLogger({
  level: process.env.LOG_LEVEL ?? 'info',
  format: logFormat,
  defaultMeta: {
    service: 'teaching-engine',
    environment: process.env.NODE_ENV ?? 'development',
    version: process.env.APP_VERSION ?? '1.0.0',
  },
  transports: [
    // Console transport for development
    new transports.Console({
      format: format.combine(format.colorize(), format.simple()),
      silent: process.env.NODE_ENV === 'test',
    }),
    // File transport for production
    ...(process.env.NODE_ENV === 'production'
      ? [
          new transports.File({
            filename: 'logs/error.log',
            level: 'error',
            maxsize: 10485760, // 10MB
            maxFiles: 5,
          }),
          new transports.File({
            filename: 'logs/combined.log',
            maxsize: 10485760, // 10MB
            maxFiles: 10,
          }),
        ]
      : []),
  ],
});

// Add structured logging methods
export class StructuredLogger {
  private static instance: StructuredLogger | undefined;

  static getInstance(): StructuredLogger {
    if (StructuredLogger.instance === undefined) {
      StructuredLogger.instance = new StructuredLogger();
    }
    return StructuredLogger.instance;
  }

  /**
   * Log with automatic context injection
   */
  log(level: LogLevel, message: string, meta?: LogMeta): void {
    const context = asyncLocalStorage.getStore();
    const duration = context?.startTime !== null && context?.startTime !== undefined
      ? Math.round(performance.now() - context.startTime)
      : undefined;

    logger.log(level, message, {
      meta,
      duration,
      ...(meta?.error !== undefined && meta.error !== null ? { error: meta.error } : {}),
    });
  }

  error(message: string, error?: Error, meta?: LogMeta): void {
    this.log(LogLevel.ERROR, message, { ...meta, error });
  }

  warn(message: string, meta?: LogMeta): void {
    this.log(LogLevel.WARN, message, meta);
  }

  info(message: string, meta?: LogMeta): void {
    this.log(LogLevel.INFO, message, meta);
  }

  http(message: string, meta?: LogMeta): void {
    this.log(LogLevel.HTTP, message, meta);
  }

  debug(message: string, meta?: LogMeta): void {
    this.log(LogLevel.DEBUG, message, meta);
  }

  trace(message: string, meta?: LogMeta): void {
    this.log(LogLevel.TRACE, message, meta);
  }

  /**
   * Create a child logger with additional context
   */
  child(additionalContext: Partial<LogContext>): StructuredLogger {
    const childLogger = new StructuredLogger();
    const parentContext = asyncLocalStorage.getStore() ?? {};

    // Merge contexts
    const childContext = { ...parentContext, ...additionalContext };

    // Return a proxy that runs in the child context
    return new Proxy(childLogger, {
      get(target, prop): unknown {
        if (typeof target[prop as keyof StructuredLogger] === 'function') {
          return (...args: unknown[]) => 
            asyncLocalStorage.run(childContext as LogContext, () => 
              (target[prop as keyof StructuredLogger] as (...args: unknown[]) => unknown)(
                ...args,
              )
            );
        }
        return target[prop as keyof StructuredLogger];
      },
    });
  }

  /**
   * Start a new span for distributed tracing
   */
  startSpan(name: string, parentSpanId?: string): string {
    const spanId = uuidv4();
    const context = asyncLocalStorage.getStore();

    if (context) {
      context.spanId = spanId;
      context.parentSpanId = parentSpanId ?? context.spanId;
    }

    this.trace(`Span started: ${name}`, { spanId, parentSpanId });
    return spanId;
  }

  /**
   * End a span and log duration
   */
  endSpan(spanId: string, name: string): void {
    const context = asyncLocalStorage.getStore();
    const duration = context?.startTime !== undefined && context.startTime !== null
      ? Math.round(performance.now() - context.startTime)
      : undefined;

    this.trace(`Span ended: ${name}`, { spanId, duration });
  }
}

/**
 * Express middleware for correlation ID and structured logging
 */
export function correlationMiddleware(req: Request, res: Response, next: NextFunction): void {
  // Generate or extract correlation ID
  const correlationId =
    (req.headers['x-correlation-id'] as string) ??
    (req.headers['x-request-id'] as string) ??
    uuidv4();

  // Generate request ID
  const requestId = uuidv4();

  // Extract trace context if available
  const traceId = (req.headers['x-trace-id'] as string) ?? uuidv4();
  const spanId = req.headers['x-span-id'] as string;
  const parentSpanId = req.headers['x-parent-span-id'] as string;

  // Create context
  const context: LogContext = {
    correlationId,
    requestId,
    traceId,
    spanId: spanId ?? uuidv4(),
    parentSpanId,
    startTime: performance.now(),
    userId: (req as Request & { user?: { id: number } }).user?.id,
    sessionId: (req as Request & { session?: { id: string } }).session?.id,
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.headers['user-agent'],
  };

  // Store context in async storage
  asyncLocalStorage.run(context, () => {
    // Add correlation ID to response headers
    res.setHeader('X-Correlation-ID', correlationId);
    res.setHeader('X-Request-ID', requestId);
    res.setHeader('X-Trace-ID', traceId);

    // Log request
    const structuredLogger = StructuredLogger.getInstance();
    structuredLogger.http(`${req.method} ${req.path}`, {
      query: req.query,
      body: req.method !== 'GET' ? sanitizeBody(req.body) : undefined,
      headers: sanitizeHeaders(req.headers),
    });

    // Log response
    const originalSend = res.send;
    res.send = function (data: unknown): Response {
      res.send = originalSend;

      const duration = context.startTime !== undefined && context.startTime !== null ? Math.round(performance.now() - context.startTime) : 0;

      structuredLogger.http(`${req.method} ${req.path} ${res.statusCode}`, {
        statusCode: res.statusCode,
        duration,
        responseSize: Buffer.byteLength(JSON.stringify(data)),
      });

      return res.send(data);
    };

    next();
  });
}

/**
 * Sanitize request body to remove sensitive data
 */
function sanitizeBody(body: unknown): unknown {
  if (!body || typeof body !== 'object') {
    return body;
  }

  const sensitiveFields = ['password', 'token', 'secret', 'apiKey', 'creditCard'];
  const sanitized = { ...(body as Record<string, unknown>) };

  for (const field of sensitiveFields) {
    if (sanitized[field] !== undefined && sanitized[field] !== null) {
      sanitized[field] = '[REDACTED]';
    }
  }

  return sanitized;
}

/**
 * Sanitize headers to remove sensitive data
 */
function sanitizeHeaders(headers: unknown): unknown {
  if (!headers || typeof headers !== 'object') {
    return headers;
  }

  const sensitiveHeaders = ['authorization', 'cookie', 'x-api-key'];
  const sanitized = { ...(headers as Record<string, unknown>) };

  for (const header of sensitiveHeaders) {
    if (sanitized[header] !== undefined && sanitized[header] !== null) {
      sanitized[header] = '[REDACTED]';
    }
  }

  return sanitized;
}

/**
 * Run function with logging context
 */
export async function withLoggingContext<T>(
  context: Partial<LogContext>,
  fn: () => Promise<T>,
): Promise<T> {
  return asyncLocalStorage.run({ ...asyncLocalStorage.getStore(), ...context } as LogContext, fn);
}

/**
 * Get current logging context
 */
export function getLoggingContext(): LogContext | undefined {
  return asyncLocalStorage.getStore();
}

/**
 * Express error handler with structured logging
 */
export function errorLoggingMiddleware(
  err: Error,
  req: Request,
  res: Response,
  next: NextFunction,
): void {
  const structuredLogger = StructuredLogger.getInstance();

  structuredLogger.error('Unhandled error', err, {
    statusCode: res.statusCode,
    path: req.path,
    method: req.method,
  });

  // Continue to next error handler
  next(err);
}

// Export singleton instance
export const structuredLogger = StructuredLogger.getInstance();

/**
 * Type guard utilities for safe type checking and conversion
 */

/**
 * Safely extracts error message from unknown error types
 */
export function getErrorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }
  return String(error);
}

/**
 * Type guard to check if a value is a Record<string, unknown>
 */
export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Type guard to check if an object has a specific array property
 */
export function hasArrayProperty<K extends string>(
  obj: unknown,
  prop: K
): obj is Record<K, unknown[]> {
  return (
    isRecord(obj) &&
    prop in obj &&
    Array.isArray(obj[prop])
  );
}

/**
 * Type guard to check if an object has a specific property
 */
export function hasProperty<K extends string>(
  obj: unknown,
  prop: K
): obj is Record<K, unknown> {
  return isRecord(obj) && prop in obj;
}

/**
 * Safely parse JSON with optional default value
 */
export function safeJsonParse<T = unknown>(
  json: string,
  defaultValue?: T
): T | undefined {
  try {
    return JSON.parse(json) as T;
  } catch {
    return defaultValue;
  }
}

/**
 * Convert unknown value to Record<string, unknown> safely
 */
export function toRecord(value: unknown): Record<string, unknown> {
  if (isRecord(value)) {
    return value;
  }
  return {};
}

/**
 * Type guard for checking if a value is a string
 */
export function isString(value: unknown): value is string {
  return typeof value === 'string';
}

/**
 * Type guard for checking if a value is a number
 */
export function isNumber(value: unknown): value is number {
  return typeof value === 'number' && !isNaN(value);
}

/**
 * Type guard for checking if a value is an array
 */
export function isArray<T = unknown>(value: unknown): value is T[] {
  return Array.isArray(value);
}

/**
 * Safely access nested property with type checking
 */
export function getNestedProperty<T>(
  obj: unknown,
  path: string[],
  defaultValue?: T
): T | undefined {
  let current: unknown = obj;

  for (const key of path) {
    if (!isRecord(current) || !(key in current)) {
      return defaultValue;
    }
    current = current[key];
  }

  return current as T;
}

/**
 * Type guard for Express-like request objects
 */
export interface RequestLike {
  body?: unknown;
  params?: unknown;
  query?: unknown;
  headers?: unknown;
  user?: unknown;
}

export function isRequestLike(value: unknown): value is RequestLike {
  return isRecord(value);
}

/**
 * Extract typed body from request
 */
export function getTypedBody<T>(req: RequestLike): T | undefined {
  if (req.body !== null && req.body !== undefined) {
    return req.body as T;
  }
  return undefined;
}

/**
 * Extract typed params from request
 */
export function getTypedParams<T extends Record<string, string>>(
  req: RequestLike
): T | undefined {
  if (isRecord(req.params)) {
    return req.params as T;
  }
  return undefined;
}

/**
 * Extract typed query from request
 */
export function getTypedQuery<T extends Record<string, string | string[]>>(
  req: RequestLike
): T | undefined {
  if (isRecord(req.query)) {
    return req.query as T;
  }
  return undefined;
}

/**
 * Type guards and utility functions for type safety
 */

import type { AppError } from '../types/http';

/**
 * Check if a value is defined (not null or undefined)
 */
export function isDefined<T>(value: T | null | undefined): value is T {
  return value !== null && value !== undefined;
}

/**
 * Check if a value is a non-empty string
 */
export function isNonEmptyString(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0;
}

/**
 * Check if a value is a number
 */
export function isNumber(value: unknown): value is number {
  return typeof value === 'number' && !isNaN(value);
}

/**
 * Check if a value is a positive number
 */
export function isPositiveNumber(value: unknown): value is number {
  return isNumber(value) && value > 0;
}

/**
 * Check if error is an AppError
 */
export function isAppError(error: unknown): error is AppError {
  return (
    error instanceof Error &&
    'statusCode' in error &&
    'code' in error &&
    'isOperational' in error &&
    isNumber((error as { statusCode?: unknown }).statusCode) &&
    typeof (error as { code?: unknown }).code === 'string' &&
    typeof (error as { isOperational?: unknown }).isOperational === 'boolean'
  );
}

/**
 * Check if error has a message property
 */
export function hasErrorMessage(error: unknown): error is { message: string } {
  return (
    typeof error === 'object' &&
    error !== null &&
    'message' in error &&
    typeof (error as { message?: unknown }).message === 'string'
  );
}

/**
 * Safe error message extraction
 */
export function getErrorMessage(error: unknown): string {
  if (hasErrorMessage(error)) {
    return error.message;
  }
  if (typeof error === 'string') {
    return error;
  }
  return 'Unknown error';
}

/**
 * Safe error logging formatter
 */
export function formatErrorForLogging(error: unknown): string | undefined {
  if (error === null || error === undefined) {
    return undefined;
  }
  if (hasErrorMessage(error)) {
    return error.message;
  }
  if (typeof error === 'string') {
    return error;
  }
  try {
    return JSON.stringify(error);
  } catch {
    return String(error);
  }
}

/**
 * Type guard for objects with specific property
 */
export function hasProperty<K extends string>(
  obj: unknown,
  key: K
): obj is Record<K, unknown> {
  return (
    typeof obj === 'object' &&
    obj !== null &&
    key in obj
  );
}

/**
 * Type guard for arrays
 */
export function isArray<T>(value: unknown): value is T[] {
  return Array.isArray(value);
}

/**
 * Type guard for non-empty arrays
 */
export function isNonEmptyArray<T>(value: unknown): value is T[] {
  return Array.isArray(value) && value.length > 0;
}

/**
 * Safe property access
 */
export function getProperty<T, K extends keyof T>(
  obj: T | null | undefined,
  key: K
): T[K] | undefined {
  return obj?.[key];
}

/**
 * Safe property access with default value
 */
export function getPropertyOrDefault<T, K extends keyof T>(
  obj: T | null | undefined,
  key: K,
  defaultValue: T[K]
): T[K] {
  return obj?.[key] ?? defaultValue;
}

/* eslint-disable @typescript-eslint/no-explicit-any */
import type { Request, Response, NextFunction } from 'express';
import { z } from 'zod';

// Common field schemas
export const commonSchemas = {
  // IDs
  id: z.union([z.string().cuid(), z.number().int().positive()]),
  numericId: z.number().int().positive(),
  stringId: z.string().cuid(),

  // Strings
  title: z.string().min(1).max(200).trim(),
  description: z.string().max(5000).trim().optional(),
  shortText: z.string().max(100).trim(),
  longText: z.string().max(10000).trim(),
  email: z.string().email().toLowerCase().trim(),
  url: z.string().url().trim(),

  // Numbers
  grade: z.number().int().min(1).max(12),
  percentage: z.number().min(0).max(100),
  rating: z.number().int().min(1).max(5),
  duration: z.number().int().min(0), // minutes

  // Dates
  date: z.string().datetime().or(z.date()),
  futureDate: z.string().datetime().or(z.date()).refine(
    (date) => new Date(date) > new Date(),
    'Date must be in the future'
  ),
  pastDate: z.string().datetime().or(z.date()).refine(
    (date) => new Date(date) < new Date(),
    'Date must be in the past'
  ),
  dateRange: z.object({
    start: z.string().datetime().or(z.date()),
    end: z.string().datetime().or(z.date()),
  }).refine(
    (range) => new Date(range.end) > new Date(range.start),
    'End date must be after start date'
  ),

  // Common enums
  language: z.enum(['en', 'fr']),
  subject: z.string().min(1).max(50),
  assessmentType: z.enum(['diagnostic', 'formative', 'summative']),

  // Pagination
  pagination: z.object({
    page: z.number().int().min(1).default(1),
    pageSize: z.number().int().min(1).max(100).default(20),
    sortBy: z.string().optional(),
    sortOrder: z.enum(['asc', 'desc']).default('asc'),
  }),

  // Filters
  dateFilter: z.object({
    from: z.string().datetime().or(z.date()).optional(),
    to: z.string().datetime().or(z.date()).optional(),
  }),

  // Arrays
  stringArray: z.array(z.string()),
  numberArray: z.array(z.number()),
  tags: z.array(z.string().min(1).max(50)).max(20),
};

// Query parameter schemas
export const querySchemas = {
  // Basic pagination
  paginationQuery: z.object({
    page: z.string().regex(/^\d+$/).transform(Number).pipe(z.number().int().min(1)).default('1'),
    pageSize: z.string().regex(/^\d+$/).transform(Number).pipe(z.number().int().min(1).max(100)).default('20'),
  }),

  // Extended pagination with sorting
  sortablePaginationQuery: z.object({
    page: z.string().regex(/^\d+$/).transform(Number).pipe(z.number().int().min(1)).default('1'),
    pageSize: z.string().regex(/^\d+$/).transform(Number).pipe(z.number().int().min(1).max(100)).default('20'),
    sortBy: z.string().optional(),
    sortOrder: z.enum(['asc', 'desc']).default('asc'),
  }),

  // Date range query
  dateRangeQuery: z.object({
    from: z.string().datetime().optional(),
    to: z.string().datetime().optional(),
    dateField: z.string().default('createdAt'),
  }),

  // Search query
  searchQuery: z.object({
    q: z.string().min(1).max(100).optional(),
    fields: z.string().transform(s => s.split(',')).optional(),
  }),
};

// Validation helpers
export const validateId = (id: string | number): number => {
  const result = commonSchemas.numericId.safeParse(
    typeof id === 'string' ? parseInt(id, 10) : id
  );

  if (!result.success) {
    throw new Error(`Invalid ID: ${id}`);
  }

  return result.data;
};

export const validatePagination = (query: unknown): { page: number; pageSize: number } => {
  const defaultPagination = { page: 1, pageSize: 20 };

  if (query === null || query === undefined || typeof query !== 'object') {
    return defaultPagination;
  }

  const queryObj = query as Record<string, unknown>;

  return {
    page: Math.max(1, parseInt(String(queryObj.page), 10) || 1),
    pageSize: Math.min(100, Math.max(1, parseInt(String(queryObj.pageSize), 10) || 20)),
  };
};

export const validateDateRange = (from?: string | Date, to?: string | Date): { from?: Date; to?: Date } => {
  const dates: { from?: Date; to?: Date } = {};

  if (from !== undefined && from !== '') {
    dates.from = new Date(from);
    if (isNaN(dates.from.getTime())) {
      throw new Error('Invalid from date');
    }
  }

  if (to !== undefined && to !== '') {
    dates.to = new Date(to);
    if (isNaN(dates.to.getTime())) {
      throw new Error('Invalid to date');
    }
  }

  if (dates.from && dates.to !== undefined && dates.from > dates.to) {
    throw new Error('From date must be before to date');
  }

  return dates;
};

// Transform helpers
export const transformToNumber = (value: unknown): number | undefined => {
  if (value === undefined || value === null || value === '') {
    return undefined;
  }

  const num = typeof value === 'string' ? parseFloat(value) : Number(value);
  return isNaN(num) ? undefined : num;
};

export const transformToBoolean = (value: unknown): boolean => {
  if (typeof value === 'boolean') {
    return value;
  }
  if (typeof value === 'string') {
    return value.toLowerCase() === 'true' || value === '1';
  }
  return value !== null && value !== undefined && value !== false && value !== 0 && value !== '';
};

export const transformToArray = (value: unknown): string[] => {
  if (Array.isArray(value)) {
    return value.filter((item): item is string => typeof item === 'string');
  }
  if (typeof value === 'string') {
    return value.split(',').map(s => s.trim()).filter(s => s !== '');
  }
  return [];
};

// Sanitization helpers
export const sanitizeHtml = (html: string): string => 
  // Basic HTML sanitization - in production, use a library like DOMPurify
   html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<iframe[^>]*>[\s\S]*?<\/iframe>/gi, '')
    .replace(/on\w+\s*=\s*["'][^"']*["']/gi, '')
    .trim()
;

export const sanitizeFilename = (filename: string): string => filename
    .replace(/[^a-zA-Z0-9.-]/g, '_')
    .replace(/_{2,}/g, '_')
    .toLowerCase();

// Custom validators
export const isValidGrade = (grade: number): boolean => Number.isInteger(grade) && grade >= 1 && grade <= 12;

export const isValidAcademicYear = (year: string): boolean => {
  const pattern = /^\d{4}-\d{4}$/;
  if (!pattern.test(year)) {
    return false;
  }

  const [start, end] = year.split('-').map(Number);
  return end === start + 1;
};

export const isValidCanadianPostalCode = (code: string): boolean => {
  const pattern = /^[A-Za-z]\d[A-Za-z][ -]?\d[A-Za-z]\d$/;
  return pattern.test(code);
};

// Schema builders
export const buildFilterSchema = <T extends z.ZodRawShape>(
  baseSchema: z.ZodObject<T>,
  additionalFields?: z.ZodRawShape
): z.ZodObject<z.ZodRawShape> => baseSchema.extend({
    ...commonSchemas.pagination.shape,
    ...commonSchemas.dateFilter.shape,
    search: z.string().optional(),
    ...additionalFields,
  });

export const buildCreateSchema = <T extends z.ZodRawShape>(
  baseSchema: z.ZodObject<T>,
  requiredFields: (keyof T)[]
): z.ZodObject<z.ZodRawShape> => {
  const shape: z.ZodRawShape = {};

  for (const key of requiredFields) {
    shape[key as string] = baseSchema.shape[key] as z.ZodTypeAny;
  }

  return z.object(shape);
};

export const buildUpdateSchema = <T extends z.ZodRawShape>(
  baseSchema: z.ZodObject<T>
): z.ZodObject<z.ZodRawShape> => {
  const shape: z.ZodRawShape = {};

  for (const [key, schema] of Object.entries(baseSchema.shape)) {
    shape[key] = (schema).optional();
  }

  return z.object(shape);
};

// Validation middleware factory
export const createValidationMiddleware = <T>(schema: z.ZodSchema<T>): ((req: Request, res: Response, next: NextFunction) => void) => (req: Request, res: Response, next: NextFunction): void => {
    try {
      const data: Record<string, unknown> = {
        ...(typeof req.body === 'object' && req.body !== null ? req.body as Record<string, unknown> : {}),
        ...(req.query as Record<string, unknown>),
        ...(req.params as Record<string, unknown>),
      };

      const result = schema.parse(data);
      (req as Request & { validated: T }).validated = result;
      next();
    } catch (_error: unknown) {
      if (_error instanceof z.ZodError) {
        res.status(400).json({
          success: false,
          error: {
            code: 'VALIDATION_ERROR',
            message: 'Validation failed',
            details: _error.errors,
          },
        });
      } else {
        next(_error);
      }
    }
  };

import { createHash } from 'crypto';

import axios from 'axios';
import { JSDOM } from 'jsdom';

import { logger } from '../logger.js';

interface CacheEntry {
  html: string;
  timestamp: number;
}

export class WebFetch {
  private cache = new Map<string, CacheEntry>();
  private readonly cacheTime = 15 * 60 * 1000; // 15 minutes
  private readonly userAgent = 'Mozilla/5.0 (compatible; TeachingEngine/2.0; +https://teaching-engine.com)';

  async fetch(url: string): Promise<string> {
    // Check cache first
    const cacheKey = this.getCacheKey(url);
    const cached = this.cache.get(cacheKey);

    if (cached && Date.now() - cached.timestamp < this.cacheTime) {
      return cached.html;
    }

    try {
      // Fetch with axios
      const response = await axios.get(url, {
        headers: {
          'User-Agent': this.userAgent,
          'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
          'Accept-Language': 'en-US,en;q=0.5',
          'Accept-Encoding': 'gzip, deflate',
          'Connection': 'keep-alive',
          'Upgrade-Insecure-Requests': '1'
        },
        timeout: 30000, // 30 seconds
        maxRedirects: 5,
        validateStatus: (status) => status < 400
      });

      const html = response.data as string;

      // Cache the result
      this.cache.set(cacheKey, {
        html,
        timestamp: Date.now()
      });

      // Clean old cache entries
      this.cleanCache();

      return html;
    } catch (_error) {
      logger.error({ error: _error, url }, 'Error fetching URL');

      // Try with JSDOM as fallback for JavaScript-heavy sites
      try {
        const dom = await JSDOM.fromURL(url, {
          userAgent: this.userAgent,
          pretendToBeVisual: true,
          runScripts: 'dangerously',
          resources: 'usable'
        });

        // Wait a bit for JavaScript to load
        await new Promise(resolve => setTimeout(resolve, 3000));

        const html = dom.serialize();

        // Cache the result
        this.cache.set(cacheKey, {
          html,
          timestamp: Date.now()
        });

        dom.window.close();
        return html;
      } catch (fallbackError) {
        logger.error({ error: fallbackError, url }, 'Fallback fetch also failed');
        throw new Error(`Unable to fetch content from ${url}`);
      }
    }
  }

  private getCacheKey(url: string): string {
    return createHash('md5').update(url).digest('hex');
  }

  private cleanCache(): void {
    const now = Date.now();
    const expiredKeys: string[] = [];

    for (const [key, entry] of this.cache.entries()) {
      if (now - entry.timestamp > this.cacheTime) {
        expiredKeys.push(key);
      }
    }

    for (const key of expiredKeys) {
      this.cache.delete(key);
    }
  }

  // Utility method to extract text content from HTML
  extractText(html: string, selector?: string): string {
    const dom = new JSDOM(html);
    const {document} = dom.window;

    if (selector !== undefined && selector !== '') {
      const element = document.querySelector(selector);
      return element?.textContent?.trim() ?? '';
    }

    // Remove script and style elements
    const scripts = document.querySelectorAll('script, style');
    scripts.forEach(el => {
 el.remove(); 
});

    return document.body.textContent?.trim() ?? '';
  }

  // Utility method to extract meta information
  extractMeta(html: string): Record<string, string> {
    const dom = new JSDOM(html);
    const {document} = dom.window;
    const meta: Record<string, string> = {};

    // Extract common meta tags
    const metaTags = document.querySelectorAll('meta[name], meta[property]');
    metaTags.forEach(tag => {
      const name = tag.getAttribute('name') ?? tag.getAttribute('property');
      const content = tag.getAttribute('content');
      if (name !== null && name !== '' && content !== null && content !== '') {
        meta[name] = content;
      }
    });

    // Extract title
    const title = document.querySelector('title');
    if (title) {
      meta.title = title.textContent ?? '';
    }

    return meta;
  }
}

